INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832e48cf-3779-446c-80ec-b233f37fc140', '奉和中書常舍人晚秋集賢院即事寄贈徐薛二侍御', '奉和中书常舍人晚秋集賢院即事寄贈徐薛二侍御', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["漢家金馬署，帝座紫微郎。","圖籍淩羣玉，歌詩冠柏梁。","陰陰萬年樹，肅肅五經堂。","揮翰忘朝食，研精待夕陽。","晴空露盤迥，秋月瑣窗涼。","遠興生斑鬢，高情寄縹囊。","葳蕤雙鸑鷟，夙昔並翱翔。","汲冢同刊謬，蓬山共補亡。","差池摧羽翮，流落限江湘。","禁省一分袂，昊天三雨霜。","石渠遺跡滿，水國暮雲長。","早晚朝宣室，歸時道路光。"]', '["漢家金马署，帝座紫微郎。","圖籍淩羣玉，歌诗冠柏梁。","陰陰万年樹，肅肅五經堂。","揮翰忘朝食，研精待夕陽。","晴空露盤迥，秋月瑣窗涼。","远兴生斑鬢，高情寄縹囊。","葳蕤雙鸑鷟，夙昔並翱翔。","汲冢同刊謬，蓬山共補亡。","差池摧羽翮，流落限江湘。","禁省一分袂，昊天三雨霜。","石渠遺跡满，水国暮云长。","早晚朝宣室，归时道路光。"]', '诗', 'shi', '', NULL, '奉和中書常舍人晚秋集賢院即事寄贈徐薛二侍御 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61db6a81-c908-43d0-881f-39f3f84a3461', '江寧詶鄭縣劉少府兄贈別作', '江寧詶鄭縣劉少府兄贈別作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["往年脫縫掖，接武仕關西。","結綬腰章並，趨堦手板齊。","仙山不用買，朋酒日相攜。","抵掌誇潭壑，忘情向組珪。","事遷時既往，年長跡逾暌。","何爲青雲器，猶嗟濁水泥。","役牽方遠別，道在或先迷。","莫見良田晚，遭時亦杖藜。"]', '["往年脫縫掖，接武仕关西。","結綬腰章並，趨堦手板齊。","仙山不用買，朋酒日相携。","抵掌誇潭壑，忘情向組珪。","事遷时既往，年长跡逾暌。","何爲青云器，猶嗟濁水泥。","役牽方远別，道在或先迷。","莫见良田晚，遭时亦杖藜。"]', '诗', 'shi', '', NULL, '江寧詶鄭縣劉少府兄贈別作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be0153d0-60a7-4035-a5d9-a01497bdb9c0', '送李賓客荆南迎親', '送李賓客荆南迎親', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["宗室劉中壘，文場謝客兒。","當爲天北斗，曾使海西陲。","毛節精誠著，銅樓羽翼施。","還申供帳別，言赴倚門期。","恩渥霑行李，晨昏在路岐。","君親兩報遂，不敢議傷離。"]', '["宗室劉中壘，文場謝客兒。","當爲天北斗，曾使海西陲。","毛節精誠著，銅楼羽翼施。","還申供帳別，言赴倚门期。","恩渥霑行李，晨昏在路岐。","君親兩報遂，不敢議傷離。"]', '诗', 'shi', '', NULL, '送李賓客荆南迎親 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41747bf8-cf9f-4631-944c-e1a6f0ebfdd5', '題玉潭', '題玉潭', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["碧玉徒強名，冰壺難比德。","唯當寂照心，可並奫淪色。"]', '["碧玉徒強名，冰壺难比德。","唯當寂照心，可並奫淪色。"]', '诗', 'shi', '', NULL, '題玉潭 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51cdcbf-e375-4c64-bc0f-9759b137879c', '海上懷華中舊遊寄鄭縣劉少府造渭南王少府崟', '海上懷华中旧游寄鄭縣劉少府造渭南王少府崟', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["涼風臺上三峯月，不夜城邊萬里沙。","離別莫言關塞遠，夢魂長在子真家。"]', '["涼风台上三峯月，不夜城邊万里沙。","離別莫言关塞远，梦魂长在子真家。"]', '诗', 'shi', '', NULL, '海上懷華中舊遊寄鄭縣劉少府造渭南王少府崟 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36bb241a-a915-45e0-9b78-b35e3565f255', '和虞部韋郎中尋楊駙馬不遇', '和虞部韋郎中尋楊駙马不遇', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["金屋瓊臺蕭史家，暮春三月渭州花。","到君仙洞不相見，謂已吹簫乘早霞。"]', '["金屋瓊台蕭史家，暮春三月渭州花。","到君仙洞不相见，謂已吹簫乘早霞。"]', '诗', 'shi', '', NULL, '和虞部韋郎中尋楊駙馬不遇 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4a7b6b-cd6e-4b4a-a3e1-f58c25911dc6', '李張皇甫閻權等數公並有送別之作見寄因答', '李張皇甫閻權等數公並有送別之作见寄因答', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["洞庭正波蘋葉衰，豈是秦吳遠別時。","謝君篋中綺端贈，何以報之長相思。"]', '["洞庭正波蘋葉衰，豈是秦吳远別时。","謝君篋中綺端贈，何以報之长相思。"]', '诗', 'shi', '', NULL, '李張皇甫閻權等數公並有送別之作見寄因答 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125a3c91-2481-42b4-8cdb-e1116d5b22df', '將還越留別豫章諸公', '將還越留別豫章諸公', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["客鳥倦飛思舊林，裴徊猶戀衆花陰。","他時相憶雙航葦，莫問吳江深不深。"]', '["客鸟倦飞思旧林，裴徊猶戀衆花陰。","他时相憶雙航葦，莫问吳江深不深。"]', '诗', 'shi', '', NULL, '將還越留別豫章諸公 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3aa535-b4a9-4a3c-abe3-0a8217c51513', '送別荆南張判官', '送別荆南張判官', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["輶車駱馬往從誰，夢浦蘭臺日更遲。","欲識桃花最多處，前程問取武陵兒。"]', '["輶车駱马往從誰，梦浦蘭台日更遲。","欲識桃花最多处，前程问取武陵兒。"]', '诗', 'shi', '', NULL, '送別荆南張判官 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a2f4ad1-f9dd-474c-978b-2a5f2aac14ab', '陪王員外北樓宴待月', '陪王員外北楼宴待月', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["勸酒論心夜不疲，含情有待問誰思。","佇看晴月澄澄影，來照江樓酩酊時。"]', '["勸酒論心夜不疲，含情有待问誰思。","佇看晴月澄澄影，来照江楼酩酊时。"]', '诗', 'shi', '', NULL, '陪王員外北樓宴待月 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401da7ba-8be2-4e91-93c1-fdf06a263095', '垂花塢醉後戲題', '垂花塢醉後戲題', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["紫蔓青條拂酒壺，落花時與竹風俱。","歸時自負花前醉，笑向鯈魚問樂無。"]', '["紫蔓青條拂酒壺，落花时與竹风俱。","归时自負花前醉，笑向鯈鱼问乐無。"]', '诗', 'shi', '', NULL, '垂花塢醉後戲題 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2673236-e35c-4802-8273-f79590114b7d', '題劉相公三湘圖', '題劉相公三湘圖', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["昔別醉衡霍，邇來憶南州。","今朝平津邸，兼得瀟湘遊。","稍辨郢門樹，依然芳杜洲。","微明三巴峽，咫尺萬里流。","飛鳥不知倦，遠帆生暮愁。","涔陽指天末，北渚空悠悠。","枕上見漁父，坐中常狎鷗。","誰言魏闕下，自有東山幽。"]', '["昔別醉衡霍，邇来憶南州。","今朝平津邸，兼得瀟湘游。","稍辨郢门樹，依然芳杜洲。","微明三巴峽，咫尺万里流。","飞鸟不知倦，远帆生暮愁。","涔陽指天末，北渚空悠悠。","枕上见漁父，坐中常狎鷗。","誰言魏闕下，自有东山幽。"]', '诗', 'shi', '', NULL, '題劉相公三湘圖 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4352f313-6ae9-4e57-8f12-b5e3c54d24da', '長安逢故人', '长安逢故人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["數年音信斷，不意在長安。","馬上相逢久，人中欲認難。","一官今嬾道，雙鬢竟羞看。","莫問生涯事，只應持釣竿。"]', '["數年音信斷，不意在长安。","马上相逢久，人中欲認难。","一官今嬾道，雙鬢竟羞看。","莫问生涯事，只應持釣竿。"]', '诗', 'shi', '', NULL, '長安逢故人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c626a7e-db6f-486b-a128-a7f5434ad1b7', '送韋湛判官', '送韋湛判官', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["高閣晴江上，重陽古戍閑。","聊因送歸客，更此望鄉山。","惜別心能醉，經秋鬢自斑。","臨流興不盡，惆悵水雲間。"]', '["高閣晴江上，重陽古戍闲。","聊因送归客，更此望乡山。","惜別心能醉，經秋鬢自斑。","臨流兴不尽，惆悵水云间。"]', '诗', 'shi', '', NULL, '送韋湛判官 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0991c7-fe35-495d-b0a7-093dfdfad29d', '送長沙韋明府', '送长沙韋明府', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["秋入長沙縣，蕭條旅宦心。","煙波連桂水，官舍映楓林。","雲日楚天暮，沙汀白露深。","遙知訟堂裏，佳政在鳴琴。"]', '["秋入长沙縣，蕭條旅宦心。","煙波連桂水，官舍映楓林。","云日楚天暮，沙汀白露深。","遙知訟堂裏，佳政在鳴琴。"]', '诗', 'shi', '', NULL, '送長沙韋明府 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c35019-b59c-4591-8698-27d7aac7b54d', '送孫願', '送孫願', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["悠然富春客，憶與暮潮歸。","擢第人多羨，如君獨步稀。","亂流江渡淺，遠色海山微。","若訪新安路，嚴陵有釣磯。"]', '["悠然富春客，憶與暮潮归。","擢第人多羨，如君独步稀。","亂流江渡淺，远色海山微。","若訪新安路，嚴陵有釣磯。"]', '诗', 'shi', '', NULL, '送孫願 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44353dc5-b941-4156-b12d-1a7e9292aa41', '送林宗配雷州', '送林宗配雷州', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["昨日三峰尉，今朝萬里人。","平生任孤直，豈是不防身。","海霧多爲瘴，山雷乍作隣。","遙憐北戶月，與子獨相親。"]', '["昨日三峰尉，今朝万里人。","平生任孤直，豈是不防身。","海霧多爲瘴，山雷乍作隣。","遙怜北戶月，與子独相親。"]', '诗', 'shi', '', NULL, '送林宗配雷州 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf729a2-07fc-4621-acb3-3a9fc74ff455', '送洪州李別駕之任', '送洪州李別駕之任', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["南去秋江遠，孤舟興自多。","能將流水引，更入洞庭波。","夏口帆初上，潯陽鴈正過。","知音在霄漢，佐郡豈蹉跎。"]', '["南去秋江远，孤舟兴自多。","能將流水引，更入洞庭波。","夏口帆初上，潯陽鴈正過。","知音在霄漢，佐郡豈蹉跎。"]', '诗', 'shi', '', NULL, '送洪州李別駕之任 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df59c4e-610f-4bad-8ff7-6c8393ec4e4a', '送楊中丞和蕃', '送楊中丞和蕃', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["錦車登隴日，邊草正萋萋。","舊好尋君長，新愁聽鼓鼙。","河源飛鳥外，雪嶺大荒西。","漢壘今猶在，遙知路不迷。"]', '["錦车登隴日，邊草正萋萋。","旧好尋君长，新愁听鼓鼙。","河源飞鸟外，雪嶺大荒西。","漢壘今猶在，遙知路不迷。"]', '诗', 'shi', '', NULL, '送楊中丞和蕃 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799ce706-685f-4340-940f-21a76b7e6f15', '送李將軍赴定州', '送李將軍赴定州', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["雙旌漢飛將，萬里授橫戈。","春色臨邊盡，黃雲出塞多。","鼓鼙悲絕漠，烽戍隔長河。","莫斷陰山路，天驕已請和。"]', '["雙旌漢飞將，万里授橫戈。","春色臨邊尽，黄云出塞多。","鼓鼙悲絕漠，烽戍隔长河。","莫斷陰山路，天驕已請和。"]', '诗', 'shi', '', NULL, '送李將軍赴定州 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3866facf-d8d2-4f4e-b7c4-eefbc12bfdea', '關羽祠送高員外還荆州', '关羽祠送高員外還荆州', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["將軍稟天姿，義勇冠今昔。","走馬百戰場，一劍萬人敵。","雖爲感恩者，竟是思歸客。","流落荆巫間，裴回故鄉隔。","離筵對祠宇，灑酒暮天碧。","去去勿復言，銜悲向陳跡。"]', '["將軍稟天姿，義勇冠今昔。","走马百戰場，一劍万人敵。","雖爲感恩者，竟是思归客。","流落荆巫间，裴回故乡隔。","離筵对祠宇，灑酒暮天碧。","去去勿复言，銜悲向陳跡。"]', '诗', 'shi', '', NULL, '關羽祠送高員外還荆州 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b76447-7491-4ec6-bedc-22de0ae8dd59', '送張南史', '送張南史', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["雨餘深巷靜，獨酌送殘春。","車馬雖嫌僻，鶯花不棄貧。","蟲絲黏戶網，鼠跡印牀塵。","借問山陽會，如今有幾人。"]', '["雨餘深巷静，独酌送殘春。","车马雖嫌僻，鶯花不棄貧。","蟲絲黏戶網，鼠跡印牀塵。","借问山陽會，如今有幾人。"]', '诗', 'shi', '', NULL, '送張南史 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facdc456-bd32-442c-b870-3a9cd87a879d', '送奚賈歸吳', '送奚賈归吳', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["東南富春渚，曾是謝公遊。","今日奚生去，新安江正秋。","水清迎過客，霜葉落行舟。","遙想赤亭下，聞猨應夜愁。"]', '["东南富春渚，曾是謝公游。","今日奚生去，新安江正秋。","水清迎過客，霜葉落行舟。","遙想赤亭下，闻猨應夜愁。"]', '诗', 'shi', '', NULL, '送奚賈歸吳 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9a3697-2850-4441-877f-8c1ac378dab7', '送陸員外赴潮州', '送陸員外赴潮州', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["含香臺上客，剖竹海邊州。","楚地多歸信，閩溪足亂流。","今朝永嘉興，重見謝公遊。"]', '["含香台上客，剖竹海邊州。","楚地多归信，閩溪足亂流。","今朝永嘉兴，重见謝公游。"]', '诗', 'shi', '', NULL, '送陸員外赴潮州 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06203cef-1dc5-4d60-9ef7-a4bf4306c730', '送裴補闕入河南幕', '送裴補闕入河南幕', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["皎然青瑣客，何事動行軒。","苦節酬知己，清吟去掖垣。","秋城臨海樹，寒月上營門。","鄒魯詩書國，應無鼙鼓喧。"]', '["皎然青瑣客，何事动行軒。","苦節酬知己，清吟去掖垣。","秋城臨海樹，寒月上營门。","鄒魯诗书国，應無鼙鼓喧。"]', '诗', 'shi', '', NULL, '送裴補闕入河南幕 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fcfc7b-7b77-4775-8301-70d3beefa3e0', '送韓司直路出延陵', '送韓司直路出延陵', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["遊吳還適越，來往任風波。","復送王孫去，其如春草何。","岸明殘雪在，潮滿夕陽多。","季子留遺廟，停舟試一過。"]', '["游吳還適越，来往任风波。","复送王孫去，其如春草何。","岸明殘雪在，潮满夕陽多。","季子留遺廟，停舟試一過。"]', '诗', 'shi', '', NULL, '送韓司直路出延陵 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d2ba1b-92a3-4fdd-8bb6-491b279a4b47', '盩厔縣鄭礒宅送錢大', '盩厔縣鄭礒宅送錢大', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["暮蟬不可聽，落葉豈堪聞。","共是悲秋客，那知此路分。","荒城背流水，遠鴈入寒雲。","陶令門前菊，餘花可贈君。"]', '["暮蟬不可听，落葉豈堪闻。","共是悲秋客，那知此路分。","荒城背流水，远鴈入寒云。","陶令门前菊，餘花可贈君。"]', '诗', 'shi', '', NULL, '盩厔縣鄭礒宅送錢大 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba215b86-2100-483d-8bb8-58abf31709ab', '送元詵還丹陽別業', '送元詵還丹陽別業', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["已知成傲吏，復見解朝衣。","應向丹陽郭，秋山獨掩扉。","草堂連古寺，江日動晴暉。","一別滄州遠，蘭橈幾歲歸。"]', '["已知成傲吏，复见解朝衣。","應向丹陽郭，秋山独掩扉。","草堂連古寺，江日动晴暉。","一別滄州远，蘭橈幾歲归。"]', '诗', 'shi', '', NULL, '送元詵還丹陽別業 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6c7722-14bb-40ea-a754-b8ac46534678', '送崔侍御往容州宣慰', '送崔侍御往容州宣慰', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["秦原獨立望湘川，擊隼南飛向楚天。","奉詔不言空問俗，清時因得訪遺賢。","荆門曉色兼梅雨，桂水春風過客船。","疇昔常聞陸賈說，故人今日豈徒然。"]', '["秦原独立望湘川，擊隼南飞向楚天。","奉詔不言空问俗，清时因得訪遺賢。","荆门晓色兼梅雨，桂水春风過客船。","疇昔常闻陸賈说，故人今日豈徒然。"]', '诗', 'shi', '', NULL, '送崔侍御往容州宣慰 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b02442f-be4c-4965-a763-503d3f99023a', '朱方南郭留別皇甫冉', '朱方南郭留別皇甫冉', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["縈迴楓葉岸，留滯木蘭橈。","吳岫新經雨，江天正落潮。","故人勞見愛，行客自無憀。","若問前程事，孤雲入剡遙。"]', '["縈迴楓葉岸，留滯木蘭橈。","吳岫新經雨，江天正落潮。","故人勞见愛，行客自無憀。","若问前程事，孤云入剡遙。"]', '诗', 'shi', '', NULL, '朱方南郭留別皇甫冉 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914b38c9-9904-4894-a10a-a5d9803c9d83', '贈張五諲歸濠州別業', '贈張五諲归濠州別業', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["常知罷官意，果與世人疎。","復此涼風起，仍聞濠上居。","故山期採菊，秋水憶觀魚。","一去蓬蒿徑，羨君閑有餘。"]', '["常知罷官意，果與世人疎。","复此涼风起，仍闻濠上居。","故山期採菊，秋水憶观鱼。","一去蓬蒿徑，羨君闲有餘。"]', '诗', 'shi', '', NULL, '贈張五諲歸濠州別業 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4cca5d-f01c-48c8-afd0-ddd6cf7c3e1f', '送王司馬赴潤州', '送王司马赴潤州', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["暫屈文爲吏，聊將祿代耕。","金陵且不遠，山水復多名。","楚塞因高出，寒潮入夜生。","離心逐春草，直到建康城。"]', '["暫屈文爲吏，聊將祿代耕。","金陵且不远，山水复多名。","楚塞因高出，寒潮入夜生。","離心逐春草，直到建康城。"]', '诗', 'shi', '', NULL, '送王司馬赴潤州 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d300505-0b4a-460a-8131-e4a414dadd6d', '留盧秦卿', '留盧秦卿', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["知有前期在，歡如此夜中。","無將故人酒，不及古淳風。"]', '["知有前期在，歡如此夜中。","無將故人酒，不及古淳风。"]', '诗', 'shi', '', NULL, '留盧秦卿 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15757ed7-bb83-49be-9336-db817939006c', '贈強山人', '贈強山人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["或掉輕舟或杖藜。","尋常適意釣前溪，草堂竹逕在何處。","落日孤煙寒渚西。"]', '["或掉轻舟或杖藜。","尋常適意釣前溪，草堂竹逕在何处。","落日孤煙寒渚西。"]', '诗', 'shi', '', NULL, '贈強山人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ebb4c2-6e32-43ac-b721-dda9be7dabd9', '贈韋司直', '贈韋司直', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["聞君感歎二毛初，舊友相依萬里餘。","烽火有時驚暫定，甲兵無處可安居。","客來吳地星霜久，家在平陵音信疎。","昨日風光還入戶，登山臨水意何如。"]', '["闻君感歎二毛初，旧友相依万里餘。","烽火有时驚暫定，甲兵無处可安居。","客来吳地星霜久，家在平陵音信疎。","昨日风光還入戶，登山臨水意何如。"]', '诗', 'shi', '', NULL, '贈韋司直 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48ca87c0-1499-4530-94e1-144e1683b4b8', '石城館酬王將軍', '石城館酬王將軍', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["誰能繡衣客，肯駐木蘭舟。","連雁沙邊至，孤城江上秋。","歸帆背南浦，楚塞入西樓。","何處看離思，滄波日夜流。"]', '["誰能繡衣客，肯駐木蘭舟。","連雁沙邊至，孤城江上秋。","归帆背南浦，楚塞入西楼。","何处看離思，滄波日夜流。"]', '诗', 'shi', '', NULL, '石城館酬王將軍 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19965c5-9574-43ff-9158-2f61b6a3fde7', '酬王季友題半日村別業兼呈李明府', '酬王季友題半日村別業兼呈李明府', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["村映寒原日已斜，煙生密竹早歸鴉。","長溪南路當羣岫，半景東隣照數家。","門通小徑連芳草，馬飲春泉踏淺沙。","欲待主人林上月，還思潘岳縣中花。"]', '["村映寒原日已斜，煙生密竹早归鴉。","长溪南路當羣岫，半景东隣照數家。","门通小徑連芳草，马饮春泉踏淺沙。","欲待主人林上月，還思潘岳縣中花。"]', '诗', 'shi', '', NULL, '酬王季友題半日村別業兼呈李明府 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b2a614-15f4-44f8-a2b8-4227751cfadc', '酬二十八秀才見寄', '酬二十八秀才见寄', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["昨夜山月好，故人果相思。","清光到枕上，嫋嫋涼風時。","永意能在我，惜無攜手期。"]', '["昨夜山月好，故人果相思。","清光到枕上，嫋嫋涼风时。","永意能在我，惜無携手期。"]', '诗', 'shi', '', NULL, '酬二十八秀才見寄 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1251d11-7f7a-4b19-8e2b-eb0df33c004f', '冬夕寄青龍寺源公', '冬夕寄青龙寺源公', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["歛屨入寒竹，安禪過漏聲。","高松殘子落，深井凍痕生。","罷磬風枝動，懸燈雪屋明。","何當招我宿，乘月上方行。"]', '["歛屨入寒竹，安禪過漏声。","高松殘子落，深井凍痕生。","罷磬风枝动，懸灯雪屋明。","何當招我宿，乘月上方行。"]', '诗', 'shi', '', NULL, '冬夕寄青龍寺源公 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad3309f-985c-4852-8bba-d6ef2a5ebc11', '塞下曲', '塞下曲', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["寶刀塞下兒，身經百戰曾百勝。","壯心竟未嫖姚知，白草山頭日初沒。","黃沙戍下悲歌發，蕭條夜靜邊風吹，獨倚營門望秋月。"]', '["寶刀塞下兒，身經百戰曾百勝。","壯心竟未嫖姚知，白草山头日初沒。","黄沙戍下悲歌發，蕭條夜静邊风吹，独倚營门望秋月。"]', '诗', 'shi', '', NULL, '塞下曲 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952b7249-b535-4d68-b2b7-feb2623a414d', '柏林寺南望', '柏林寺南望', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["溪上遙聞精舍鐘，泊舟微徑度深松。","青山霽後雲猶在，畫出東南四五峰。"]', '["溪上遙闻精舍鐘，泊舟微徑度深松。","青山霽後云猶在，畫出东南四五峰。"]', '诗', 'shi', '', NULL, '柏林寺南望 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bbcafe3-b343-4428-9a88-0b961af72d26', '宿杜判官江樓', '宿杜判官江楼', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["適楚豈吾願，思歸秋向深。","故人江樓月，永夜千里心。","葉落覺鄉夢，鳥啼驚越吟。","寥寥更何有，斷續空城砧。"]', '["適楚豈吾願，思归秋向深。","故人江楼月，永夜千里心。","葉落覺乡梦，鸟啼驚越吟。","寥寥更何有，斷續空城砧。"]', '诗', 'shi', '', NULL, '宿杜判官江樓 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91cc371b-f47e-4e0c-b611-134d953616c4', '春宴王補闕城東別業', '春宴王補闕城东別業', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["柳陌乍隨州勢轉，花源忽傍竹陰開。","能將瀑水清人境，直取流鶯送酒杯。","山下古松當綺席，簷前片雨滴春苔。","地主同聲復同舍，留歡不畏夕陽催。"]', '["柳陌乍隨州勢轉，花源忽傍竹陰开。","能將瀑水清人境，直取流鶯送酒杯。","山下古松當綺席，簷前片雨滴春苔。","地主同声复同舍，留歡不畏夕陽催。"]', '诗', 'shi', '', NULL, '春宴王補闕城東別業 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51dd970-bcea-4dc2-8de1-d0a31dc7c95c', '郢城西樓吟', '郢城西楼吟', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["連山盡處水縈迴，山上戍門臨水開。","朱欄直下一百丈，日暖遊鱗自相向。","昔人愛險閉層城，今日愛閑江復清。","沙洲楓岸無來客，草綠花紅山鳥鳴。"]', '["連山尽处水縈迴，山上戍门臨水开。","朱欄直下一百丈，日暖游鱗自相向。","昔人愛險閉層城，今日愛闲江复清。","沙洲楓岸無来客，草綠花紅山鸟鳴。"]', '诗', 'shi', '', NULL, '郢城西樓吟 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a93b0ca-ca2c-40b8-998a-39850248bc99', '聽鄰家吹笙', '听鄰家吹笙', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["鳳吹聲如隔綵霞，不知牆外是誰家。","重門深鎖無尋處，疑有碧桃千樹花。"]', '["鳳吹声如隔綵霞，不知牆外是誰家。","重门深鎖無尋处，疑有碧桃千樹花。"]', '诗', 'shi', '', NULL, '聽鄰家吹笙 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39922da-9ec5-488a-a87a-93bfdd9d6ea6', '登丹陽北樓', '登丹陽北楼', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["寒臯那可望，旅望又初還。","迢遰高樓上，蕭條曠野閑。","暮晴依遠水，秋興屬連山。","浮客時相見，霜凋動翠顏。"]', '["寒臯那可望，旅望又初還。","迢遰高楼上，蕭條曠野闲。","暮晴依远水，秋兴屬連山。","浮客时相见，霜凋动翠顏。"]', '诗', 'shi', '', NULL, '登丹陽北樓 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b3a0df-11b4-46ae-bc44-f58f19a51447', '題精舍寺', '題精舍寺', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["石林精舍武溪東，夜扣禪關謁遠公。","月在上方諸品靜，僧持半偈萬緣空。","秋山竟日聞猨嘯，落木寒泉聽不窮。","惟有雙峰最高頂，此心期與故人同。"]', '["石林精舍武溪东，夜扣禪关謁远公。","月在上方諸品静，僧持半偈万緣空。","秋山竟日闻猨嘯，落木寒泉听不窮。","惟有雙峰最高頂，此心期與故人同。"]', '诗', 'shi', '', NULL, '題精舍寺 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcea2070-7313-49ff-b095-27b364df6406', '雙林寺謁傅大士', '雙林寺謁傅大士', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["草露經前代，津梁及後人。","此方今示滅，何國更分身。","月色空知夜，松陰不記春。","猶憐下生日，應在一微塵。"]', '["草露經前代，津梁及後人。","此方今示滅，何国更分身。","月色空知夜，松陰不記春。","猶怜下生日，應在一微塵。"]', '诗', 'shi', '', NULL, '雙林寺謁傅大士 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23f740f-f87b-46dd-82a8-2a01423525a6', '題尹真人祠', '題尹真人祠', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["窅窅雲旗去不還，陰陰祠宇閉空山。","我來始悟丹青妙，稽首如逢冰雪顏。"]', '["窅窅云旗去不還，陰陰祠宇閉空山。","我来始悟丹青妙，稽首如逢冰雪顏。"]', '诗', 'shi', '', NULL, '題尹真人祠 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e1562f-9efe-497c-b540-7bd7031022e0', '山中即事', '山中即事', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["入谷多春興，乘舟棹碧潯。","山雲昨夜雨，溪水曉來深。"]', '["入谷多春兴，乘舟棹碧潯。","山云昨夜雨，溪水晓来深。"]', '诗', 'shi', '', NULL, '山中即事 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba844f7-b593-42d1-95f1-ebfe27f2a077', '湘夫人二首 一', '湘夫人二首 一', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["蛾眉對湘水，遙哭蒼梧山。","萬乘既已歿，孤舟誰忍還。","至今楚竹上，猶有淚痕斑。"]', '["蛾眉对湘水，遙哭蒼梧山。","万乘既已歿，孤舟誰忍還。","至今楚竹上，猶有泪痕斑。"]', '诗', 'shi', '', NULL, '湘夫人二首 一 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25be9870-8794-4702-bdb9-8ed2a7df8051', '湘夫人二首 二', '湘夫人二首 二', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["南有涔陽路，渺渺多新愁。","桂酒神降時，迴風江上秋。","彩雲忽無處，碧水空安流。"]', '["南有涔陽路，渺渺多新愁。","桂酒神降时，迴风江上秋。","彩云忽無处，碧水空安流。"]', '诗', 'shi', '', NULL, '湘夫人二首 二 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45cd0d5e-957f-4ee4-bf93-35b8935f526c', '蓋少府新除江南尉問風俗', '蓋少府新除江南尉问风俗', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["聞君作尉向江潭，吳越風煙到自諳。","客路尋常隨竹影，人家大底傍山嵐。","緣溪花木偏宜遠，避地衣冠盡向南。","惟有夜猨啼海樹，思鄉望國意難堪。"]', '["闻君作尉向江潭，吳越风煙到自諳。","客路尋常隨竹影，人家大底傍山嵐。","緣溪花木偏宜远，避地衣冠尽向南。","惟有夜猨啼海樹，思乡望国意难堪。"]', '诗', 'shi', '', NULL, '蓋少府新除江南尉問風俗 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75bd5871-849f-4d90-9931-4eb7e033abff', '春宴張舍人宅', '春宴張舍人宅', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["嬾尋芳草徑，來接侍臣筵。","山色知殘雨，牆陰覺暮天。","鶯啼漢宮柳，花隔杜陵煙。","地與東城接，春光醉目前。"]', '["嬾尋芳草徑，来接侍臣筵。","山色知殘雨，牆陰覺暮天。","鶯啼漢宮柳，花隔杜陵煙。","地與东城接，春光醉目前。"]', '诗', 'shi', '', NULL, '春宴張舍人宅 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8367b4a1-da94-463e-9ccf-5417a0cb5735', '寄李袁州桑落酒', '寄李袁州桑落酒', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["色比瓊漿猶嫩，香同甘露仍春。","十千提攜一斗，遠送瀟湘故人。"]', '["色比瓊漿猶嫩，香同甘露仍春。","十千提携一斗，远送瀟湘故人。"]', '诗', 'shi', '', NULL, '寄李袁州桑落酒 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1cb1f50-691a-4546-b23b-71c7084c58ef', '贈萬生下第還吳', '贈万生下第還吳', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["直道多不偶，美才應息機。","灞陵春欲暮，雲海獨言歸。","爲客成白首，入門嗟布衣。","蓴羹若可憶，慙出掩柴扉。"]', '["直道多不偶，美才應息機。","灞陵春欲暮，云海独言归。","爲客成白首，入门嗟布衣。","蓴羹若可憶，慙出掩柴扉。"]', '诗', 'shi', '', NULL, '贈萬生下第還吳 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de75be6-b6a5-44ce-b263-459a14d6d20b', '送大德講時河東徐明府招', '送大德講时河东徐明府招', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["遠近作人天，王城指日邊。","宰君迎說法，童子伴隨緣。","到處花爲雨，行時杖出泉。","今宵松月下，開閣想安禪。"]', '["远近作人天，王城指日邊。","宰君迎说法，童子伴隨緣。","到处花爲雨，行时杖出泉。","今宵松月下，开閣想安禪。"]', '诗', 'shi', '', NULL, '送大德講時河東徐明府招 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6fd205b-a5b4-415a-87f4-ad87b918ebbb', '赴無錫別靈一上人', '赴無錫別靈一上人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["高僧本姓竺，開士舊名林。","一入春山裏，千峰不可尋。","新年芳草徧，度日白雲深。","欲問微官去，懸知訝此心。"]', '["高僧本姓竺，开士旧名林。","一入春山裏，千峰不可尋。","新年芳草徧，度日白云深。","欲问微官去，懸知訝此心。"]', '诗', 'shi', '', NULL, '赴無錫別靈一上人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe072a84-b2e7-41a4-8045-54607d073e09', '送粲上人兼寄梁鎮員外', '送粲上人兼寄梁鎮員外', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["季月還鄉獨未能，林行溪宿厭層冰。","尺素欲傳三署客，雪山愁送五天僧。","連空朔氣橫秦苑，滿目寒雲隔灞陵。","借問從來香積寺，何時攜手更同登。"]', '["季月還乡独未能，林行溪宿厭層冰。","尺素欲傳三署客，雪山愁送五天僧。","連空朔氣橫秦苑，满目寒云隔灞陵。","借问從来香積寺，何时携手更同登。"]', '诗', 'shi', '', NULL, '送粲上人兼寄梁鎮員外 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17f33bdc-0ce3-4527-960c-69cd20198276', '送韋逸人歸鍾山', '送韋逸人归鍾山', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["逸人歸路遠，弟子出山迎。","服藥顏猶駐，耽書癖已成。","柴扉多歲月，藜杖見公卿。","更作儒林傳，應須載姓名。"]', '["逸人归路远，弟子出山迎。","服藥顏猶駐，耽书癖已成。","柴扉多歲月，藜杖见公卿。","更作儒林傳，應須載姓名。"]', '诗', 'shi', '', NULL, '送韋逸人歸鍾山 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202ec2f2-f2a3-41f5-a9f0-b4ecd577f38b', '登無錫北樓', '登無錫北楼', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["秋興因危堞，歸心過遠山。","風霜征鴈早，江海旅人還。","驛樹寒仍密，漁舟晚更閑。","仲宣何所賦，秪欲滯柴關。"]', '["秋兴因危堞，归心過远山。","风霜征鴈早，江海旅人還。","驛樹寒仍密，漁舟晚更闲。","仲宣何所賦，秪欲滯柴关。"]', '诗', 'shi', '', NULL, '登無錫北樓 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb8dfe5-540c-4e2e-b12a-085273a6cf99', '和王相公題中書叢竹寄上元相公', '和王相公題中书叢竹寄上元相公', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["多時仙掖裏，色並翠琅玕。","幽意含煙月，清陰庇蕙蘭。","枝繁宜露重，葉老愛天寒。","竟日雙鸞止，孤吟爲一看。"]', '["多时仙掖裏，色並翠琅玕。","幽意含煙月，清陰庇蕙蘭。","枝繁宜露重，葉老愛天寒。","竟日雙鸾止，孤吟爲一看。"]', '诗', 'shi', '', NULL, '和王相公題中書叢竹寄上元相公 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ddf299-92d9-437e-b92a-266fe1091086', '酬蕭二十七侍御初秋言懷', '酬蕭二十七侍御初秋言懷', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["楚客秋多興，江林月漸生。","細枝涼葉動，極浦早鴻聲。","勝賞睽前夕，新詩報遠情。","曲高慙和者，惆悵閉寒城。"]', '["楚客秋多兴，江林月漸生。","細枝涼葉动，極浦早鴻声。","勝賞睽前夕，新诗報远情。","曲高慙和者，惆悵閉寒城。"]', '诗', 'shi', '', NULL, '酬蕭二十七侍御初秋言懷 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca536e1-2a86-411f-a29a-99353ae5f202', '奉和杜相公益昌路作', '奉和杜相公益昌路作', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["春半梁山正落花，台衡受律向天涯。","南去猨聲傍雙節，西來江色遶千家。","風吹畫角孤城曉，林映蛾眉片月斜。","已見廟謨能喻蜀，新文更喜報金華。"]', '["春半梁山正落花，台衡受律向天涯。","南去猨声傍雙節，西来江色遶千家。","风吹畫角孤城晓，林映蛾眉片月斜。","已见廟謨能喻蜀，新文更喜報金华。"]', '诗', 'shi', '', NULL, '奉和杜相公益昌路作 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f9fd2f-e6d6-4e29-b10f-b50072e676fc', '賦得長洲苑送李惠', '賦得长洲苑送李惠', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["草深那可訪，地久阻相傳。","散漫三秋雨，疎蕪萬里煙。","都迷採蘭處，強記館娃年。","客有遊吳者，臨風思眇然。"]', '["草深那可訪，地久阻相傳。","散漫三秋雨，疎蕪万里煙。","都迷採蘭处，強記館娃年。","客有游吳者，臨风思眇然。"]', '诗', 'shi', '', NULL, '賦得長洲苑送李惠 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1808a4-793f-4410-a2fb-9a537bae879c', '別房士清', '別房士清', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["世路還相見，偏堪淚滿衣。","那能郢門別，獨向鄴城歸。","平楚看蓬轉，連山望鳥飛。","蒼蒼歲陰暮，況復惜馳暉。"]', '["世路還相见，偏堪泪满衣。","那能郢门別，独向鄴城归。","平楚看蓬轉，連山望鸟飞。","蒼蒼歲陰暮，況复惜驰暉。"]', '诗', 'shi', '', NULL, '別房士清 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3fdefb-adbd-4caa-a860-765af1cfd941', '送彭偃房由赴朝因寄錢大郎中李十七舍人', '送彭偃房由赴朝因寄錢大郎中李十七舍人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["衰病已經年，西峰望楚天。","風光欺鬢髮，秋色換山川。","寂寞浮雲外，支離漢水邊。","平生故人遠，君去話潸然。"]', '["衰病已經年，西峰望楚天。","风光欺鬢髮，秋色換山川。","寂寞浮云外，支離漢水邊。","平生故人远，君去話潸然。"]', '诗', 'shi', '', NULL, '送彭偃房由赴朝因寄錢大郎中李十七舍人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e38478-98e6-4836-addf-14101678d2a4', '送李遂之越', '送李遂之越', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["未習風波事，初爲東越遊。","露霑湖草晚，月照海山秋。","梅市門何處，蘭亭水向流。","西興待潮信，落日滿孤舟。"]', '["未習风波事，初爲东越游。","露霑湖草晚，月照海山秋。","梅市门何处，蘭亭水向流。","西兴待潮信，落日满孤舟。"]', '诗', 'shi', '', NULL, '送李遂之越 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d50e67d-f380-4e9d-9fe4-826a985dfd54', '送鄭正則徐州行營', '送鄭正則徐州行營', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["從軍非隴頭，師在古徐州。","氣勁三河卒，功全萬戶侯。","元戎閫外略，才子握中籌。","莫聽關山曲，還生塞上愁。"]', '["從軍非隴头，師在古徐州。","氣勁三河卒，功全万戶侯。","元戎閫外略，才子握中籌。","莫听关山曲，還生塞上愁。"]', '诗', 'shi', '', NULL, '送鄭正則徐州行營 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6210ab6-af10-41ce-b847-ad41e94aaf8a', '送錢拾遺歸兼寄劉校書', '送錢拾遺归兼寄劉校书', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["墟落歲陰暮，桑榆煙景昏。","蟬聲靜空館，雨色隔秋原。","歸客不可望，悠然林外村。","終當報芸閣，攜手醉柴門。"]', '["墟落歲陰暮，桑榆煙景昏。","蟬声静空館，雨色隔秋原。","归客不可望，悠然林外村。","終當報芸閣，携手醉柴门。"]', '诗', 'shi', '', NULL, '送錢拾遺歸兼寄劉校書 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbccad2c-0218-4e85-8b44-16128ba951de', '送郴縣裴明府之任兼充宣慰', '送郴縣裴明府之任兼充宣慰', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["白蘋楚水三湘遠，芳草秦城二月初。","連鴈北飛看欲盡，孤舟南去意何如。","渡江野老思求瘼，候館郴人憶下車。","別後天涯何所寄，故交惟有袖中書。"]', '["白蘋楚水三湘远，芳草秦城二月初。","連鴈北飞看欲尽，孤舟南去意何如。","渡江野老思求瘼，候館郴人憶下车。","別後天涯何所寄，故交惟有袖中书。"]', '诗', 'shi', '', NULL, '送郴縣裴明府之任兼充宣慰 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c2c954-dd46-4b72-8609-ff75bef665c1', '送李敖湖南書記', '送李敖湖南书記', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["憐君才與阮家同，掌記能資亞相雄。","入楚豈忘看淚竹，泊舟應自愛江楓。","誠知客夢煙波裏，肯厭猨鳴夜雨中。","莫信衡湘書不到，年年秋鴈過巴東。"]', '["怜君才與阮家同，掌記能資亞相雄。","入楚豈忘看泪竹，泊舟應自愛江楓。","誠知客梦煙波裏，肯厭猨鳴夜雨中。","莫信衡湘书不到，年年秋鴈過巴东。"]', '诗', 'shi', '', NULL, '送李敖湖南書記 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe59eb75-1737-4f12-be68-af8876fd47ff', '送麴司直', '送麴司直', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["曙雪蒼蒼兼曙雲，朔風煙鴈不堪聞。","貧交此別無他贈，唯有青山遠送君。"]', '["曙雪蒼蒼兼曙云，朔风煙鴈不堪闻。","貧交此別無他贈，唯有青山远送君。"]', '诗', 'shi', '', NULL, '送麴司直 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703f40c7-74fc-4155-972b-673b8742b5df', '送別', '送別', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["穆陵關上秋雲起，安陸城邊遠行子。","薄暮寒蟬三兩聲，迴頭故鄉千萬里。"]', '["穆陵关上秋云起，安陸城邊远行子。","薄暮寒蟬三兩声，迴头故乡千万里。"]', '诗', 'shi', '', NULL, '送別 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028b4cb8-66a0-4935-b7f5-b75760a688a1', '咸陽西樓別竇審', '咸陽西楼別竇審', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["西樓迴起寒原上，霽日遙分萬井間。","小苑城隅連渭水，離宮曙色近京關。","亭臯寂寞傷孤客，雲雪蕭條滿衆山。","時命如今猶未偶，辭君擬欲拂衣還。"]', '["西楼迴起寒原上，霽日遙分万井间。","小苑城隅連渭水，離宮曙色近京关。","亭臯寂寞傷孤客，云雪蕭條满衆山。","时命如今猶未偶，辞君擬欲拂衣還。"]', '诗', 'shi', '', NULL, '咸陽西樓別竇審 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d6ce47-371d-43d0-a96c-ffe83083892c', '聞蟬寄友人', '闻蟬寄友人', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["昨日始聞鶯，今朝蟬又鳴。","朱顏向華髮，定是幾年程。","故國白雲遠，閑居青草生。","因垂數行淚，書寄十年兄。"]', '["昨日始闻鶯，今朝蟬又鳴。","朱顏向华髮，定是幾年程。","故国白云远，闲居青草生。","因垂數行泪，书寄十年兄。"]', '诗', 'shi', '', NULL, '聞蟬寄友人 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd8425fc-1637-4f3d-8af1-c13dc740c6f8', '送李騎曹之靈武寧侍', '送李騎曹之靈武寧侍', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["一歲一歸寧，涼天數騎行。","河來當塞曲，山遠與沙平。","縱獵旗風卷，聽笳帳月生。","新鴻引寒色，迴日滿京城。"]', '["一歲一归寧，涼天數騎行。","河来當塞曲，山远與沙平。","縱獵旗风卷，听笳帳月生。","新鴻引寒色，迴日满京城。"]', '诗', 'shi', '', NULL, '送李騎曹之靈武寧侍 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3edd1919-8eaa-4a85-b05e-97f6f10a2d19', '馮翊西樓', '馮翊西楼', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["城上西樓倚暮天，樓中歸望正淒然。","近郭亂山橫古渡，野莊喬木帶新煙。","北風吹鴈聲能苦，遠客辭家月再圓。","陶令好文常對酒，相招一和白雲篇。"]', '["城上西楼倚暮天，楼中归望正淒然。","近郭亂山橫古渡，野莊喬木带新煙。","北风吹鴈声能苦，远客辞家月再圓。","陶令好文常对酒，相招一和白云篇。"]', '诗', 'shi', '', NULL, '馮翊西樓 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc565d9d-ab21-4e86-8a65-c222a0d21eb5', '郢城秋望', '郢城秋望', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["白首思歸歸不得，空山聞鴈鴈聲哀。","高城落日望西北，又見秋風逐水來。"]', '["白首思归归不得，空山闻鴈鴈声哀。","高城落日望西北，又见秋风逐水来。"]', '诗', 'shi', '', NULL, '郢城秋望 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1cee37-7c51-4168-bdfa-62f2a968c12f', '夜泊湘江', '夜泊湘江', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["湘山木落洞庭波，湘水連雲秋鴈多。","寂寞舟中誰借問，月明只自聽漁歌。"]', '["湘山木落洞庭波，湘水連云秋鴈多。","寂寞舟中誰借问，月明只自听漁歌。"]', '诗', 'shi', '', NULL, '夜泊湘江 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c03d44ee-9791-45a2-a9e7-f42e42065b2b', '留別常著', '留別常著', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["歲晏蒼郊蓬轉時，遊人相見說歸期。","宓君堂上能留客，明日還家應未遲。"]', '["歲晏蒼郊蓬轉时，游人相见说归期。","宓君堂上能留客，明日還家應未遲。"]', '诗', 'shi', '', NULL, '留別常著 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1541d8-c0ef-4732-8d77-3a87cc06b4fe', '送張光歸吳', '送張光归吳', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["看取庭蕪白露新，勸君不用久風塵。","秋來多見長安客，解愛鱸魚能幾人。"]', '["看取庭蕪白露新，勸君不用久风塵。","秋来多见长安客，解愛鱸鱼能幾人。"]', '诗', 'shi', '', NULL, '送張光歸吳 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16dbc4d3-1930-4f57-8d30-c358ec7ba315', '聞吹楊葉者二首 一', '闻吹楊葉者二首 一', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["妙吹楊葉動悲笳，胡馬迎風起恨賒。","若是鴈門寒月夜，此時應卷盡驚沙。"]', '["妙吹楊葉动悲笳，胡马迎风起恨賒。","若是鴈门寒月夜，此时應卷尽驚沙。"]', '诗', 'shi', '', NULL, '聞吹楊葉者二首 一 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5c77d4-1ce5-458f-bf76-648539c0a0b2', '聞吹楊葉者二首 二', '闻吹楊葉者二首 二', '63b8c7c6-78d9-48b0-8d3a-b9fec399c7b1', '唐', '["天生一藝更無倫，寥亮幽音妙入神。","吹向別離攀折處，當應合有斷腸人。"]', '["天生一藝更無倫，寥亮幽音妙入神。","吹向別離攀折处，當應合有斷腸人。"]', '诗', 'shi', '', NULL, '聞吹楊葉者二首 二 郎士元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39daba5b-8a7e-44f7-9f72-e2aa77337e3f', '潤州南郭留別', '潤州南郭留別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["縈迴楓葉岸，留滯木蘭橈。","吳岫新經雨，江天正落潮。","故人勞見愛，行客自無聊。","君問前程事，孤雲入剡遙。"]', '["縈迴楓葉岸，留滯木蘭橈。","吳岫新經雨，江天正落潮。","故人勞见愛，行客自無聊。","君问前程事，孤云入剡遙。"]', '诗', 'shi', '', NULL, '潤州南郭留別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0f4002-028c-4f2a-981a-44f1c13326a4', '祭張公洞二首 一', '祭張公洞二首 一', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["堯心知稼穡，精意遶山川。","風雨神祇應，笙鏞詔命傳。","沐蘭秪掃地，酌桂佇靈仙。","拂霧陳金策，焚香拜玉筵。"]', '["堯心知稼穡，精意遶山川。","风雨神祇應，笙鏞詔命傳。","沐蘭秪掃地，酌桂佇靈仙。","拂霧陳金策，焚香拜玉筵。"]', '诗', 'shi', '', NULL, '祭張公洞二首 一 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20c82da-8b24-4a6a-8594-e57bbcdf5bba', '祭張公洞二首 二', '祭張公洞二首 二', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["雲開小有洞，日出大羅天。","三鳥隨王母，雙童翊子先。","何時種核桃，幾度看桑田。","倏忽煙霞散，空巖騎吏旋。"]', '["云开小有洞，日出大羅天。","三鸟隨王母，雙童翊子先。","何时種核桃，幾度看桑田。","倏忽煙霞散，空巖騎吏旋。"]', '诗', 'shi', '', NULL, '祭張公洞二首 二 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fc442f0-cd4d-44c9-bfe9-009f2df80640', '臨平道贈同舟人', '臨平道贈同舟人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["遠山誰辨江南北，長路空隨樹淺深。","流蕩飄颻此何極，唯應行客共知心。"]', '["远山誰辨江南北，长路空隨樹淺深。","流蕩飄颻此何極，唯應行客共知心。"]', '诗', 'shi', '', NULL, '臨平道贈同舟人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2c6ee1-d73d-44cb-a0ad-c54aacc1a4c6', '巫山峽', '巫山峽', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["巫峽見巴東，迢迢出半空。","雲藏神女館，雨到楚王宮。","朝暮泉聲落，寒暄樹色同。","清猿不可聽，偏在九秋中。"]', '["巫峽见巴东，迢迢出半空。","云藏神女館，雨到楚王宮。","朝暮泉声落，寒暄樹色同。","清猿不可听，偏在九秋中。"]', '诗', 'shi', '', NULL, '巫山峽 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('251010ed-b2b6-4170-959e-58b4de7fb5a3', '長安路', '长安路', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["長安九城路，戚里五侯家。","結束趨平樂，聯翩抵狹斜。","高樓臨遠水，複道出繁花。","唯見相如宅，蓬門度歲華。"]', '["长安九城路，戚里五侯家。","結束趨平乐，聯翩抵狹斜。","高楼臨远水，複道出繁花。","唯见相如宅，蓬门度歲华。"]', '诗', 'shi', '', NULL, '長安路 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61b1601-9208-47f8-8478-79da59ab09c0', '送朱逸人', '送朱逸人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["時人多不見，出入五湖間。","寄酒全吾道，移家愛遠山。","更看秋草暮，欲共白雲還。","雖在風塵裹，陶潛身自閑。"]', '["时人多不见，出入五湖间。","寄酒全吾道，移家愛远山。","更看秋草暮，欲共白云還。","雖在风塵裹，陶潛身自闲。"]', '诗', 'shi', '', NULL, '送朱逸人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bd81f9-fb49-462f-a0be-035ca1619183', '西陵寄靈一上人', '西陵寄靈一上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["西陵遇風處，自古是通津。","終日空江上，雲山若待人。","汀洲寒事早，魚鳥興情新。","迴望山陰路，心中有所親。"]', '["西陵遇风处，自古是通津。","終日空江上，云山若待人。","汀洲寒事早，鱼鸟兴情新。","迴望山陰路，心中有所親。"]', '诗', 'shi', '', NULL, '西陵寄靈一上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a51837-2d7d-471e-8b98-fc0a61ef13e3', '赴無錫寄別靈一淨虛二上人雲門所居', '赴無錫寄別靈一淨虛二上人云门所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["高僧本姓竺，開士舊名林。","一入春山裏，千峰不可尋。","新年芳草徧，終日白雲深。","欲徇微官去，懸知訝此心。"]', '["高僧本姓竺，开士旧名林。","一入春山裏，千峰不可尋。","新年芳草徧，終日白云深。","欲徇微官去，懸知訝此心。"]', '诗', 'shi', '', NULL, '赴無錫寄別靈一淨虛二上人雲門所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a220432-9c40-4633-8366-b88899114fc7', '舟中送李八', '舟中送李八', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["詞客金門未有媒，遊吳適越任舟迴。","遠水迢迢分手去，天邊山色待人來。"]', '["词客金门未有媒，游吳適越任舟迴。","远水迢迢分手去，天邊山色待人来。"]', '诗', 'shi', '', NULL, '舟中送李八 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7552cc24-70f8-4885-8ff2-f5265e6391c4', '與張補闕王鍊師自徐方清路同舟南下於臺頭寺留別趙員外裴補闕同賦雜題一首', '與張補闕王鍊師自徐方清路同舟南下於台头寺留別趙員外裴補闕同賦杂題一首', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["朝朝春事晚，泛泛行舟遠。","淮海思無窮，悠揚煙景中。","幸將仙子去，復與故人同。","高枕隨流水，輕帆任遠風。","鐘聲野寺逈，草色故城空。","送別高臺上，裴回共惆悵。","懸知白日斜，定是猶相望。"]', '["朝朝春事晚，泛泛行舟远。","淮海思無窮，悠揚煙景中。","幸將仙子去，复與故人同。","高枕隨流水，轻帆任远风。","鐘声野寺逈，草色故城空。","送別高台上，裴回共惆悵。","懸知白日斜，定是猶相望。"]', '诗', 'shi', '', NULL, '與張補闕王鍊師自徐方清路同舟南下於臺頭寺留別趙員外裴補闕同賦雜題一首 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a36892-9b3b-4d19-a3fa-092096ccd1e5', '酬張二仲彝', '酬張二仲彝', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["吳洲見芳草，楚客動歸心。","屈宋鄉山古，荆衡煙雨深。","艱難十載別，羈旅四愁侵。","澧月通沅水，湘雲入桂林。","已看生白髮，當爲乏黃金。","江海時相見，唯聞梁甫吟。"]', '["吳洲见芳草，楚客动归心。","屈宋乡山古，荆衡煙雨深。","艱难十載別，羈旅四愁侵。","澧月通沅水，湘云入桂林。","已看生白髮，當爲乏黄金。","江海时相见，唯闻梁甫吟。"]', '诗', 'shi', '', NULL, '酬張二仲彝 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a656ee4a-a803-40a8-a06c-a935d5c630d4', '三月三日義興李明府後亭泛舟', '三月三日義兴李明府後亭泛舟', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江南煙景復如何，聞道新亭更可過。","處處蓻蘭春浦綠，萋萋藉草遠山多。","壺觴須就陶彭澤，時俗猶傳晉永和。","更使輕橈徐轉去，微風落日水增波。"]', '["江南煙景复如何，闻道新亭更可過。","处处蓻蘭春浦綠，萋萋藉草远山多。","壺觴須就陶彭澤，时俗猶傳晉永和。","更使轻橈徐轉去，微风落日水增波。"]', '诗', 'shi', '', NULL, '三月三日義興李明府後亭泛舟 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb1ff5ce-b5ff-475f-a307-b9c7740169d7', '少室山韋鍊師昇仙歌', '少室山韋鍊師昇仙歌', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["紅霞紫氣晝氳氳，絳節青幢迎少君。","忽從林下昇天去，空使時人禮白雲。"]', '["紅霞紫氣晝氳氳，絳節青幢迎少君。","忽從林下昇天去，空使时人禮白云。"]', '诗', 'shi', '', NULL, '少室山韋鍊師昇仙歌 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf798b9-3594-4320-bcbd-dfd9f6ef22b6', '獨孤中丞筵陪餞韋君赴昇州', '独孤中丞筵陪餞韋君赴昇州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["中司龍節貴，上客虎符新。","地控吳襟帶，才高漢縉紳。","泛舟應度臘，入境便行春。","處處歌來暮，長江建業人。"]', '["中司龙節貴，上客虎符新。","地控吳襟带，才高漢縉紳。","泛舟應度臘，入境便行春。","处处歌来暮，长江建業人。"]', '诗', 'shi', '', NULL, '獨孤中丞筵陪餞韋君赴昇州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1befe2e-2e4d-4220-aa06-5fae1d3a1a04', '送王緒剡中', '送王緒剡中', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["不見關山去，何時到郯中。","已聞成竹木，更道長兒童。","籬落雲常聚，村墟水自通。","朝朝憶玄度，非是對清風。"]', '["不见关山去，何时到郯中。","已闻成竹木，更道长兒童。","籬落云常聚，村墟水自通。","朝朝憶玄度，非是对清风。"]', '诗', 'shi', '', NULL, '送王緒剡中 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4df1827-8d5d-4cbb-ba7e-e5d7cf1a787d', '詶李郎中侍御秋夜登福州城樓見寄', '詶李郎中侍御秋夜登福州城楼见寄', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["辛勤萬里道，簫索九秋殘。","月照閩中夜，天凝海上寒。","王程無地遠，主意在人安。","遙寄登樓作，空知行路難。"]', '["辛勤万里道，簫索九秋殘。","月照閩中夜，天凝海上寒。","王程無地远，主意在人安。","遙寄登楼作，空知行路难。"]', '诗', 'shi', '', NULL, '詶李郎中侍御秋夜登福州城樓見寄 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac7a41b-3f34-4af0-8b38-d16be263c2c9', '同李司直諸公暑夜南餘館', '同李司直諸公暑夜南餘館', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["何處多明月，津亭暑夜深。","煙霞不可望，雲樹更沈沈。","好是吳中隱，仍爲洛下吟。","微官朝復夕，牽強亦何心。"]', '["何处多明月，津亭暑夜深。","煙霞不可望，云樹更沈沈。","好是吳中隐，仍爲洛下吟。","微官朝复夕，牽強亦何心。"]', '诗', 'shi', '', NULL, '同李司直諸公暑夜南餘館 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d74803-47e5-41c2-9631-a9ef240491e0', '贈普門上人', '贈普门上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["支公身欲老，長在沃州多。","慧力堪傳敎，禪功久伏魔。","山雲隨坐夏，江草伴頭陀。","借問迴心後，賢愚去幾何。"]', '["支公身欲老，长在沃州多。","慧力堪傳敎，禪功久伏魔。","山云隨坐夏，江草伴头陀。","借问迴心後，賢愚去幾何。"]', '诗', 'shi', '', NULL, '贈普門上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a9f059d-a423-47f4-a818-47a708dd2cf6', '與諸公同登無錫北樓', '與諸公同登無錫北楼', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["秋興因危堞，歸心過遠山。","風霜征雁早，江海旅人閑。","驛樹寒仍密，漁舟晚自還。","仲宣何所賦，秪歎在荆蠻。"]', '["秋兴因危堞，归心過远山。","风霜征雁早，江海旅人闲。","驛樹寒仍密，漁舟晚自還。","仲宣何所賦，秪歎在荆蠻。"]', '诗', 'shi', '', NULL, '與諸公同登無錫北樓 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f411dd36-1eb8-492e-845a-9c933e4ad5a9', '同李蘇州傷美人', '同李蘇州傷美人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["玉佩石榴裙，當年嫁使君。","專房猶見寵，傾國衆皆聞。","歌舞常無對，幽明忽此分。","陽臺千萬里，何處作朝雲。"]', '["玉佩石榴裙，當年嫁使君。","專房猶见寵，傾国衆皆闻。","歌舞常無对，幽明忽此分。","陽台千万里，何处作朝云。"]', '诗', 'shi', '', NULL, '同李蘇州傷美人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83ab760-cd85-407c-8bb5-e5344a2754d3', '送李錄事赴饒州', '送李錄事赴饒州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["北人南去雪紛紛，雁叫汀沙不可聞。","積水長天隨遠客，荒城極浦足寒雲。","山從建業千峰出，江至潯陽九派分。","借問督郵纔弱冠，府中年少不如君。"]', '["北人南去雪紛紛，雁叫汀沙不可闻。","積水长天隨远客，荒城極浦足寒云。","山從建業千峰出，江至潯陽九派分。","借问督郵纔弱冠，府中年少不如君。"]', '诗', 'shi', '', NULL, '送李錄事赴饒州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974d7215-4150-44b0-9a5f-f519ff1a048d', '同諸公有懷絕句', '同諸公有懷絕句', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["舊國迷江樹，他鄉近海門。","移家南渡久，童稚解方言。"]', '["旧国迷江樹，他乡近海门。","移家南渡久，童稚解方言。"]', '诗', 'shi', '', NULL, '同諸公有懷絕句 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6e2ebd-2648-49f9-8c2c-944b83fb212e', '題魏仲光淮山所居', '題魏仲光淮山所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["人群不相見，乃在白雲間。","問我將何適，羨君今獨閑。","朝朝汲淮水，暮暮上龜山。","幸已安貧定，當從鬢髮斑。"]', '["人群不相见，乃在白云间。","问我將何適，羨君今独闲。","朝朝汲淮水，暮暮上龟山。","幸已安貧定，當從鬢髮斑。"]', '诗', 'shi', '', NULL, '題魏仲光淮山所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eada0234-be9a-4e8a-ac91-fef409a4a9cb', '送鄭判官赴徐州', '送鄭判官赴徐州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["從軍非隴頭，師在古徐州。","氣勁三河卒，功多萬里侯。","元戎閫外令，才子幄中籌。","莫聽關山曲，還生出塞愁。"]', '["從軍非隴头，師在古徐州。","氣勁三河卒，功多万里侯。","元戎閫外令，才子幄中籌。","莫听关山曲，還生出塞愁。"]', '诗', 'shi', '', NULL, '送鄭判官赴徐州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d1043ef-c463-450c-96ca-73567acef3b6', '送顧萇往新安', '送顧萇往新安', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["由來山水客，復道向新安。","半是乘潮便，全非行路難。","晨裝林月在，野飯浦沙寒。","嚴子千年後，何人釣舊灘。"]', '["由来山水客，复道向新安。","半是乘潮便，全非行路难。","晨裝林月在，野飯浦沙寒。","嚴子千年後，何人釣旧灘。"]', '诗', 'shi', '', NULL, '送顧萇往新安 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc239af-e267-4a89-a804-330cf037dcb5', '秋夜有懷高三十五兼呈空和尚', '秋夜有懷高三十五兼呈空和尚', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["晚節聞君趨道深，結茅栽樹近東林。","大師幾度曾摩頂，高士何年遂發心。","北渚三更聞過雁，西城萬里動寒砧。","不見支公與玄度，相思擁膝坐長吟。"]', '["晚節闻君趨道深，結茅栽樹近东林。","大師幾度曾摩頂，高士何年遂發心。","北渚三更闻過雁，西城万里动寒砧。","不见支公與玄度，相思擁膝坐长吟。"]', '诗', 'shi', '', NULL, '秋夜有懷高三十五兼呈空和尚 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b497a5f2-7762-43d6-b788-c6a1d7f20bed', '途中送權三兄弟', '途中送權三兄弟', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["淮海風濤起，江關憂思長。","同悲鵲遶樹，獨作雁隨陽。","山晚雲初雪，汀寒月照霜。","由來濯纓處，漁父愛滄浪。"]', '["淮海风濤起，江关憂思长。","同悲鵲遶樹，独作雁隨陽。","山晚云初雪，汀寒月照霜。","由来濯纓处，漁父愛滄浪。"]', '诗', 'shi', '', NULL, '途中送權三兄弟 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8954ab80-1480-4de3-abdb-06121c8493b2', '送裴闡', '送裴闡', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["道向毗陵豈是歸，客中誰與換春衣。","今夜孤舟行近遠，子荆零雨正霏霏。"]', '["道向毗陵豈是归，客中誰與換春衣。","今夜孤舟行近远，子荆零雨正霏霏。"]', '诗', 'shi', '', NULL, '送裴闡 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a1f615-2b63-4797-8b7a-3ea3708722df', '雜言湖山歌送許鳴謙', '杂言湖山歌送許鳴謙', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["湖中之山兮波上青，桂颯颯兮雨冥冥。","君歸兮春早，滿山兮碧草。","晨舂暮汲兮心何求，澗戶巖扉兮身自老。","東嶺西峰兮同白雲，雞鳴犬吠兮時相聞。","幽芳媚景兮當嘉月，踐石捫蘿兮恣超忽。","空山寂寂兮潁陽人，旦夕孤雲隨一身。"]', '["湖中之山兮波上青，桂颯颯兮雨冥冥。","君归兮春早，满山兮碧草。","晨舂暮汲兮心何求，澗戶巖扉兮身自老。","东嶺西峰兮同白云，雞鳴犬吠兮时相闻。","幽芳媚景兮當嘉月，踐石捫蘿兮恣超忽。","空山寂寂兮潁陽人，旦夕孤云隨一身。"]', '诗', 'shi', '', NULL, '雜言湖山歌送許鳴謙 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c94e20-704b-42b2-a2e8-bc9f8a851232', '雜言迎神詞二首 迎神', '杂言迎神词二首 迎神', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["啓庭戶，列芳鮮，目眇眇，心綿綿，因風託雨降瓊筵。","紛下拜，屢加籩，人心望歲祈豐年。"]', '["啓庭戶，列芳鲜，目眇眇，心綿綿，因风託雨降瓊筵。","紛下拜，屢加籩，人心望歲祈豐年。"]', '诗', 'shi', '', NULL, '雜言迎神詞二首 迎神 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea87f475-1d06-4516-9a65-bd30c39813eb', '雜言迎神詞二首 送神', '杂言迎神词二首 送神', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["露霑衣，月隱壁，氣淒淒，人寂寂，風迴雨度虛瑤席。","來無聲，去無跡，神心降和福遠客。"]', '["露霑衣，月隐壁，氣淒淒，人寂寂，风迴雨度虛瑤席。","来無声，去無跡，神心降和福远客。"]', '诗', 'shi', '', NULL, '雜言迎神詞二首 送神 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c89a38-5646-48b3-ad64-0b936125b979', '屏風上各賦一物得攜琴客', '屏风上各賦一物得携琴客', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["不是向空林，應當就磐石。","白雲知隱處，芳草迷行跡。","如何秪役心，見爾攜琴客。"]', '["不是向空林，應當就磐石。","白云知隐处，芳草迷行跡。","如何秪役心，见爾携琴客。"]', '诗', 'shi', '', NULL, '屏風上各賦一物得攜琴客 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae58610a-ba60-4fa4-8d76-97478b3ee43d', '江草歌送盧判官', '江草歌送盧判官', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江臯兮春早，江上兮芳草。","雜蘼蕪兮杜蘅，作叢秀兮欲羅生。","被遙隰兮經長衍，雨中深兮煙中淺。","目眇眇兮增愁，步遲遲兮堪搴。","澧之浦兮湘之濱，思夫君兮送美人。","吳洲曲兮楚鄉路，遠孤城兮依獨戎。","新月能分裛露時，夕陽照見連天處。","問君行邁將何之，淹泊沿洄風日遲。","處處汀洲有芳草，王孫詎肯念歸期。"]', '["江臯兮春早，江上兮芳草。","杂蘼蕪兮杜蘅，作叢秀兮欲羅生。","被遙隰兮經长衍，雨中深兮煙中淺。","目眇眇兮增愁，步遲遲兮堪搴。","澧之浦兮湘之濱，思夫君兮送美人。","吳洲曲兮楚乡路，远孤城兮依独戎。","新月能分裛露时，夕陽照见連天处。","问君行邁將何之，淹泊沿洄风日遲。","处处汀洲有芳草，王孫詎肯念归期。"]', '诗', 'shi', '', NULL, '江草歌送盧判官 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d8ac50-fbb4-4823-aa34-efd17ca1970d', '題畫帳二首 山水', '題畫帳二首 山水', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["桂水饒楓杉，荆南足煙雨。","猶疑黛色中，復是雒陽岨。"]', '["桂水饒楓杉，荆南足煙雨。","猶疑黛色中，复是雒陽岨。"]', '诗', 'shi', '', NULL, '題畫帳二首 山水 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62830474-3427-4338-9a08-5812d7532c7f', '題畫帳二首 遠帆', '題畫帳二首 远帆', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["朝見巴江客，暮見巴江客。","雲帆儻暫停，中路陽臺夕。"]', '["朝见巴江客，暮见巴江客。","云帆儻暫停，中路陽台夕。"]', '诗', 'shi', '', NULL, '題畫帳二首 遠帆 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8090d749-4cf1-4d08-8d13-52eb93687fc7', '落第後東遊留別', '落第後东游留別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["功成方自得，何事學干求。","果以浮名誤，深貽達士羞。","九江連漲海，萬里任虛舟。","歲晚同懷客，相思波上鷗。"]', '["功成方自得，何事学干求。","果以浮名誤，深貽達士羞。","九江連漲海，万里任虛舟。","歲晚同懷客，相思波上鷗。"]', '诗', 'shi', '', NULL, '落第後東遊留別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31b402f-fafa-40e4-af3b-a6f82d3801df', '雜言月洲歌送趙冽還襄陽', '杂言月洲歌送趙冽還襄陽', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["漢之廣矣中有洲，洲如月兮水環流。","流聒聒兮湍與瀨，草青青兮春更秋。","苦竹林，香楓樹，樵子罛師幾家住。","萬山飛雨一川來，巴客歸船傍洲去。","歸人不可遲，芳杜滿洲時。","無限風煙皆自悲，莫辭貧賤阻心期。","家住洲頭定近遠，朝泛輕橈暮當返。","不能隨爾臥芳洲，自念天機一何淺。"]', '["漢之廣矣中有洲，洲如月兮水环流。","流聒聒兮湍與瀨，草青青兮春更秋。","苦竹林，香楓樹，樵子罛師幾家住。","万山飞雨一川来，巴客归船傍洲去。","归人不可遲，芳杜满洲时。","無限风煙皆自悲，莫辞貧賤阻心期。","家住洲头定近远，朝泛轻橈暮當返。","不能隨爾臥芳洲，自念天機一何淺。"]', '诗', 'shi', '', NULL, '雜言月洲歌送趙冽還襄陽 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663600d9-fbb8-4336-96b3-5bf5cad96945', '寄劉八山中', '寄劉八山中', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["東臯若近遠，苦雨隔還期。","閨歲風霜晚，山田收穫遲。","茅簷燕去後，樵路菊黃時。","平子遊都久，知君坐見嗤。"]', '["东臯若近远，苦雨隔還期。","閨歲风霜晚，山田收穫遲。","茅簷燕去後，樵路菊黄时。","平子游都久，知君坐见嗤。"]', '诗', 'shi', '', NULL, '寄劉八山中 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e06dea87-6b5e-4f85-9f18-a4cfa4a53401', '答張諲劉方平兼呈賀蘭廣', '答張諲劉方平兼呈賀蘭廣', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["野性難馴狎，荒郊自閉門。","心閑同海鳥，日夕戀山村。","屢枉瓊瑤贈，如今道術存。","遠峯時振策，春雨耐香源。","復有故人在，寧聞廬鵲喧。","青青草色綠，終是待王孫。"]', '["野性难馴狎，荒郊自閉门。","心闲同海鸟，日夕戀山村。","屢枉瓊瑤贈，如今道術存。","远峯时振策，春雨耐香源。","复有故人在，寧闻廬鵲喧。","青青草色綠，終是待王孫。"]', '诗', 'shi', '', NULL, '答張諲劉方平兼呈賀蘭廣 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1255e7f-9db9-45a3-85cf-ad00559a3e58', '灃水送鄭鄠縣讀書', '灃水送鄭鄠縣读书', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["麥秋中夏涼風起，送君西郊及灃水。","孤煙遠樹動離心，隔岸江流若千里。","早年江海謝浮名，此路雲山愜爾情。","上古全經皆在口，秦人如見濟南生。"]', '["麦秋中夏涼风起，送君西郊及灃水。","孤煙远樹动離心，隔岸江流若千里。","早年江海謝浮名，此路云山愜爾情。","上古全經皆在口，秦人如见濟南生。"]', '诗', 'shi', '', NULL, '灃水送鄭鄠縣讀書 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1626b02f-b09d-4620-89a6-ffb8edef5190', '九日寄鄭豐', '九日寄鄭豐', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["重陽秋已晚，千里信仍稀。","何處登高望，知君正憶歸。","還當採時菊，定未授寒衣。","欲識離居恨，郊園正掩扉。"]', '["重陽秋已晚，千里信仍稀。","何处登高望，知君正憶归。","還當採时菊，定未授寒衣。","欲識離居恨，郊园正掩扉。"]', '诗', 'shi', '', NULL, '九日寄鄭豐 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f20774d3-7cb2-4ce2-aa36-32d90b50413e', '酬包評事壁畫山水見寄', '酬包評事壁畫山水见寄', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["一官知所傲，本意在雲泉。","濡翰生新興，群峰忽眼前。","黛中分遠近，筆下起風煙。","巖翠深樵路，湖光出釣船。","寒侵赤城頂，日照武陵川。","若覽名山誌，仍聞招隱篇。","遂令江海客，惆悵憶閑田。"]', '["一官知所傲，本意在云泉。","濡翰生新兴，群峰忽眼前。","黛中分远近，笔下起风煙。","巖翠深樵路，湖光出釣船。","寒侵赤城頂，日照武陵川。","若覽名山誌，仍闻招隐篇。","遂令江海客，惆悵憶闲田。"]', '诗', 'shi', '', NULL, '酬包評事壁畫山水見寄 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2db41a-d15e-46b7-9a04-b9ab1e467d64', '渡汝水向太和山', '渡汝水向太和山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["落日事搴陟，西南投一峯。","誠知秋水淺，但怯無人蹤。"]', '["落日事搴陟，西南投一峯。","誠知秋水淺，但怯無人蹤。"]', '诗', 'shi', '', NULL, '渡汝水向太和山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca96236-f393-4f2b-9a76-9691af094b99', '秋怨', '秋怨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["長信多秋氣，昭陽借月華。","那堪閉永巷，聞道選良家。"]', '["长信多秋氣，昭陽借月华。","那堪閉永巷，闻道選良家。"]', '诗', 'shi', '', NULL, '秋怨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53540760-0c98-4266-b4e2-e6e39b49ca0c', '贈鄭山人', '贈鄭山人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["白首滄洲客，陶然得此生。","龐公採藥去，萊氏與妻行。","乍見還州里，全非隱姓名。","枉帆臨海嶠，貰酒秣陵城。","伐木吳山曉，持竿越水清。","家人恣貧賤，物外任衰榮。","忽爾辭林壑，高歌至上京。","避喧心已慣，念遠夢頻成。","石路寒花發，江田臘雪明。","玄纁倘有命，何以遂躬耕。"]', '["白首滄洲客，陶然得此生。","龐公採藥去，萊氏與妻行。","乍见還州里，全非隐姓名。","枉帆臨海嶠，貰酒秣陵城。","伐木吳山晓，持竿越水清。","家人恣貧賤，物外任衰榮。","忽爾辞林壑，高歌至上京。","避喧心已慣，念远梦頻成。","石路寒花發，江田臘雪明。","玄纁倘有命，何以遂躬耕。"]', '诗', 'shi', '', NULL, '贈鄭山人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c0f1c2-a2f3-4278-a666-80404d0fdd26', '劉方平西齋對雪', '劉方平西斋对雪', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["對酒閑齋晚，開軒臘雪時。","花飄疑節候，色淨潤簾帷。","委樹寒枝弱，縈空去雁遲。","自然堪訪戴，無復四愁詩。"]', '["对酒闲斋晚，开軒臘雪时。","花飄疑節候，色淨潤簾帷。","委樹寒枝弱，縈空去雁遲。","自然堪訪戴，無复四愁诗。"]', '诗', 'shi', '', NULL, '劉方平西齋對雪 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43aa9830-55bf-4565-8ca1-38658b6ed048', '福先寺尋湛然寺主不見', '福先寺尋湛然寺主不见', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["寂然空佇立，往往報疎鐘。","高館誰留客，東南二室峰。","川原通霽色，田野變春容。","惆悵層城暮，猶言歸路逢。"]', '["寂然空佇立，往往報疎鐘。","高館誰留客，东南二室峰。","川原通霽色，田野变春容。","惆悵層城暮，猶言归路逢。"]', '诗', 'shi', '', NULL, '福先寺尋湛然寺主不見 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b72ab3f-89d3-4673-91a5-616aeb967f02', '河南鄭少尹城南亭送鄭判官還河東', '河南鄭少尹城南亭送鄭判官還河东', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["使臣懷餞席，亞尹有前溪。","客是仙舟裏，途從御苑西。","泉聲喧暗竹，草色引長堤。","故絳青山在，新田綠樹齊。","天秋聞別鵠，關曉待鳴雞。","應歎沈冥者，年年津路迷。"]', '["使臣懷餞席，亞尹有前溪。","客是仙舟裏，途從御苑西。","泉声喧暗竹，草色引长堤。","故絳青山在，新田綠樹齊。","天秋闻別鵠，关晓待鳴雞。","應歎沈冥者，年年津路迷。"]', '诗', 'shi', '', NULL, '河南鄭少尹城南亭送鄭判官還河東 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2aa6bd9-7433-4336-9561-81f7d7bdb067', '登玄元廟', '登玄元廟', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["古廟川原迥，重門禁籞連。","海童紛翠蓋，羽客事瓊筵。","御路分疎柳，離宮出苑田。","興新無向背，望久辨山川。","物外將遺老，區中誓絕緣。","函關若遠近，紫氣獨依然。"]', '["古廟川原迥，重门禁籞連。","海童紛翠蓋，羽客事瓊筵。","御路分疎柳，離宮出苑田。","兴新無向背，望久辨山川。","物外將遺老，區中誓絕緣。","函关若远近，紫氣独依然。"]', '诗', 'shi', '', NULL, '登玄元廟 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d20c68-6a13-491d-b88c-6f25bcd154b8', '冬夜集賦得寒漏', '冬夜集賦得寒漏', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["清冬洛陽客，寒漏建章臺。","出禁因風徹，縈窗共月來。","偏將殘瀨雜，乍與遠鴻哀。","遙夜重城警，流年滴水催。","閑齋堪坐聽，況有故人杯。"]', '["清冬洛陽客，寒漏建章台。","出禁因风徹，縈窗共月来。","偏將殘瀨杂，乍與远鴻哀。","遙夜重城警，流年滴水催。","闲斋堪坐听，況有故人杯。"]', '诗', 'shi', '', NULL, '冬夜集賦得寒漏 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f418f5-5f0c-4db3-9352-a2aea84eb414', '玄元觀送李源李風還奉先華陰', '玄元观送李源李风還奉先华陰', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["此去那知道路遙，寒原紫府上迢迢。","莫辭別酒和瓊液，乍唱離歌和鳳簫。","遠水東流浮落景，繚垣西轉失行鑣。","華山秦塞長相憶，無使音塵頓寂寥。"]', '["此去那知道路遙，寒原紫府上迢迢。","莫辞別酒和瓊液，乍唱離歌和鳳簫。","远水东流浮落景，繚垣西轉失行鑣。","华山秦塞长相憶，無使音塵頓寂寥。"]', '诗', 'shi', '', NULL, '玄元觀送李源李風還奉先華陰 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a57a4f-3095-4a5e-a9a4-6e2548104d43', '劉方平壁畫山', '劉方平壁畫山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["墨妙無前，性生筆先。","迴溪已失，遠嶂猶連。","側徑樵客，長林野煙。","青峰之外，何處雲天。"]', '["墨妙無前，性生笔先。","迴溪已失，远嶂猶連。","側徑樵客，长林野煙。","青峰之外，何处云天。"]', '诗', 'shi', '', NULL, '劉方平壁畫山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9130928b-e65e-421d-90d4-b8f2fc52bddf', '登山歌', '登山歌', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["青山前，青山後，登高望兩處。","兩處今何有？","煙景滿川原，離人堪白首。"]', '["青山前，青山後，登高望兩处。","兩处今何有？","煙景满川原，離人堪白首。"]', '诗', 'shi', '', NULL, '登山歌 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79497342-fc67-40d5-a09b-3fa21a1927af', '和鄭少尹祭中岳寺北訪蕭居士越上方', '和鄭少尹祭中岳寺北訪蕭居士越上方', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["肅寺祠靈境，尋真到隱居。","夤緣幽谷遠，蕭散白雲餘。","晚節持僧律，他年著道書。","海邊曾狎鳥，濠上正觀魚。","寂靜求無相，淳和覩太初。","一峰綿歲月，萬性任盈虛。","籬隔溪鐘度，窗臨澗木疎。","謝公懷舊壑，迴駕復何如。"]', '["肅寺祠靈境，尋真到隐居。","夤緣幽谷远，蕭散白云餘。","晚節持僧律，他年著道书。","海邊曾狎鸟，濠上正观鱼。","寂静求無相，淳和覩太初。","一峰綿歲月，万性任盈虛。","籬隔溪鐘度，窗臨澗木疎。","謝公懷旧壑，迴駕复何如。"]', '诗', 'shi', '', NULL, '和鄭少尹祭中岳寺北訪蕭居士越上方 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d69bbb1-6f02-4bdb-9b4c-1f3db7a985d1', '秋夜寄所思', '秋夜寄所思', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["寂寞坐遙夜，清風何處來？","天高散騎省，月冷建章臺。","鄰笛哀聲急，城砧朔氣催。","芙蓉已委絕，誰復可爲媒。"]', '["寂寞坐遙夜，清风何处来？","天高散騎省，月冷建章台。","鄰笛哀声急，城砧朔氣催。","芙蓉已委絕，誰复可爲媒。"]', '诗', 'shi', '', NULL, '秋夜寄所思 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67d398e-1ed0-4f1e-915e-e646dea8af66', '賦得郢路悲猨', '賦得郢路悲猨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["悲猨何處發？郢路第三聲。","遠客知秋暮，空山益夜清。","啾啾深衆木，嗷嗷入孤城。","坐覺盈心耳，翛然適楚情。"]', '["悲猨何处發？郢路第三声。","远客知秋暮，空山益夜清。","啾啾深衆木，嗷嗷入孤城。","坐覺盈心耳，翛然適楚情。"]', '诗', 'shi', '', NULL, '賦得郢路悲猨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0488e2-d817-4e8d-a2dc-641a84bda578', '雜言無錫惠山寺流泉歌', '杂言無錫惠山寺流泉歌', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["寺有泉兮泉在山，鏘金鳴玉兮長潺潺。","作潭鏡兮澄寺內，泛巖花兮到人間。","土膏脉動知春早，隈隩陰深長苔草。","處處縈迴石磴喧，朝朝盥漱山僧老。","僧自老，松自新，流活活，無冬春。","任疏鑿兮與汲引，若有意兮山中人。","偏依佛界通仙境，明滅玲瓏媚林嶺。","宛如太室臨九潭，詎減天台望三井。","我來結綬未經秋，已厭微官憶舊遊。","且復遲迴猶未去，此心秪爲靈泉留。"]', '["寺有泉兮泉在山，鏘金鳴玉兮长潺潺。","作潭镜兮澄寺內，泛巖花兮到人间。","土膏脉动知春早，隈隩陰深长苔草。","处处縈迴石磴喧，朝朝盥漱山僧老。","僧自老，松自新，流活活，無冬春。","任疏鑿兮與汲引，若有意兮山中人。","偏依佛界通仙境，明滅玲瓏媚林嶺。","宛如太室臨九潭，詎減天台望三井。","我来結綬未經秋，已厭微官憶旧游。","且复遲迴猶未去，此心秪爲靈泉留。"]', '诗', 'shi', '', NULL, '雜言無錫惠山寺流泉歌 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ec6f0d-71fd-4eb2-b460-f95cecab414f', '清明日青龍寺上方賦得多字', '清明日青龙寺上方賦得多字', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["上方偏可適。","季月況堪過，遠近水聲至。","東西山色多，夕陽留徑草。","新葉變庭柯，已度清明節。","春秋如客何。"]', '["上方偏可適。","季月況堪過，远近水声至。","东西山色多，夕陽留徑草。","新葉变庭柯，已度清明節。","春秋如客何。"]', '诗', 'shi', '', NULL, '清明日青龍寺上方賦得多字 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc2682b-faa5-40c7-8af2-f73ba04ace91', '與張諲宿劉八城東莊', '與張諲宿劉八城东莊', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["人閑當歲暮，田野尚逢迎。","萊子多嘉慶，陶公得此生。","寒蕪連古渡，雲樹近嚴城。","雞黍無辭薄，貧交但貴情。"]', '["人闲當歲暮，田野尚逢迎。","萊子多嘉慶，陶公得此生。","寒蕪連古渡，云樹近嚴城。","雞黍無辞薄，貧交但貴情。"]', '诗', 'shi', '', NULL, '與張諲宿劉八城東莊 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f3a99f-b10f-4470-bd4a-f69de67a4607', '寄劉方平', '寄劉方平', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["坐憶山中人，窮棲事南畝。","煙霞相親外，墟落今何有。","潘郎作賦年，陶令辭官後。","達生遺自適，良願固無負。","田取潁水流，樹入陽城口。","歲暮憂思盈，離居不堪久。"]', '["坐憶山中人，窮棲事南畝。","煙霞相親外，墟落今何有。","潘郎作賦年，陶令辞官後。","達生遺自適，良願固無負。","田取潁水流，樹入陽城口。","歲暮憂思盈，離居不堪久。"]', '诗', 'shi', '', NULL, '寄劉方平 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e1c844-d9ad-4345-80b9-c3329d9ea2f2', '曾東遊以詩寄之', '曾东游以诗寄之', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["出郭離言多，迴車始知遠。","寂然層城暮，更念前山轉。","總轡越成臯，浮舟背梁苑。","朝朝勞延首，往住若在眼。","落日孤雲還，邊愁迷楚關。","如何漵花發，復對遊子顏。","古寺杉栝裏，連檣洲渚間。","煙生海西岸，雲見吳南山。","驚風掃蘆荻，翻浪連天白。","正是揚帆時，偏逢江上客。","由來許佳句，況乃愜所適。","嵯峨天姥峰，翠色春更碧。","氣淒湖上雨，月淨剡中夕。","釣艇或相逢，江蘺又堪摘。","迢迢始寧墅，蕪沒謝公宅。","朱槿列摧墉，蒼苔徧幽石。","顧予任疎懶，期爾振羽翮。","滄洲未可行，須售金門策。"]', '["出郭離言多，迴车始知远。","寂然層城暮，更念前山轉。","總轡越成臯，浮舟背梁苑。","朝朝勞延首，往住若在眼。","落日孤云還，邊愁迷楚关。","如何漵花發，复对游子顏。","古寺杉栝裏，連檣洲渚间。","煙生海西岸，云见吳南山。","驚风掃蘆荻，翻浪連天白。","正是揚帆时，偏逢江上客。","由来許佳句，況乃愜所適。","嵯峨天姥峰，翠色春更碧。","氣淒湖上雨，月淨剡中夕。","釣艇或相逢，江蘺又堪摘。","迢迢始寧墅，蕪沒謝公宅。","朱槿列摧墉，蒼苔徧幽石。","顧予任疎懶，期爾振羽翮。","滄洲未可行，須售金门策。"]', '诗', 'shi', '', NULL, '曾東遊以詩寄之 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccdfb1d-5f1c-4f71-9f96-affa24afacbb', '適荆州途次南陽贈何明府', '適荆州途次南陽贈何明府', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["千里獨遊日，有懷誰與同。","言過細陽令，一遇郎陵公。","清節邁多士，斯文傳古風。","閭閻知俗變，原野識年豐。","吾道方在此，前程殊未窮。","江天經峴北，客思滿巴東。","夢渚夕愁遠，山丘晴望通。","應嗟出處異，流蕩楚雲中。"]', '["千里独游日，有懷誰與同。","言過細陽令，一遇郎陵公。","清節邁多士，斯文傳古风。","閭閻知俗变，原野識年豐。","吾道方在此，前程殊未窮。","江天經峴北，客思满巴东。","梦渚夕愁远，山丘晴望通。","應嗟出处異，流蕩楚云中。"]', '诗', 'shi', '', NULL, '適荆州途次南陽贈何明府 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0e59a3-9d95-4a22-849a-fdc25fc2e3d8', '秋夜戲題劉方平壁', '秋夜戲題劉方平壁', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["鴻悲月白時將謝，正可招尋惜遙夜。","翠帳蘭房曲且深，寧知戶外清霜下。"]', '["鴻悲月白时將謝，正可招尋惜遙夜。","翠帳蘭房曲且深，寧知戶外清霜下。"]', '诗', 'shi', '', NULL, '秋夜戲題劉方平壁 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fcb6791-4b0f-4a32-84f9-fbebc30dd9c5', '問正上人疾', '问正上人疾', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["醫王猶有疾，妙理競難窮。","餌藥應隨病，觀身轉悟空。","地閑花欲雨，窗冷竹生風。","幾日東林去，門人待遠公。"]', '["醫王猶有疾，妙理競难窮。","餌藥應隨病，观身轉悟空。","地闲花欲雨，窗冷竹生风。","幾日东林去，门人待远公。"]', '诗', 'shi', '', NULL, '問正上人疾 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02139bd5-8e74-47f9-9ec3-5d13163bb1d0', '山中五詠 門柳', '山中五詠 门柳', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["接影武昌城，分行漢南道。","何事閑門外，空對青山老。"]', '["接影武昌城，分行漢南道。","何事闲门外，空对青山老。"]', '诗', 'shi', '', NULL, '山中五詠 門柳 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a40f694-3066-46ab-b2fd-2f87bd1eedb0', '山中五詠 遠山', '山中五詠 远山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["少室盡西峯，鳴臯隱南面。","柴門縱復關，終日窗中見。"]', '["少室尽西峯，鳴臯隐南面。","柴门縱复关，終日窗中见。"]', '诗', 'shi', '', NULL, '山中五詠 遠山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce12fb9-715f-482d-80eb-5e8946ea2e8f', '山中五詠 南澗', '山中五詠 南澗', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["上路各乘軒，高明盡鳴玉。","寧知澗下人，自愛輕波淥。"]', '["上路各乘軒，高明尽鳴玉。","寧知澗下人，自愛轻波淥。"]', '诗', 'shi', '', NULL, '山中五詠 南澗 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cef360-6346-46e5-acd2-5c7c1ed7fced', '山中五詠 春早', '山中五詠 春早', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["草徧潁陽山，花開武陵水。","春色既已同，人心亦相似。"]', '["草徧潁陽山，花开武陵水。","春色既已同，人心亦相似。"]', '诗', 'shi', '', NULL, '山中五詠 春早 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab17641-f626-47a7-a8e3-c59a43000649', '山中五詠 山館', '山中五詠 山館', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["山館長寂寂，閑雲朝夕來。","空庭復何有，落日照青苔。"]', '["山館长寂寂，闲云朝夕来。","空庭复何有，落日照青苔。"]', '诗', 'shi', '', NULL, '山中五詠 山館 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b39f42b-3d8c-4c15-ad4c-b9ed2b9a88a2', '送竇十九叔向赴京', '送竇十九叔向赴京', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["冰結楊柳津，從吳去入秦。","徒云還上國，誰爲作中人。","驛樹同霜霰，漁舟伴苦辛。","相如求一謁，詞賦遠隨身。"]', '["冰結楊柳津，從吳去入秦。","徒云還上国，誰爲作中人。","驛樹同霜霰，漁舟伴苦辛。","相如求一謁，词賦远隨身。"]', '诗', 'shi', '', NULL, '送竇十九叔向赴京 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972879b8-36c2-409a-9d02-14b1253b1cde', '登石城戍望海寄諸暨嚴少府', '登石城戍望海寄諸暨嚴少府', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["平明登古戍，徙倚待寒潮。","江海方回合，雲林自寂寥。","詎能知遠近，徒見蕩煙霄。","即此滄洲路，嗟君久折腰。"]', '["平明登古戍，徙倚待寒潮。","江海方回合，云林自寂寥。","詎能知远近，徒见蕩煙霄。","即此滄洲路，嗟君久折腰。"]', '诗', 'shi', '', NULL, '登石城戍望海寄諸暨嚴少府 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ef0ed0-68f0-428b-9056-48a65c9c7a3c', '和樊潤州秋日登城樓', '和樊潤州秋日登城楼', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["露冕臨平楚，寒城帶早霜。","時同借河內，人是臥淮陽。","積水澄天塹，連山入帝鄉。","因高欲見下，非是愛秋光。"]', '["露冕臨平楚，寒城带早霜。","时同借河內，人是臥淮陽。","積水澄天塹，連山入帝乡。","因高欲见下，非是愛秋光。"]', '诗', 'shi', '', NULL, '和樊潤州秋日登城樓 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29c187a-cae6-47be-bd85-ccdaee98f422', '寄江東李判官', '寄江东李判官', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["遠懷不可道，歷稔倦離憂。","洛下聞新雁，江南想暮秋。","澄清佐八使，綱紀案諸侯。","地識吳平久，才當晉用求。","時賢幾殂謝，摛藻繼風流。","更有西陵作，還成北固遊。","歸途限尺牘，王事在扁舟。","山色臨湖盡，猿聲入夢愁。"]', '["远懷不可道，歷稔倦離憂。","洛下闻新雁，江南想暮秋。","澄清佐八使，綱紀案諸侯。","地識吳平久，才當晉用求。","时賢幾殂謝，摛藻繼风流。","更有西陵作，還成北固游。","归途限尺牘，王事在扁舟。","山色臨湖尽，猿声入梦愁。"]', '诗', 'shi', '', NULL, '寄江東李判官 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('071e72e6-de40-4aa0-add7-7eed7e63ac4c', '送蔣評事往福州', '送蔣評事往福州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江上春常早，閩中客去稀。","登山怨迢遞，臨水惜芳菲。","煙樹何時盡，風帆幾日歸。","還看復命處，盛府有光輝。"]', '["江上春常早，閩中客去稀。","登山怨迢遞，臨水惜芳菲。","煙樹何时尽，风帆幾日归。","還看复命处，盛府有光輝。"]', '诗', 'shi', '', NULL, '送蔣評事往福州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70072726-2a11-4aa0-8814-3affe5ba0097', '送從弟豫貶遠州', '送從弟豫貶远州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["何事成遷客，思歸不見鄉。","遊吳經萬里，弔屈過三湘。","水與荆巫接，山通鄢郢長。","名嗟黃綬繫，才是白眉良。","獨結南枝恨，應思北雁行。","憂來沽楚酒，玄鬢莫凝霜。"]', '["何事成遷客，思归不见乡。","游吳經万里，弔屈過三湘。","水與荆巫接，山通鄢郢长。","名嗟黄綬繫，才是白眉良。","独結南枝恨，應思北雁行。","憂来沽楚酒，玄鬢莫凝霜。"]', '诗', 'shi', '', NULL, '送從弟豫貶遠州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2258ac-7c5b-42fd-951e-5e904383259e', '送錢唐路少府赴制舉', '送錢唐路少府赴制舉', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["公車待詔赴長安，客裏新正阻舊歡。","遲日未能銷野雪，晴花偏自犯江寒。","東溟道路通秦塞，北闕威儀識漢官。","共許郄詵工射策，恩榮請向一枝看。"]', '["公车待詔赴长安，客裏新正阻旧歡。","遲日未能銷野雪，晴花偏自犯江寒。","东溟道路通秦塞，北闕威儀識漢官。","共許郄詵工射策，恩榮請向一枝看。"]', '诗', 'shi', '', NULL, '送錢唐路少府赴制舉 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8920421d-07a1-40d8-8776-aef2212f6681', '賦得荆溪夜湍送蔣逸人歸義興山', '賦得荆溪夜湍送蔣逸人归義兴山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["驚湍流不極，夜度識雲岑。","長帶溪沙淺，時因山雨深。","方同七里路，更遂五湖心。","揭厲朝將夕，潺湲古至今。","花源君若許，雖遠亦相尋。"]', '["驚湍流不極，夜度識云岑。","长带溪沙淺，时因山雨深。","方同七里路，更遂五湖心。","揭厲朝將夕，潺湲古至今。","花源君若許，雖远亦相尋。"]', '诗', 'shi', '', NULL, '賦得荆溪夜湍送蔣逸人歸義興山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503b3e6f-a832-43df-bf4b-20bbfcef0769', '送孔黨赴舉', '送孔黨赴舉', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["入貢列諸生，詩書業早成。","家承孔聖後，身有魯儒名。","楚水通滎浦，春山擁漢京。","愛君方弱冠，爲賦少年行。"]', '["入貢列諸生，诗书業早成。","家承孔聖後，身有魯儒名。","楚水通滎浦，春山擁漢京。","愛君方弱冠，爲賦少年行。"]', '诗', 'shi', '', NULL, '送孔黨赴舉 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740ca256-d62c-4cb8-96f9-7a62d39c398c', '齊郎中筵賦得的的帆向浦留別', '齊郎中筵賦得的的帆向浦留別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["一帆何處去，正在望中微。","浦迥搖空色，汀迴見落暉。","每爭高鳥度，能送遠人歸。","偏似南浮客，悠揚無所依。"]', '["一帆何处去，正在望中微。","浦迥搖空色，汀迴见落暉。","每爭高鸟度，能送远人归。","偏似南浮客，悠揚無所依。"]', '诗', 'shi', '', NULL, '齊郎中筵賦得的的帆向浦留別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd40f188-e63b-48e7-9418-7e8e667b7308', '送陸鴻漸棲霞寺採茶', '送陸鴻漸棲霞寺採茶', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["採茶非採菉，遠遠上層崖。","布葉春風暖，盈筐白日斜。","舊知山寺路，時宿野人家。","借問王孫草，何時泛椀花。"]', '["採茶非採菉，远远上層崖。","布葉春风暖，盈筐白日斜。","旧知山寺路，时宿野人家。","借问王孫草，何时泛椀花。"]', '诗', 'shi', '', NULL, '送陸鴻漸棲霞寺採茶 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('585e6c66-799d-477b-bc45-c1f3b201c6cc', '泊丹陽與諸人同舟至馬林溪遇雨', '泊丹陽與諸人同舟至马林溪遇雨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["雲林不可望，溪水更悠悠。","共載人皆客，離家春是秋。","遠山方對枕，細雨莫迴舟。","來往南徐路，多爲芳草留。"]', '["云林不可望，溪水更悠悠。","共載人皆客，離家春是秋。","远山方对枕，細雨莫迴舟。","来往南徐路，多爲芳草留。"]', '诗', 'shi', '', NULL, '泊丹陽與諸人同舟至馬林溪遇雨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3fdf10-9280-4d80-a33d-9c4ac579eab0', '太常魏博士遠出賊庭江外相逢因敘其事', '太常魏博士远出賊庭江外相逢因敘其事', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["烽火驚戎塞，豺狼犯帝畿。","川原無稼穡，日月翳光輝。","里社枌榆毀，宮城騎吏非。","羣生被慘毒，雜虜耀輕肥。","多士從芳餌，唯君識禍機。","心同合浦葉，命寄首陽薇。","耻作纖鱗喣，方隨高鳥飛。","山經商嶺出，水泛漢池歸。","離別霜凝鬢，逢迎淚迸衣。","京華長路絕，江海故人稀。","秉節身常苦，求仁志不違。","秪應窮野外，耕種且相依。"]', '["烽火驚戎塞，豺狼犯帝畿。","川原無稼穡，日月翳光輝。","里社枌榆毀，宮城騎吏非。","羣生被慘毒，杂虜耀轻肥。","多士從芳餌，唯君識禍機。","心同合浦葉，命寄首陽薇。","耻作纖鱗喣，方隨高鸟飞。","山經商嶺出，水泛漢池归。","離別霜凝鬢，逢迎泪迸衣。","京华长路絕，江海故人稀。","秉節身常苦，求仁志不違。","秪應窮野外，耕種且相依。"]', '诗', 'shi', '', NULL, '太常魏博士遠出賊庭江外相逢因敘其事 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('318cdefe-d46b-4f4c-b462-5f9337aa0fa7', '送包佶賦得天津橋', '送包佶賦得天津橋', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["洛陽歲暮作征客，囗囗囗囗囗囗囗。","相望依然一水間，相思已如千年隔。","晴煙霽景滿天津，鳳閣龍樓暎水濱。","豈無朝夕軒車度，其奈相逢非所親。","鞏樹甘陵愁遠道，他鄉一望人堪老。","君報還期在早春，橋邊日日看芳草。"]', '["洛陽歲暮作征客，囗囗囗囗囗囗囗。","相望依然一水间，相思已如千年隔。","晴煙霽景满天津，鳳閣龙楼暎水濱。","豈無朝夕軒车度，其奈相逢非所親。","鞏樹甘陵愁远道，他乡一望人堪老。","君報還期在早春，橋邊日日看芳草。"]', '诗', 'shi', '', NULL, '送包佶賦得天津橋 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a5a5d83-7614-4415-a36b-c9a198e65c25', '上禮部楊侍郎', '上禮部楊侍郎', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["郢匠掄材日，轅輪必盡呈。","敢言當一幹，徒欲隸諸生。","末學慙鄒魯，深仁錄弟兄。","餘波知可挹，弱植更求榮。","績媿他年敗，功期此日成。","方因舊桃李，猶冀載飛鳴。","道淺猶懷分，時移但自驚。","關門驚暮節，林壑廢春畊。","十里嵩峯近，千秋潁水清。","煙花迷戍谷，墟落接陽城。","渺默思鄉夢，遲迴知己情。","勞歌終此曲，還是苦辛行。"]', '["郢匠掄材日，轅輪必尽呈。","敢言當一幹，徒欲隸諸生。","末学慙鄒魯，深仁錄弟兄。","餘波知可挹，弱植更求榮。","績媿他年敗，功期此日成。","方因旧桃李，猶冀載飞鳴。","道淺猶懷分，时移但自驚。","关门驚暮節，林壑廢春畊。","十里嵩峯近，千秋潁水清。","煙花迷戍谷，墟落接陽城。","渺默思乡梦，遲迴知己情。","勞歌終此曲，還是苦辛行。"]', '诗', 'shi', '', NULL, '上禮部楊侍郎 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd8a531-9e74-476b-9345-6824427f4cec', '宿嚴維宅送包七', '宿嚴維宅送包七', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江湖同避地，分手自依依。","盡室今爲客，經秋空念歸。","歲儲無別墅，寒服羨鄰機。","草色村橋晚，蟬聲江樹稀。","夜涼宜共醉，時難惜相違。","何事隨陽侶，汀洲忽背飛。"]', '["江湖同避地，分手自依依。","尽室今爲客，經秋空念归。","歲儲無別墅，寒服羨鄰機。","草色村橋晚，蟬声江樹稀。","夜涼宜共醉，时难惜相違。","何事隨陽侶，汀洲忽背飞。"]', '诗', 'shi', '', NULL, '宿嚴維宅送包七 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd9291b-9201-4e56-9214-3aa3c4c29e37', '同張侍御詠興寧寺經藏院海石榴花', '同張侍御詠兴寧寺經藏院海石榴花', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["嫩葉生初茂，殘花少更鮮。","結根龍藏側，故欲並青蓮。"]', '["嫩葉生初茂，殘花少更鲜。","結根龙藏側，故欲並青蓮。"]', '诗', 'shi', '', NULL, '同張侍御詠興寧寺經藏院海石榴花 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f0993f-d2b7-4b8e-a8dc-ad05daacf472', '崔十四宅各賦一物得簷柳', '崔十四宅各賦一物得簷柳', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["官渡老風烟，潯陽媚雲日。","漢將營前見，胡笳曲中出。","復在此簷端，垂陰仲長室。"]', '["官渡老风烟，潯陽媚云日。","漢將營前见，胡笳曲中出。","复在此簷端，垂陰仲长室。"]', '诗', 'shi', '', NULL, '崔十四宅各賦一物得簷柳 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ecea89-11af-496d-b707-bf20aad90219', '送段明府', '送段明府', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["遙夜此何其，霜空殘杳靄。","方嗟異鄉別，蹔是同公會。","海林秋更疎，野水寒猶大。","離人轉吳岫，旅雁從燕塞。","日夕望前期，勞心白雲外。"]', '["遙夜此何其，霜空殘杳靄。","方嗟異乡別，蹔是同公會。","海林秋更疎，野水寒猶大。","離人轉吳岫，旅雁從燕塞。","日夕望前期，勞心白云外。"]', '诗', 'shi', '', NULL, '送段明府 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6626bd00-c5f7-4983-98b3-6a2eb60c9154', '送王司直', '送王司直', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["西塞雲山遠，東風道路長。","人心勝潮水，相送過潯陽。"]', '["西塞云山远，东风道路长。","人心勝潮水，相送過潯陽。"]', '诗', 'shi', '', NULL, '送王司直 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5daf7602-90c9-4846-b0b3-cd49a6aa6964', '婕妤春怨', '婕妤春怨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["花枝出建章，鳳管發昭陽。","借問承恩者，雙蛾幾許長。"]', '["花枝出建章，鳳管發昭陽。","借问承恩者，雙蛾幾許长。"]', '诗', 'shi', '', NULL, '婕妤春怨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c335b1db-440a-4038-affe-15a07e5842b2', '送魏十六還蘇州', '送魏十六還蘇州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["秋夜深深北送君，陰蟲切切不堪聞。","歸舟明日毗陵道，迴首姑蘇是白雲。"]', '["秋夜深深北送君，陰蟲切切不堪闻。","归舟明日毗陵道，迴首姑蘇是白云。"]', '诗', 'shi', '', NULL, '送魏十六還蘇州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196ed93c-6344-40f4-a254-31fe62925bb6', '婕妤怨', '婕妤怨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["由來詠團扇，今已值秋風。","事逐時皆徃，恩無日再中。","早鴻聞上苑，寒露下深宮。","顏色年年謝，相如賦豈工。"]', '["由来詠團扇，今已值秋风。","事逐时皆徃，恩無日再中。","早鴻闻上苑，寒露下深宮。","顏色年年謝，相如賦豈工。"]', '诗', 'shi', '', NULL, '婕妤怨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d125924-4073-47eb-b947-d0f164f33ac1', '送客', '送客', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["旗鼓軍威重，關山客路賒。","待封甘度隴，回首不思家。","城下春山路，營中瀚海沙。","河源雖萬里，音信寄來查。"]', '["旗鼓軍威重，关山客路賒。","待封甘度隴，回首不思家。","城下春山路，營中瀚海沙。","河源雖万里，音信寄来查。"]', '诗', 'shi', '', NULL, '送客 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cb80fd-66ac-4f0c-ad95-c0cec8bff9ce', '秋日東郊作', '秋日东郊作', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["閑看秋水心無事，臥對寒松手自栽。","廬岳高僧留偈別，茅山道士寄書來。","燕知社日辭巢去，菊爲重陽冒雨開。","淺薄將何稱獻納，臨岐終日自遲迴。"]', '["闲看秋水心無事，臥对寒松手自栽。","廬岳高僧留偈別，茅山道士寄书来。","燕知社日辞巢去，菊爲重陽冒雨开。","淺薄將何稱獻納，臨岐終日自遲迴。"]', '诗', 'shi', '', NULL, '秋日東郊作 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9be6a9-bfdc-44f6-90ac-cd08abd71c1a', '秋夜宿嚴維宅', '秋夜宿嚴維宅', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["昔聞玄度宅，門向會稽峯。","君住東湖下，清風繼舊踪。","秋深臨水月，夜半隔山鐘。","世故多離別，良宵詎可逢。"]', '["昔闻玄度宅，门向會稽峯。","君住东湖下，清风繼旧踪。","秋深臨水月，夜半隔山鐘。","世故多離別，良宵詎可逢。"]', '诗', 'shi', '', NULL, '秋夜宿嚴維宅 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb1e943-f2a7-4f1a-b173-0f6d1e1637d5', '見諸姬學玉臺體', '见諸姬学玉台體', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["豔唱召燕姬，清弦待盧女。","由來道姓秦，誰不知家楚。","傳盃見目成，結帶明心許。","寧辭玉輦迎，自堪金屋貯。","朝朝作行雲，襄王迷處所。"]', '["豔唱召燕姬，清弦待盧女。","由来道姓秦，誰不知家楚。","傳盃见目成，結带明心許。","寧辞玉輦迎，自堪金屋貯。","朝朝作行云，襄王迷处所。"]', '诗', 'shi', '', NULL, '見諸姬學玉臺體 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dd5692e-2e4e-46a3-9e61-15a4e395a5d8', '酬張二倉曹揚子所居見寄兼呈韓郎中', '酬張二倉曹揚子所居见寄兼呈韓郎中', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["孤雲獨鶴自悠悠，別後經年尚泊舟。","漁父置詞相借問，郎官能賦許依投。","折芳遠寄三春草，乘興閑看萬里流。","莫怪杜門頻乞假，不堪扶病拜龍樓。"]', '["孤云独鹤自悠悠，別後經年尚泊舟。","漁父置词相借问，郎官能賦許依投。","折芳远寄三春草，乘兴闲看万里流。","莫怪杜门頻乞假，不堪扶病拜龙楼。"]', '诗', 'shi', '', NULL, '酬張二倉曹揚子所居見寄兼呈韓郎中 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335f6bc2-5379-466f-8553-d7d5ec4a9ed1', '送安律師', '送安律師', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["出家童子歲，愛此雪山人。","長路經千里，孤雲伴一身。","水中應見月，草上豈傷春。","永日空林下，心將何物親。"]', '["出家童子歲，愛此雪山人。","长路經千里，孤云伴一身。","水中應见月，草上豈傷春。","永日空林下，心將何物親。"]', '诗', 'shi', '', NULL, '送安律師 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96baaba3-9551-4e43-b43d-38acba9b88f8', '題盧十一所居', '題盧十一所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["春風來幾日，先入辟疆園。","身外無餘事，閑吟晝閉門。"]', '["春风来幾日，先入辟疆园。","身外無餘事，闲吟晝閉门。"]', '诗', 'shi', '', NULL, '題盧十一所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('969f9af7-e7ac-46f8-8a73-7898e72b72d2', '送陸[澧]郭鄖', '送陸[澧]郭鄖', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["纔見吳洲百草春，已聞燕雁一聲新。","秋風何處催年急，偏逐山行水宿人。"]', '["纔见吳洲百草春，已闻燕雁一声新。","秋风何处催年急，偏逐山行水宿人。"]', '诗', 'shi', '', NULL, '送陸[澧]郭鄖 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e5ec11-b403-4ede-9d5b-c1854706739b', '山中橫雲', '山中橫云', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["湘水風日滿，楚山朝夕空。","連峰雖已見，猶念長雲中。"]', '["湘水风日满，楚山朝夕空。","連峰雖已见，猶念长云中。"]', '诗', 'shi', '', NULL, '山中橫雲 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde212e6-2e8d-4c74-aa0f-d8e8cb9835a4', '題裴二十一新園', '題裴二十一新园', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["東郭訪先生，西郊尋隱路。","久爲江南客，自有雲陽樹。","已得閑園心，不知公府步。","開門白日晚，倚杖青山暮。","果熟任霜封，籬疎從水度。","窮年無牽綴，往事惜淪悞。","唯見耦耕人，朝朝自來去。"]', '["东郭訪先生，西郊尋隐路。","久爲江南客，自有云陽樹。","已得闲园心，不知公府步。","开门白日晚，倚杖青山暮。","果熟任霜封，籬疎從水度。","窮年無牽綴，往事惜淪悞。","唯见耦耕人，朝朝自来去。"]', '诗', 'shi', '', NULL, '題裴二十一新園 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de28c365-7d67-4513-a2d5-5dec1ff3c795', '寄高雲', '寄高云', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["南徐風日好，悵望毘陵道。","毘陵有故人，一見恨無因。","獨戀青山久，唯令白髮新。","每嫌持手板，時見著頭巾。","煙景臨寒食，農桑接仲春。","家貧仍嗜酒，生事今何有。","芳草遍江南，勞心憶攜手。"]', '["南徐风日好，悵望毘陵道。","毘陵有故人，一见恨無因。","独戀青山久，唯令白髮新。","每嫌持手板，时见著头巾。","煙景臨寒食，農桑接仲春。","家貧仍嗜酒，生事今何有。","芳草遍江南，勞心憶携手。"]', '诗', 'shi', '', NULL, '寄高雲 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d382e9b0-da98-4eae-9c97-aca770dcbb90', '溫泉即事', '溫泉即事', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["天仗星辰轉，霜冬景氣和。","樹含溫液潤，山入繚垣多。","丞相金錢賜，平陽玉輦過。","魯儒求一謁，無路獨如何。"]', '["天仗星辰轉，霜冬景氣和。","樹含溫液潤，山入繚垣多。","丞相金錢賜，平陽玉輦過。","魯儒求一謁，無路独如何。"]', '诗', 'shi', '', NULL, '溫泉即事 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db1e935-601d-4258-a93c-bf840d7c4655', '送張南史', '送張南史', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["馬卿工詞賦，位下年將暮。","謝客愛雲山，家貧身不閑。","風波杳未極，幾處逢相識。","富貴人皆變，誰能念貧賤。","岸有經霜草，林有故年枝。","俱應待春色，獨使客心悲。"]', '["马卿工词賦，位下年將暮。","謝客愛云山，家貧身不闲。","风波杳未極，幾处逢相識。","富貴人皆变，誰能念貧賤。","岸有經霜草，林有故年枝。","俱應待春色，独使客心悲。"]', '诗', 'shi', '', NULL, '送張南史 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346fa139-195f-40dc-b3e2-3758a5dd01ff', '廬山歌送至弘法師兼呈薛江州', '廬山歌送至弘法師兼呈薛江州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["釋子去兮訪名山，禪舟容與兮住仍前。","猿啾啾兮怨月，江渺渺兮多煙。","東林西林兮入何處，上方下方兮通石路。","連湘接楚饒桂花，事久年深無杏樹。","使君愛人兼愛山，時引雙旌萬木間。","政成人野皆不擾，遂令法侶性安閑。"]', '["釋子去兮訪名山，禪舟容與兮住仍前。","猿啾啾兮怨月，江渺渺兮多煙。","东林西林兮入何处，上方下方兮通石路。","連湘接楚饒桂花，事久年深無杏樹。","使君愛人兼愛山，时引雙旌万木间。","政成人野皆不擾，遂令法侶性安闲。"]', '诗', 'shi', '', NULL, '廬山歌送至弘法師兼呈薛江州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d22d9e5-04ad-42f1-b88c-7c4b07f012c1', '送薛秀才', '送薛秀才', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["雖是尋山客，還同慢世人。","讀書惟務靜，無褐不憂貧。","野色春冬樹，雞聲遠近鄰。","郄公即吾友，合與爾相親。"]', '["雖是尋山客，還同慢世人。","读书惟務静，無褐不憂貧。","野色春冬樹，雞声远近鄰。","郄公即吾友，合與爾相親。"]', '诗', 'shi', '', NULL, '送薛秀才 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f2904e-a113-40f7-8ca2-c92304a7a44b', '使往壽州淮路寄劉長卿', '使往壽州淮路寄劉长卿', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["榛草荒涼村落空，驅馳卒歲亦何功。","蒹葭曙色蒼蒼遠，蟋蟀秋聲處處同。","鄉路遙知淮浦外，故人多在楚雲東。","日夕煙霜那可道，壽陽西去水無窮。"]', '["榛草荒涼村落空，驱驰卒歲亦何功。","蒹葭曙色蒼蒼远，蟋蟀秋声处处同。","乡路遙知淮浦外，故人多在楚云东。","日夕煙霜那可道，壽陽西去水無窮。"]', '诗', 'shi', '', NULL, '使往壽州淮路寄劉長卿 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea18a01-5287-449f-bba4-38c6193b85ce', '酬李司兵直夜見寄', '酬李司兵直夜见寄', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江城聞鼓角，旅宿復何如。","寒月此宵半，春風舊歲餘。","徒云資薄祿，未必勝閑居。","見欲扁舟去，誰能畏簡書。"]', '["江城闻鼓角，旅宿复何如。","寒月此宵半，春风旧歲餘。","徒云資薄祿，未必勝闲居。","见欲扁舟去，誰能畏簡书。"]', '诗', 'shi', '', NULL, '酬李司兵直夜見寄 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc969e2f-a03d-4893-bf53-14dcc38d3a26', '送薛判官之越', '送薛判官之越', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["時難自多務，職小亦求賢。","道路無辭遠，雲山併在前。","樟亭待潮處，已是越人烟。"]', '["时难自多務，職小亦求賢。","道路無辞远，云山併在前。","樟亭待潮处，已是越人烟。"]', '诗', 'shi', '', NULL, '送薛判官之越 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef2f2701-dd8d-4482-b004-217944deac48', '同溫丹徒登萬歲樓', '同溫丹徒登万歲楼', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["高樓獨立思依依，極浦遙山合翠微。","江客不堪頻北顧，塞鴻何事復南飛。","丹陽古渡寒煙積，瓜步空洲遠樹稀。","聞道王師猶轉戰，誰能談笑解重圍。"]', '["高楼独立思依依，極浦遙山合翠微。","江客不堪頻北顧，塞鴻何事复南飞。","丹陽古渡寒煙積，瓜步空洲远樹稀。","闻道王師猶轉戰，誰能談笑解重圍。"]', '诗', 'shi', '', NULL, '同溫丹徒登萬歲樓 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a621e1c-a9ba-4690-a735-b83877917ab0', '賦得簷燕', '賦得簷燕', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["拂水競何忙，傍簷如有意。","翻風去每遠，帶雨歸偏駛。","令君裁杏梁，更欲年年去。"]', '["拂水競何忙，傍簷如有意。","翻风去每远，带雨归偏駛。","令君裁杏梁，更欲年年去。"]', '诗', 'shi', '', NULL, '賦得簷燕 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d54c7d-1683-4225-af61-23db20d99fc2', '送李萬州赴饒州覲省', '送李万州赴饒州覲省', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["前程觀拜慶，舊館惜招攜。","荀氏風流遠，胡家清白齊。","川迴吳岫失，塞闊楚雲低。","舉目親魚鳥，驚心怯鼓鼙。","人稀漁浦外，灘淺定山西。","無限青青草，王孫去不迷。"]', '["前程观拜慶，旧館惜招携。","荀氏风流远，胡家清白齊。","川迴吳岫失，塞闊楚云低。","舉目親鱼鸟，驚心怯鼓鼙。","人稀漁浦外，灘淺定山西。","無限青青草，王孫去不迷。"]', '诗', 'shi', '', NULL, '送李萬州赴饒州覲省 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976df39d-63c3-4d04-bb8c-4845154f3137', '送鄒判官赴河南', '送鄒判官赴河南', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["看君發原隰，四牡去皇皇。","始罷滄江吏，還隨粉署郎。","海沂軍未息，河畔歲仍荒。","征稅人全少，榛蕪虜近亡。","所行知宋遠，相隔歎淮長。","早晚裁書寄，銀鉤佇八行。"]', '["看君發原隰，四牡去皇皇。","始罷滄江吏，還隨粉署郎。","海沂軍未息，河畔歲仍荒。","征稅人全少，榛蕪虜近亡。","所行知宋远，相隔歎淮长。","早晚裁书寄，銀鉤佇八行。"]', '诗', 'shi', '', NULL, '送鄒判官赴河南 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('555dca9c-3114-454a-895e-37d014f73753', '宿淮陰南樓酬常伯能', '宿淮陰南楼酬常伯能', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["淮陰日落上南樓，喬木荒城古渡頭。","浦外野風初入戶，窗中海月早知秋。","滄波一望通千里，畫角三聲起百憂。","佇立分宵絕來客，煩君步屐忽相求。"]', '["淮陰日落上南楼，喬木荒城古渡头。","浦外野风初入戶，窗中海月早知秋。","滄波一望通千里，畫角三声起百憂。","佇立分宵絕来客，煩君步屐忽相求。"]', '诗', 'shi', '', NULL, '宿淮陰南樓酬常伯能 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b8aaf4-9827-470b-ab77-9666b6e11f4c', '送歸中丞使新羅', '送归中丞使新羅', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["詔使殊方遠，朝儀舊典行。","浮天無盡處，望日計前程。","暫喜孤山出，長愁積水平。","野風飄疊鼓，海雨濕危旌。","異俗知文敎，通儒有令名。","還將大戴禮，方外授諸生。"]', '["詔使殊方远，朝儀旧典行。","浮天無尽处，望日計前程。","暫喜孤山出，长愁積水平。","野风飄叠鼓，海雨濕危旌。","異俗知文敎，通儒有令名。","還將大戴禮，方外授諸生。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a288f33-b3b9-4fbd-8250-811fed3348ed', '小江懷靈一上人', '小江懷靈一上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江上年年春早，津頭日日人行。","借問山陰遠近，猶聞薄暮鐘聲。"]', '["江上年年春早，津头日日人行。","借问山陰远近，猶闻薄暮鐘声。"]', '诗', 'shi', '', NULL, '小江懷靈一上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d90e86-6dd8-4773-a0f8-c2cb6b66580f', '送唐別駕赴郢州', '送唐別駕赴郢州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["莫歎辭家遠，方看佐郡榮。","長林通楚塞，高嶺見秦城。","雪向嶢關下，人從郢路迎。","翩翩駿馬去，自是少年行。"]', '["莫歎辞家远，方看佐郡榮。","长林通楚塞，高嶺见秦城。","雪向嶢关下，人從郢路迎。","翩翩駿马去，自是少年行。"]', '诗', 'shi', '', NULL, '送唐別駕赴郢州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bac3aea-d9e6-4e74-bf5a-b44345ce829f', '送魏中丞還河北', '送魏中丞還河北', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["寧知貴公子，本是魯諸生。","上國風塵舊，中司印綬榮。","辛勤戎旅事，雪下護羗營。"]', '["寧知貴公子，本是魯諸生。","上国风塵旧，中司印綬榮。","辛勤戎旅事，雪下護羗營。"]', '诗', 'shi', '', NULL, '送魏中丞還河北 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5781e2ed-dc49-4d3e-8e7f-ab5d0b078187', '送李使君赴邵州', '送李使君赴邵州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["出送東方騎，行安南楚人。","城池春足雨，風俗夜迎神。","郢路逢歸客，湘川問去津。","爭看使君度，皂蓋雪中新。"]', '["出送东方騎，行安南楚人。","城池春足雨，风俗夜迎神。","郢路逢归客，湘川问去津。","爭看使君度，皂蓋雪中新。"]', '诗', 'shi', '', NULL, '送李使君赴邵州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd2c15e5-7297-4ae8-93f9-943605c6e30f', '寄振上人無碍寺所居', '寄振上人無碍寺所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["戀親時見在人羣，多在東山就白雲。","獨坐焚香誦經處，深山古寺雪紛紛。"]', '["戀親时见在人羣，多在东山就白云。","独坐焚香誦經处，深山古寺雪紛紛。"]', '诗', 'shi', '', NULL, '寄振上人無碍寺所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56acd535-6744-4d16-b59e-f897f591544b', '酬李補闕', '酬李補闕', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["十年歸客但心傷，三徑無人已自荒。","夕宿靈臺伴煙月，晨趨建禮逐衣裳。","偶因麋鹿隨豐草，謬荷鴛鸞借末行。","縱有諫書猶未獻，春風拂地日空長。"]', '["十年归客但心傷，三徑無人已自荒。","夕宿靈台伴煙月，晨趨建禮逐衣裳。","偶因麋鹿隨豐草，謬荷鴛鸾借末行。","縱有諫书猶未獻，春风拂地日空长。"]', '诗', 'shi', '', NULL, '酬李補闕 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc4f9adf-294c-47ac-9c99-cfe10866acb7', '故齊王贈承天皇帝挽歌', '故齊王贈承天皇帝挽歌', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["禮盛追崇日，人知友悌恩。","舊居從代邸，新隴入文園。","鴻寶仙書祕，龍旂帝服尊。","蒼蒼松裏月，萬古此高原。"]', '["禮盛追崇日，人知友悌恩。","旧居從代邸，新隴入文园。","鴻寶仙书祕，龙旂帝服尊。","蒼蒼松裏月，万古此高原。"]', '诗', 'shi', '', NULL, '故齊王贈承天皇帝挽歌 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c4ba64-a500-4b4a-8b5d-2a141ff29d57', '贈恭順皇后挽歌', '贈恭順皇后挽歌', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["徂謝年方久，哀榮事獨稀。","雖殊百兩迓，同是九泉歸。","詔使歸金策，神人送玉衣。","空山竟不從，寧肯學湘妃。"]', '["徂謝年方久，哀榮事独稀。","雖殊百兩迓，同是九泉归。","詔使归金策，神人送玉衣。","空山竟不從，寧肯学湘妃。"]', '诗', 'shi', '', NULL, '贈恭順皇后挽歌 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da41166c-15b3-454a-8abb-da16b0661591', '病中對石竹花', '病中对石竹花', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["散點空堦下，閑凝細雨中。","那能久相伴，嗟爾殢秋風。"]', '["散点空堦下，闲凝細雨中。","那能久相伴，嗟爾殢秋风。"]', '诗', 'shi', '', NULL, '病中對石竹花 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b905b4-aac5-4509-ba20-0826d15e9272', '寄鄭二侍御歸新鄭無礙寺所居', '寄鄭二侍御归新鄭無礙寺所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["何事休官早，歸來作鄭人。","雲山隨伴侶，伏臘見鄉親。","南畝無三徑，東林寄一身。","誰當便靜者，莫使甑生塵。"]', '["何事休官早，归来作鄭人。","云山隨伴侶，伏臘见乡親。","南畝無三徑，东林寄一身。","誰當便静者，莫使甑生塵。"]', '诗', 'shi', '', NULL, '寄鄭二侍御歸新鄭無礙寺所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac5a760-055d-4c66-bf4c-9baf38b78e2c', '送廬山人歸林慮山', '送廬山人归林慮山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["無論行遠近，歸向舊煙林。","寥落人家少，青冥鳥道深。","白雲長滿目，芳草自知心。"]', '["無論行远近，归向旧煙林。","寥落人家少，青冥鸟道深。","白云长满目，芳草自知心。"]', '诗', 'shi', '', NULL, '送廬山人歸林慮山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3ccf99-4d66-4826-bad5-5f177c3cec45', '送榮別駕赴華州', '送榮別駕赴华州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["直到羣峯下，應無累日程。","高車入郡舍，流水出關城。","草色田家迥，槐陰府吏迎。","還將海沂詠，籍甚漢公卿。"]', '["直到羣峯下，應無累日程。","高车入郡舍，流水出关城。","草色田家迥，槐陰府吏迎。","還將海沂詠，籍甚漢公卿。"]', '诗', 'shi', '', NULL, '送榮別駕赴華州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a2b2ac0-78ed-4a7c-adde-31d2a3b2824b', '送常大夫加散騎常侍赴朔方', '送常大夫加散騎常侍赴朔方', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["故壘煙塵後，新軍河塞間。","金貂寵漢將，玉節度蕭關。","澶漫沙中雪，依稀漢口山。","人知竇車騎，計日勒銘還。"]', '["故壘煙塵後，新軍河塞间。","金貂寵漢將，玉節度蕭关。","澶漫沙中雪，依稀漢口山。","人知竇车騎，計日勒銘還。"]', '诗', 'shi', '', NULL, '送常大夫加散騎常侍赴朔方 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ee63fe-7459-4ada-889d-ac3e5da55486', '送王翁信還剡中舊居', '送王翁信還剡中旧居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["海岸耕殘雪，溪沙釣夕陽。","客中何所有，春草漸看長。"]', '["海岸耕殘雪，溪沙釣夕陽。","客中何所有，春草漸看长。"]', '诗', 'shi', '', NULL, '送王翁信還剡中舊居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1df6b8-2a20-4b7a-b609-26b897944436', '酬張繼', '酬張繼', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["悵望南徐登北固，迢遙西塞恨東關。","落日臨川問音信，寒潮唯帶夕陽還。"]', '["悵望南徐登北固，迢遙西塞恨东关。","落日臨川问音信，寒潮唯带夕陽還。"]', '诗', 'shi', '', NULL, '酬張繼 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec75ddb-6cce-4775-b934-7a7995bc9a04', '送柳八員外赴江西', '送柳八員外赴江西', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["岐路窮無極，長江九派分。","行人隨旅雁，楚樹入湘雲。","久在征南役，何殊薊北勳。","離心不可問，歲暮雪紛紛。"]', '["岐路窮無極，长江九派分。","行人隨旅雁，楚樹入湘云。","久在征南役，何殊薊北勳。","離心不可问，歲暮雪紛紛。"]', '诗', 'shi', '', NULL, '送柳八員外赴江西 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71571867-b9ca-417e-bf05-b27816d2d277', '賦長道一絕送陸邃潛夫', '賦长道一絕送陸邃潛夫', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["高山迥欲登，遠水深難渡。","杳杳復漫漫，行人別家去。"]', '["高山迥欲登，远水深难渡。","杳杳复漫漫，行人別家去。"]', '诗', 'shi', '', NULL, '賦長道一絕送陸邃潛夫 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34aa8fc-aa37-4d16-bc86-1c9cc6362d68', '又得雲字', '又得云字', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["何事千年遇聖君，坐令雙鬢老如雲。","南行更入深山淺，岐路悠悠水自分。"]', '["何事千年遇聖君，坐令雙鬢老如云。","南行更入深山淺，岐路悠悠水自分。"]', '诗', 'shi', '', NULL, '又得雲字 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e07e347-b04c-47ba-b08b-50290aabe618', '送陸潛夫往茅山賦得華陽洞', '送陸潛夫往茅山賦得华陽洞', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["游仙洞兮訪真官，奠瑤席兮禮石壇。","忽髣髴兮雲擾，杳陰深兮夏寒。","欲迴頭兮揮手，便辭家兮可否。","有婚嫁兮嬰纏，綿歸來兮已久。"]', '["游仙洞兮訪真官，奠瑤席兮禮石壇。","忽髣髴兮云擾，杳陰深兮夏寒。","欲迴头兮揮手，便辞家兮可否。","有婚嫁兮嬰纏，綿归来兮已久。"]', '诗', 'shi', '', NULL, '送陸潛夫往茅山賦得華陽洞 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2775b4-198d-4e97-8308-2ccf925ef5b0', '又送陸潛夫茅山尋友', '又送陸潛夫茅山尋友', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["登山自補屐，訪友不齎糧。","坐嘯青楓晚，行吟白日長。","人烟隔水見，草氣入林香。","誰作招尋侶，清齋宿紫陽。"]', '["登山自補屐，訪友不齎糧。","坐嘯青楓晚，行吟白日长。","人烟隔水见，草氣入林香。","誰作招尋侶，清斋宿紫陽。"]', '诗', 'shi', '', NULL, '又送陸潛夫茅山尋友 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b63e56-a8be-4d2b-9d3e-c1d6fc1fce8d', '賦得越山三韻', '賦得越山三韻', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["西陵猶隔水，北岸已春山。","獨鳥連天去，孤雲伴客還。","秪應結茅宇，出入石林間。"]', '["西陵猶隔水，北岸已春山。","独鸟連天去，孤云伴客還。","秪應結茅宇，出入石林间。"]', '诗', 'shi', '', NULL, '賦得越山三韻 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a306145a-5a45-49e4-bcd7-4070546a0400', '送盧郎中使君赴京', '送盧郎中使君赴京', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["三年期上國，萬里自東溟。","曲蓋遵長道，油幢憩短亭。","楚雲山隱隱，淮雨草青青。","康樂多新興，題詩紀所經。"]', '["三年期上国，万里自东溟。","曲蓋遵长道，油幢憩短亭。","楚云山隐隐，淮雨草青青。","康乐多新兴，題诗紀所經。"]', '诗', 'shi', '', NULL, '送盧郎中使君赴京 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2630a36-69b2-4b0f-9073-592eb2540143', '楊氏林亭探得古槎', '楊氏林亭探得古槎', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["千年古貌多，八月秋濤晚。","偶被主人留，那知來近遠。"]', '["千年古貌多，八月秋濤晚。","偶被主人留，那知来近远。"]', '诗', 'shi', '', NULL, '楊氏林亭探得古槎 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4be0d8-c1e8-41c6-8908-14f061329e8c', '送鄭二之茅山', '送鄭二之茅山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["水流絕澗終日，草長深山暮春。","犬吠雞鳴幾處，條桑種杏何人。"]', '["水流絕澗終日，草长深山暮春。","犬吠雞鳴幾处，條桑種杏何人。"]', '诗', 'shi', '', NULL, '送鄭二之茅山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c590ce-9357-4a67-85bb-29a2402d9c33', '和王給事禁省梨花詠', '和王給事禁省梨花詠', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["巧解逢人笑，還能亂蝶飛。","春時風入戶，幾片落朝衣。"]', '["巧解逢人笑，還能亂蝶飞。","春时风入戶，幾片落朝衣。"]', '诗', 'shi', '', NULL, '和王給事禁省梨花詠 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92e5356-f7a6-4068-b44e-1e7b87fb3977', '送鄭員外入茅山居', '送鄭員外入茅山居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["但見全家去，寧知幾日還。","白雲迎谷口，流水出人間。","冠冕情遺世，神仙事滿山。","其中應有物，豈貴一身閑。"]', '["但见全家去，寧知幾日還。","白云迎谷口，流水出人间。","冠冕情遺世，神仙事满山。","其中應有物，豈貴一身闲。"]', '诗', 'shi', '', NULL, '送鄭員外入茅山居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('221ebe63-3aa2-4662-9c8e-f303d99700bb', '送志彌師往淮南', '送志彌師往淮南', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["已能持律藏，復去禮禪亭。","長老偏摩頂，時流尚誦經。","獨行寒野曠，旅宿遠山青。","眷屬空相望，鴻飛已杳冥。"]', '["已能持律藏，复去禮禪亭。","长老偏摩頂，时流尚誦經。","独行寒野曠，旅宿远山青。","眷屬空相望，鴻飞已杳冥。"]', '诗', 'shi', '', NULL, '送志彌師往淮南 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a4b0c2-fd29-4877-ae66-d5ee191930b9', '謝韋大夫柳栽', '謝韋大夫柳栽', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["本在胡笳曲，今從漢將營。","濃陰方待庇，弱植豈無情。","比雪花應吐，藏烏葉未成。","五株蒙遠賜，應使號先生。"]', '["本在胡笳曲，今從漢將營。","濃陰方待庇，弱植豈無情。","比雪花應吐，藏烏葉未成。","五株蒙远賜，應使號先生。"]', '诗', 'shi', '', NULL, '謝韋大夫柳栽 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c7dba62-fe55-41e2-a39b-baa1a128bcd8', '問李二司直所居雲山', '问李二司直所居云山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["門外水流何處，天邊樹遶誰家。","山色東西多少，朝朝幾度雲遮。"]', '["门外水流何处，天邊樹遶誰家。","山色东西多少，朝朝幾度云遮。"]', '诗', 'shi', '', NULL, '問李二司直所居雲山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da812ff-6e3d-4dc8-aff1-132b9ca701f7', '劉侍御朝命許停官歸侍', '劉侍御朝命許停官归侍', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["孟孫唯問孝，萊子復辭官。","幸遂溫凊願，其甘稼穡難。","採芝供上藥，拾槿奉晨餐。","棟裏雲藏雨，山中暑帶寒。","非時應有筍，閑地盡生蘭。","賜告承優詔，長筵永日歡。"]', '["孟孫唯问孝，萊子复辞官。","幸遂溫凊願，其甘稼穡难。","採芝供上藥，拾槿奉晨餐。","棟裏云藏雨，山中暑带寒。","非时應有筍，闲地尽生蘭。","賜告承優詔，长筵永日歡。"]', '诗', 'shi', '', NULL, '劉侍御朝命許停官歸侍 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc4fd7fb-829d-4d74-ab63-36071c7608fe', '送陸鴻漸赴越', '送陸鴻漸赴越', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["行隨新樹深，夢隔重江遠。","迢遞風日間，蒼茫洲渚晚。"]', '["行隨新樹深，梦隔重江远。","迢遞风日间，蒼茫洲渚晚。"]', '诗', 'shi', '', NULL, '送陸鴻漸赴越 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde03de2-0282-4563-8c84-b3611dfa199e', '送竇叔向', '送竇叔向', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["楚客怨逢秋，閑吟興非一。","棄官守貧病，作賦推文律。","樵徑未經霜，茅簷初負日。","今看泛月去，偶見乘潮出。","卜地會爲隣，還依仲長室。"]', '["楚客怨逢秋，闲吟兴非一。","棄官守貧病，作賦推文律。","樵徑未經霜，茅簷初負日。","今看泛月去，偶见乘潮出。","卜地會爲隣，還依仲长室。"]', '诗', 'shi', '', NULL, '送竇叔向 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c647e0b-f398-4dd3-817d-0c9fe9b45e76', '題蔣道士房', '題蔣道士房', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["軒窗縹緲起烟霞，誦訣存思白日斜。","聞道崑崙有仙籍，何時青鳥送丹砂。"]', '["軒窗縹緲起烟霞，誦訣存思白日斜。","闻道崑崙有仙籍，何时青鸟送丹砂。"]', '诗', 'shi', '', NULL, '題蔣道士房 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca19ac56-15aa-4e6b-8577-787e9aa92ffd', '夜集張諲所居', '夜集張諲所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江南成久客，門館日蕭條。","惟有圖書在，多傷鬢髮凋。","諸生陪講誦，稚子給漁樵。","虛室寒燈靜，空堦落葉飄。","滄洲自有趣，誰道隱須招。"]', '["江南成久客，门館日蕭條。","惟有圖书在，多傷鬢髮凋。","諸生陪講誦，稚子給漁樵。","虛室寒灯静，空堦落葉飄。","滄洲自有趣，誰道隐須招。"]', '诗', 'shi', '', NULL, '夜集張諲所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5e55e2-a107-4a1b-8ce7-5e4b8204fe2d', '酬權器', '酬權器', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["南望江南滿山雪，此情惆悵將誰說。","徒隨羣吏不曾閑，顧與諸生爲久別。","聞君靜坐轉耽書，種樹葺茅還舊居。","終日白雲應自足，明年芳草又何如。","人生有懷若不展，出入公門猶未免。","迴舟朝夕待春風，先報華陽洞深淺。"]', '["南望江南满山雪，此情惆悵將誰说。","徒隨羣吏不曾闲，顧與諸生爲久別。","闻君静坐轉耽书，種樹葺茅還旧居。","終日白云應自足，明年芳草又何如。","人生有懷若不展，出入公门猶未免。","迴舟朝夕待春风，先報华陽洞深淺。"]', '诗', 'shi', '', NULL, '酬權器 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('080a9610-9c99-4c53-88ad-b299396e09cc', '寄劉方平大谷田家', '寄劉方平大谷田家', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["故山聞獨往，樵路憶相從。","冰結泉聲絕，霜清野翠濃。","籬邊潁陽道，竹外少姨峯。","日夕田家務，寒煙隔幾重。"]', '["故山闻独往，樵路憶相從。","冰結泉声絕，霜清野翠濃。","籬邊潁陽道，竹外少姨峯。","日夕田家務，寒煙隔幾重。"]', '诗', 'shi', '', NULL, '寄劉方平大谷田家 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11197ba-a106-4b45-832d-7445f702bb7f', '送雲陽少府', '送云陽少府', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["渭曲春光無遠近，池陽谷口倍芳菲。","官舍村橋來幾日，殘花寥落待君歸。"]', '["渭曲春光無远近，池陽谷口倍芳菲。","官舍村橋来幾日，殘花寥落待君归。"]', '诗', 'shi', '', NULL, '送雲陽少府 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acac9e5-60e9-42cf-a8dc-f667520717a5', '魯山送別', '魯山送別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["淒淒遊子若飄蓬，明月清罇秪暫同。","南望千山如黛色，愁君客路在其中。"]', '["淒淒游子若飄蓬，明月清罇秪暫同。","南望千山如黛色，愁君客路在其中。"]', '诗', 'shi', '', NULL, '魯山送別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b128d9-264f-48b0-83e9-751db7dbb08e', '題高雲客舍', '題高云客舍', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["孤興日自深，浮雲非所仰。","窗中西城峻，樹外東川廣。","晏起簪葛巾，閑吟倚藜杖。","阮公道在醉，莊子生常養。","五柳轉扶疎，千峰恣來往。","清秋香秔穫，白露寒菜長。","吳國滯風煙，平陵延夢想。","時人趨纓弁，高鳥違羅網。","世事徒亂紛，吾心方浩蕩。","唯將山與水，處處諧真賞。"]', '["孤兴日自深，浮云非所仰。","窗中西城峻，樹外东川廣。","晏起簪葛巾，闲吟倚藜杖。","阮公道在醉，莊子生常養。","五柳轉扶疎，千峰恣来往。","清秋香秔穫，白露寒菜长。","吳国滯风煙，平陵延梦想。","时人趨纓弁，高鸟違羅網。","世事徒亂紛，吾心方浩蕩。","唯將山與水，处处諧真賞。"]', '诗', 'shi', '', NULL, '題高雲客舍 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8364f1e-c63c-4df1-8772-e856094fef55', '臺頭寺願上人院古松下有小松裁毫末新生與纖草不辨重其有凌雲干霄之志與趙八員外裴十補闕同賦之', '台头寺願上人院古松下有小松裁毫末新生與纖草不辨重其有凌云干霄之志與趙八員外裴十補闕同賦之', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["細草亦全高，秋毫乍堪比。","及至干霄日，何人復居此。"]', '["細草亦全高，秋毫乍堪比。","及至干霄日，何人复居此。"]', '诗', 'shi', '', NULL, '臺頭寺願上人院古松下有小松裁毫末新生與纖草不辨重其有凌雲干霄之志與趙八員外裴十補闕同賦之 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55328a4d-e257-41c4-a83d-73c11be06e62', '漁子溝寄趙員外裴補闕', '漁子溝寄趙員外裴補闕', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["欲逐淮潮上，暫停漁子溝。","相望知不見，終是屢迴頭。"]', '["欲逐淮潮上，暫停漁子溝。","相望知不见，終是屢迴头。"]', '诗', 'shi', '', NULL, '漁子溝寄趙員外裴補闕 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8f040e-f5ba-40a9-b3ef-d1837281540c', '送崔使君赴壽州', '送崔使君赴壽州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["列郡專城分國憂，彤幨皂蓋古諸侯。","仲華遇主年猶少，公瑾論兵位已酬。","草色青青宜建隼，蟬聲處處雜鳴騶。","千里相思如可見，淮南木落早驚秋。"]', '["列郡專城分国憂，彤幨皂蓋古諸侯。","仲华遇主年猶少，公瑾論兵位已酬。","草色青青宜建隼，蟬声处处杂鳴騶。","千里相思如可见，淮南木落早驚秋。"]', '诗', 'shi', '', NULL, '送崔使君赴壽州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152b72c8-0e20-4cf2-9877-c843aeab9cd0', '送謝十二判官', '送謝十二判官', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["四牡驅馳千里餘，越山稠疊海林疎。","不辭終日離家遠，應爲劉公一紙書。"]', '["四牡驱驰千里餘，越山稠叠海林疎。","不辞終日離家远，應爲劉公一紙书。"]', '诗', 'shi', '', NULL, '送謝十二判官 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab25516-bd98-4407-964a-0292fef55d0f', '送處州裴使君赴京', '送处州裴使君赴京', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["使君朝北闕，車騎發東方。","別喜天書召，寧憂地脉長。","山行朝復夕，水宿露爲霜。","秋草連秦塞，孤帆落漢陽。","新銜趨建禮，舊位識文昌。","唯有東歸客，應隨南雁翔。"]', '["使君朝北闕，车騎發东方。","別喜天书召，寧憂地脉长。","山行朝复夕，水宿露爲霜。","秋草連秦塞，孤帆落漢陽。","新銜趨建禮，旧位識文昌。","唯有东归客，應隨南雁翔。"]', '诗', 'shi', '', NULL, '送處州裴使君赴京 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2597fae-4bb7-4c37-9c3a-ab09606f06a5', '送田濟之揚州赴選', '送田濟之揚州赴選', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["家貧不自給，求祿爲荒年。","調補無高位，卑棲屈此賢。","江山欲霜雪，吳楚接風煙。","相去誠非遠，離心亦渺然。"]', '["家貧不自給，求祿爲荒年。","調補無高位，卑棲屈此賢。","江山欲霜雪，吳楚接风煙。","相去誠非远，離心亦渺然。"]', '诗', 'shi', '', NULL, '送田濟之揚州赴選 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0766c4f-76e3-405a-958c-b4476ab23e3d', '送袁郎中破賊北歸', '送袁郎中破賊北归', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["優詔親賢時獨稀，中途紫紱（一作「綬」）換征衣。","黃香省闥登朝去，楊僕樓船振旅歸。","萬里長聞隨戰角，十年不得掩（一作「偃」）郊扉。","囗囗囗囗囗囗囗，但將詞賦奉恩輝。"]', '["優詔親賢时独稀，中途紫紱（一作「綬」）換征衣。","黄香省闥登朝去，楊僕楼船振旅归。","万里长闻隨戰角，十年不得掩（一作「偃」）郊扉。","囗囗囗囗囗囗囗，但將词賦奉恩輝。"]', '诗', 'shi', '', NULL, '送袁郎中破賊北歸 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62d9973-ad95-4f49-8221-bd3805be0a15', '同李萬晚望南岳寺懷普門上人', '同李万晚望南岳寺懷普门上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["釋子身心無垢紛，獨將衣鉢去人羣。","相思晚望松林寺，唯有鐘聲出白雲。"]', '["釋子身心無垢紛，独將衣鉢去人羣。","相思晚望松林寺，唯有鐘声出白云。"]', '诗', 'shi', '', NULL, '同李萬晚望南岳寺懷普門上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36117dc6-7425-4fea-a2b2-738bbfadd40d', '奉和獨孤中丞遊法華寺', '奉和独孤中丞游法华寺', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["謝君臨郡府，越國舊山川。","訪道三千界，當仁五百年。","巖空騶馭響，樹密斾旌連。","閣影凌空壁，松聲助亂泉。","開門得初地，伏檻接諸天。","向背春光滿，樓臺古制全。","羣峰爭彩翠，百谷會風煙。","香象隨僧久，祥烏報客先。","清心乘暇日，稽首慕良緣。","法證無生偈，詩成大雅篇。","蒼生望已久，迴駕獨依然。"]', '["謝君臨郡府，越国旧山川。","訪道三千界，當仁五百年。","巖空騶馭响，樹密斾旌連。","閣影凌空壁，松声助亂泉。","开门得初地，伏檻接諸天。","向背春光满，楼台古制全。","羣峰爭彩翠，百谷會风煙。","香象隨僧久，祥烏報客先。","清心乘暇日，稽首慕良緣。","法證無生偈，诗成大雅篇。","蒼生望已久，迴駕独依然。"]', '诗', 'shi', '', NULL, '奉和獨孤中丞遊法華寺 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e7530f-9d5c-474b-b032-44c063c6b4b8', '之京留別劉方平', '之京留別劉方平', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["客子慕儔侶，含悽整晨裝。","邀歡日不足，況乃前期長。","離袂惜嘉月，遠還勞折芳。","遲迴越二陵，迴首但蒼茫。","喬木清宿雨，故關愁夕陽。","人言長安樂，其奈緬相望。"]', '["客子慕儔侶，含悽整晨裝。","邀歡日不足，況乃前期长。","離袂惜嘉月，远還勞折芳。","遲迴越二陵，迴首但蒼茫。","喬木清宿雨，故关愁夕陽。","人言长安乐，其奈緬相望。"]', '诗', 'shi', '', NULL, '之京留別劉方平 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ccd05d-1251-403b-8e43-8586d08d43bf', '出塞', '出塞', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["吹角出塞門，前瞻即胡地。","三軍盡迴首，皆洒望鄉淚。","轉念關山長，行看風景異。","由來征戍客，負得輕生義。"]', '["吹角出塞门，前瞻即胡地。","三軍尽迴首，皆洒望乡泪。","轉念关山长，行看风景異。","由来征戍客，負得轻生義。"]', '诗', 'shi', '', NULL, '出塞 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6318c4-f7d2-4bc8-b136-bd84d6a744c8', '赴李少府莊失路', '赴李少府莊失路', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["君家南郭白雲連，正待情人弄石泉。","月照煙花迷客路，蒼蒼何處是伊川。"]', '["君家南郭白云連，正待情人弄石泉。","月照煙花迷客路，蒼蒼何处是伊川。"]', '诗', 'shi', '', NULL, '赴李少府莊失路 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5ff5a6-546b-45fc-8812-6ab998d2aa6b', '雨雪', '雨雪', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["風沙悲久戍，雨雪更勞師。","絕漠無人境，將軍苦戰時。","山川迷向背，氛霧失旌旗。","徒念天涯隔，中人芳草期。"]', '["风沙悲久戍，雨雪更勞師。","絕漠無人境，將軍苦戰时。","山川迷向背，氛霧失旌旗。","徒念天涯隔，中人芳草期。"]', '诗', 'shi', '', NULL, '雨雪 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd66da21-8b24-4c95-85ea-0a303f8c644f', '館陶李丞舊居', '館陶李丞旧居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["盛名天下挹餘芳，棄置終身不拜郎。","詞藻世傳平子賦，園林人比鄭公鄉。","門前墜葉浮秋水，籬外寒臯帶夕陽。","日日青松成古木，秪應來者爲心傷。"]', '["盛名天下挹餘芳，棄置終身不拜郎。","词藻世傳平子賦，园林人比鄭公乡。","门前墜葉浮秋水，籬外寒臯带夕陽。","日日青松成古木，秪應来者爲心傷。"]', '诗', 'shi', '', NULL, '館陶李丞舊居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b2e218-b707-4c23-8836-61e38c4071c0', '送劉兵曹還隴山居', '送劉兵曹還隴山居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["離堂徒讌語，行子但悲辛。","雖是還家路，終爲隴上人。","先秋雪已滿，近夏草初新。","唯有聞羌笛，梅花曲裏春。"]', '["離堂徒讌語，行子但悲辛。","雖是還家路，終爲隴上人。","先秋雪已满，近夏草初新。","唯有闻羌笛，梅花曲裏春。"]', '诗', 'shi', '', NULL, '送劉兵曹還隴山居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39702ba-5835-461f-ae4f-4fc597c65478', '同李三月夜作', '同李三月夜作', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["霜風驚度雁，月露皓疎林。","處處砧聲發，星河秋夜深。"]', '["霜风驚度雁，月露皓疎林。","处处砧声發，星河秋夜深。"]', '诗', 'shi', '', NULL, '同李三月夜作 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a25e64b-b1b8-48ec-9f95-4a76f6dd3ff2', '同裴少府安居寺對雨', '同裴少府安居寺对雨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["共結尋真會，還當退食初。","爐煙雲氣合，林葉雨聲餘。","溽暑銷珍簟，浮涼入綺疏。","歸心從念遠，懷此復何如。"]', '["共結尋真會，還當退食初。","爐煙云氣合，林葉雨声餘。","溽暑銷珍簟，浮涼入綺疏。","归心從念远，懷此复何如。"]', '诗', 'shi', '', NULL, '同裴少府安居寺對雨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d101812-9feb-4523-aa14-dd96caf5fd5d', '送元晟歸潛山所居', '送元晟归潛山所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["深山秋事早，君去復何如。","裛露收新稼，迎寒葺舊廬。","題詩即招隱，作賦是閑居。","別後空相憶，嵇康懶寄書。"]', '["深山秋事早，君去复何如。","裛露收新稼，迎寒葺旧廬。","題诗即招隐，作賦是闲居。","別後空相憶，嵇康懶寄书。"]', '诗', 'shi', '', NULL, '送元晟歸潛山所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24060346-883e-4d15-9007-9121b5a10eff', '送康判官徃新安賦得江路西南永', '送康判官徃新安賦得江路西南永', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["不向新安去，那知江路長。","猿聲比廬霍，水色勝瀟湘。","驛樹收殘雨，漁家帶夕陽。","何須愁旅泊，使者有輝光。"]', '["不向新安去，那知江路长。","猿声比廬霍，水色勝瀟湘。","驛樹收殘雨，漁家带夕陽。","何須愁旅泊，使者有輝光。"]', '诗', 'shi', '', NULL, '送康判官徃新安賦得江路西南永 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1822c0b1-b888-4feb-a745-192eef167303', '宿洞靈觀', '宿洞靈观', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["孤煙靈洞遠，積雪滿山寒。","松柏凌高殿，莓苔封古壇。","客來清夜久，仙去白雲殘。","明日開金籙，焚香更沐蘭。"]', '["孤煙靈洞远，積雪满山寒。","松柏凌高殿，莓苔封古壇。","客来清夜久，仙去白云殘。","明日开金籙，焚香更沐蘭。"]', '诗', 'shi', '', NULL, '宿洞靈觀 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e525dc74-ca9f-4989-b18d-d0934171f5e7', '酬盧十一過宿', '酬盧十一過宿', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["乞還方未遂，日夕望雲林。","況復逢春草，何勞問此心。","閉門公務散，枉策故情深。","遙夜他鄉酒，同君梁甫吟。"]', '["乞還方未遂，日夕望云林。","況复逢春草，何勞问此心。","閉门公務散，枉策故情深。","遙夜他乡酒，同君梁甫吟。"]', '诗', 'shi', '', NULL, '酬盧十一過宿 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87562913-27dd-49a5-9710-b0c9f64452eb', '酬裴十四', '酬裴十四', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["淮海各聯翩，三年方一見。","素心終不易，玄髮何須變。","舊國想平陵，春山滿陽羨。","隣雞莫遽唱，共惜良夜晏。"]', '["淮海各聯翩，三年方一见。","素心終不易，玄髮何須变。","旧国想平陵，春山满陽羨。","隣雞莫遽唱，共惜良夜晏。"]', '诗', 'shi', '', NULL, '酬裴十四 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b3d5e66-eee6-4e65-b79c-1089a5c74b6b', '彭祖井', '彭祖井', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["上公旌節在徐方，舊井莓苔近寢堂。","訪古因知彭祖宅，得仙何必葛洪鄉。","清虛不共春池竟，盥漱偏宜夏日長。","聞道延年如玉液，欲將調鼎獻明光。"]', '["上公旌節在徐方，旧井莓苔近寢堂。","訪古因知彭祖宅，得仙何必葛洪乡。","清虛不共春池竟，盥漱偏宜夏日长。","闻道延年如玉液，欲將調鼎獻明光。"]', '诗', 'shi', '', NULL, '彭祖井 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cb665f-b8db-47ed-a098-da4898307a88', '奉和對雪', '奉和对雪', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["春雪偏當夜，暄風却變寒。","庭深不復掃，城曉更宜看。","命酒閑令酌，披蓑晚未冠。","連營鼓角動，忽似戰桑乾。"]', '["春雪偏當夜，暄风却变寒。","庭深不复掃，城晓更宜看。","命酒闲令酌，披蓑晚未冠。","連營鼓角动，忽似戰桑乾。"]', '诗', 'shi', '', NULL, '奉和對雪 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f92806c-9ee2-45a3-a49e-622a79dc64c3', '送蕭獻士', '送蕭獻士', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["惆悵煙郊晚，依然此送君。","長河隔旅夢，浮客伴孤雲。","淇上春山直，黎陽大道分。","西陵倘一弔，應有士衡文。"]', '["惆悵煙郊晚，依然此送君。","长河隔旅梦，浮客伴孤云。","淇上春山直，黎陽大道分。","西陵倘一弔，應有士衡文。"]', '诗', 'shi', '', NULL, '送蕭獻士 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('108c29ef-0144-49b3-a8e4-5e6b04bf29f8', '賣藥人處得南陽朱山人書', '賣藥人处得南陽朱山人书', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["賣藥何爲者，逃名市井居。","唯通遠山信，因致逸人書。","已報還丹効，全將世事疎。","秋風景溪裏，蕭散寄樵漁。"]', '["賣藥何爲者，逃名市井居。","唯通远山信，因致逸人书。","已報還丹効，全將世事疎。","秋风景溪裏，蕭散寄樵漁。"]', '诗', 'shi', '', NULL, '賣藥人處得南陽朱山人書 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db71c2b-dba6-4622-8382-70f0aea43c85', '初出沅江夜入湖', '初出沅江夜入湖', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["放溜出江口，迴瞻松栝深。","不知舟中月，更引湖間心。"]', '["放溜出江口，迴瞻松栝深。","不知舟中月，更引湖间心。"]', '诗', 'shi', '', NULL, '初出沅江夜入湖 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa0e86a-df58-49e9-bba2-35b7eeef4b33', '送裴員外往江南', '送裴員外往江南', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["分務江南遠，留歡幕下榮。","楓林縈楚塞，水驛到湓城。","岸草知春晚，沙禽好夜驚。","風帆幾泊處，處處暮潮清。"]', '["分務江南远，留歡幕下榮。","楓林縈楚塞，水驛到湓城。","岸草知春晚，沙禽好夜驚。","风帆幾泊处，处处暮潮清。"]', '诗', 'shi', '', NULL, '送裴員外往江南 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9969339c-9e80-49bf-89f7-0237a863da08', '奉和王相公早春登徐州城', '奉和王相公早春登徐州城', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["落日憑危堞，春風似故鄉。","川流通楚塞，山色遶徐方。","壁壘依寒草，旌旗動夕陽。","元戎資上策，南畝起耕桑。"]', '["落日憑危堞，春风似故乡。","川流通楚塞，山色遶徐方。","壁壘依寒草，旌旗动夕陽。","元戎資上策，南畝起耕桑。"]', '诗', 'shi', '', NULL, '奉和王相公早春登徐州城 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c612488c-7df4-4769-8be5-d708a26d7a17', '奉和對山僧', '奉和对山僧', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["吏散重門掩，僧來閉閣閑。","遠心馳北闕，春興寄東山。","草長風光裏，鶯喧靜默間。","芳辰不可住，惆悵暮禽還。"]', '["吏散重门掩，僧来閉閣闲。","远心驰北闕，春兴寄东山。","草长风光裏，鶯喧静默间。","芳辰不可住，惆悵暮禽還。"]', '诗', 'shi', '', NULL, '奉和對山僧 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafa92f3-7a8a-48ef-9b5a-fb02ebd9100e', '奉和待勤照上人不至', '奉和待勤照上人不至', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["東洛居賢相，南方待本師。","旌麾儼欲動，杯錫杳仍遲。","積雪迷何處，驚風泊幾時。","大臣能護法，況有故山期。"]', '["东洛居賢相，南方待本師。","旌麾儼欲动，杯錫杳仍遲。","積雪迷何处，驚风泊幾时。","大臣能護法，況有故山期。"]', '诗', 'shi', '', NULL, '奉和待勤照上人不至 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ebfd744-60e2-4fa9-aa54-23f3f1b0e7ca', '奉和漢祖廟下之作', '奉和漢祖廟下之作', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["古廟風煙積，春城車騎過。","方修漢祖祀，更使沛童歌。","寢帳巢禽出，香煙水霧和。","神心降福處，應在故鄉多。"]', '["古廟风煙積，春城车騎過。","方修漢祖祀，更使沛童歌。","寢帳巢禽出，香煙水霧和。","神心降福处，應在故乡多。"]', '诗', 'shi', '', NULL, '奉和漢祖廟下之作 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3d8dc7-29bf-49d0-a109-ef9cfa7f20e1', '和朝郎中揚子翫雪寄山陰嚴維', '和朝郎中揚子翫雪寄山陰嚴維', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["凝陰晦長箔，積雪滿通川。","征客寒猶去，愁人晝更眠。","謝家興詠日，漢將出師年。","聞有招尋興，隨君訪戴船。"]', '["凝陰晦长箔，積雪满通川。","征客寒猶去，愁人晝更眠。","謝家兴詠日，漢將出師年。","闻有招尋兴，隨君訪戴船。"]', '诗', 'shi', '', NULL, '和朝郎中揚子翫雪寄山陰嚴維 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36794e1-c8aa-43e4-88ab-350d79324e6c', '閑居作', '闲居作', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["多病辭官罷，閑居作賦成。","圖書唯藥籙，飲食止藜羹。","學謝淹中術，詩無鄴下名。","不堪趨建禮，詎是厭承明。","已輟金門步，方從石路行。","遠山期道士，高柳覓先生。","性懶尤因疾，家貧自省營。","種苗雖尚短，穀價幸全輕。","篇詠投康樂，壺觴就步兵。","何人肯相訪，開戶一逢迎。"]', '["多病辞官罷，闲居作賦成。","圖书唯藥籙，饮食止藜羹。","学謝淹中術，诗無鄴下名。","不堪趨建禮，詎是厭承明。","已輟金门步，方從石路行。","远山期道士，高柳覓先生。","性懶尤因疾，家貧自省營。","種苗雖尚短，穀價幸全轻。","篇詠投康乐，壺觴就步兵。","何人肯相訪，开戶一逢迎。"]', '诗', 'shi', '', NULL, '閑居作 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e52513d-af49-40cf-92d8-f8d239122e0d', '歸渡洛水', '归渡洛水', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["暝色赴春愁，歸人南渡頭。","渚煙空翠合，灘月碎光流。","澧浦饒芳草，滄浪有釣舟。","誰知放歌客，此意正悠悠。"]', '["暝色赴春愁，归人南渡头。","渚煙空翠合，灘月碎光流。","澧浦饒芳草，滄浪有釣舟。","誰知放歌客，此意正悠悠。"]', '诗', 'shi', '', NULL, '歸渡洛水 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f76fe3df-fb0e-4d06-bd55-9e726ef336ca', '送鄭二員外', '送鄭二員外', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["置酒竟長宵，送君登遠道。","羇心看旅雁，晚泊依秋草。","秋草尚芊芊，離憂亦渺然。","元戎辟才彥，行子犯風煙。","風煙積惆悵，淮海殊飄蕩。","明日是重陽，登高遠相望。"]', '["置酒竟长宵，送君登远道。","羇心看旅雁，晚泊依秋草。","秋草尚芊芊，離憂亦渺然。","元戎辟才彥，行子犯风煙。","风煙積惆悵，淮海殊飄蕩。","明日是重陽，登高远相望。"]', '诗', 'shi', '', NULL, '送鄭二員外 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b33f522-6586-4fb7-95ea-782bc0c7699d', '酬崔侍御期籍道士不至兼寄', '酬崔侍御期籍道士不至兼寄', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["一心求妙道，幾歲候真師。","丹竈今何在，白雲無定期。","崑崙煙景絕，汗漫徃還遲。","君但焚香待，人間到有時。"]', '["一心求妙道，幾歲候真師。","丹竈今何在，白云無定期。","崑崙煙景絕，汗漫徃還遲。","君但焚香待，人间到有时。"]', '诗', 'shi', '', NULL, '酬崔侍御期籍道士不至兼寄 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f925ab31-9181-424a-b450-06933382fd4d', '送裴陟歸常州', '送裴陟归常州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["夜雨須停棹，秋風暗入衣。","見君嘗北望，何事却南歸。"]', '["夜雨須停棹，秋风暗入衣。","见君嘗北望，何事却南归。"]', '诗', 'shi', '', NULL, '送裴陟歸常州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392fb0df-c212-454b-a99c-fb5c64479e29', '贈別', '贈別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["南橋春日暮，楊柳帶青渠。","不得同攜手，空成意有餘。"]', '["南橋春日暮，楊柳带青渠。","不得同携手，空成意有餘。"]', '诗', 'shi', '', NULL, '贈別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe69e18-fe22-4ea1-92b1-98ecf305d7dc', '和袁郎中破賊後經剡中山水', '和袁郎中破賊後經剡中山水', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["武庫分帷幄，儒衣事鼓鼙。","兵連越徼外，寇盡海門西。","節比全疎勒，功當雪會稽。","旌旗迴剡嶺，士馬濯耶溪。","受律梅初發，班師草未齊。","行看佩金印，豈得訪丹梯。"]', '["武庫分帷幄，儒衣事鼓鼙。","兵連越徼外，寇尽海门西。","節比全疎勒，功當雪會稽。","旌旗迴剡嶺，士马濯耶溪。","受律梅初發，班師草未齊。","行看佩金印，豈得訪丹梯。"]', '诗', 'shi', '', NULL, '和袁郎中破賊後經剡中山水 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2e77fa-3093-46bd-837e-08dc3934ada6', '徐州送丘侍御之越', '徐州送丘侍御之越', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["時鳥催春色，離人惜歲華。","遠山隨擁傳，芳草引還家。","北固潮當闊，西陵路稍斜。","縱令寒食過，猶有鏡中花。"]', '["时鸟催春色，離人惜歲华。","远山隨擁傳，芳草引還家。","北固潮當闊，西陵路稍斜。","縱令寒食過，猶有镜中花。"]', '诗', 'shi', '', NULL, '徐州送丘侍御之越 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b205910-b529-4b37-9cf0-b7587247f582', '閑居', '闲居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["桃紅復含宿雨，柳綠更帶春煙。","花落家童未掃，鶯啼山客猶眠。"]', '["桃紅复含宿雨，柳綠更带春煙。","花落家童未掃，鶯啼山客猶眠。"]', '诗', 'shi', '', NULL, '閑居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77588ed6-70a6-465e-bb2f-3f7d27fc4640', '送延陵陳法師赴上元', '送延陵陳法師赴上元', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["延陵初罷講，建業去隨緣。","翻譯推多學，壇場最少年。","浣衣逢野水，乞食向人煙。","遍禮南朝寺，焚香古像前。"]', '["延陵初罷講，建業去隨緣。","翻譯推多学，壇場最少年。","浣衣逢野水，乞食向人煙。","遍禮南朝寺，焚香古像前。"]', '诗', 'shi', '', NULL, '送延陵陳法師赴上元 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec010d67-8a54-4e4e-a830-40b8e4bb9e6a', '賦得海邊樹', '賦得海邊樹', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["歷歷緣荒岸，溟溟入遠天。","每同沙草發，長共水雲連。","搖落潮風早，離披海雨偏。","故傷遊子意，多在客舟前。"]', '["歷歷緣荒岸，溟溟入远天。","每同沙草發，长共水云連。","搖落潮风早，離披海雨偏。","故傷游子意，多在客舟前。"]', '诗', 'shi', '', NULL, '賦得海邊樹 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3974504-f89f-4aa0-9400-ef0ef6de1e55', '題昭上人房', '題昭上人房', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["沃州傳敎後，百衲老空林。","慮盡朝昏磬，禪隨坐臥心。","鶴飛湖草迥，門閉野雲深。","地與天台接，中峯早晚尋。"]', '["沃州傳敎後，百衲老空林。","慮尽朝昏磬，禪隨坐臥心。","鹤飞湖草迥，门閉野云深。","地與天台接，中峯早晚尋。"]', '诗', 'shi', '', NULL, '題昭上人房 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024e0857-25ec-40a8-8218-8dda78d89c77', '送李使君赴撫州', '送李使君赴撫州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["遠送臨川守，還同康樂侯。","歲時徒改易，今古接風流。","五馬嘶長道，雙旌向本州。","鄉心寄西北，應上郡城樓。"]', '["远送臨川守，還同康乐侯。","歲时徒改易，今古接风流。","五马嘶长道，雙旌向本州。","乡心寄西北，應上郡城楼。"]', '诗', 'shi', '', NULL, '送李使君赴撫州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbd3aaa-c910-4c4a-89d5-bc04a6ec6ca7', '同樊潤州遊郡東山', '同樊潤州游郡东山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["北固多陳迹，東山復盛遊。","鐃聲發大道，草色引行騶。","此地何時有，長江自古流。","頻隨公府步，南客寄徐州。"]', '["北固多陳迹，东山复盛游。","鐃声發大道，草色引行騶。","此地何时有，长江自古流。","頻隨公府步，南客寄徐州。"]', '诗', 'shi', '', NULL, '同樊潤州遊郡東山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('134b31c7-78cc-460d-b338-6994da4cbaad', '酬楊侍御寺中見招', '酬楊侍御寺中见招', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["貧居依柳市，閑步在蓮宮。","高閣宜春雨，長廊好嘯風。","誠如雙樹下，豈比一丘中。"]', '["貧居依柳市，闲步在蓮宮。","高閣宜春雨，长廊好嘯风。","誠如雙樹下，豈比一丘中。"]', '诗', 'shi', '', NULL, '酬楊侍御寺中見招 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95161070-6601-4b08-89ad-b4b3f9444e6e', '重陽日酬李觀', '重陽日酬李观', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["不見白衣來送酒，但令黃菊自開花。","愁看日晚良辰過，步步行尋陶令家。"]', '["不见白衣来送酒，但令黄菊自开花。","愁看日晚良辰過，步步行尋陶令家。"]', '诗', 'shi', '', NULL, '重陽日酬李觀 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a39188e-47fd-4e3f-9b87-3754a672273d', '寄權器', '寄權器', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["露濕青蕪時欲晚，水流黃葉意無窮。","節近重陽念歸否，眼前籬菊帶秋風。"]', '["露濕青蕪时欲晚，水流黄葉意無窮。","節近重陽念归否，眼前籬菊带秋风。"]', '诗', 'shi', '', NULL, '寄權器 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6d74a4-9808-4fed-8678-d1ea19674690', '酬李判官度梨嶺見寄', '酬李判官度梨嶺见寄', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["隴首怨西征，嶺南雁北顧。","行人與流水，共向閩中去。"]', '["隴首怨西征，嶺南雁北顧。","行人與流水，共向閩中去。"]', '诗', 'shi', '', NULL, '酬李判官度梨嶺見寄 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1f199d7-7965-4a66-8c47-613420d00749', '送魏六侍御葬', '送魏六侍御葬', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["哭葬寒郊外，行將何所從。","盛曹徒列柏，新墓已栽松。","海月同千古，江雲覆幾重。","舊書曾諫獵，遺草議登封。","疇昔輕三事，嘗期老一峯。","門臨商嶺道，窗引洛城鐘。","應積泉中恨，無因世上逢。","招尋偏見厚，疎慢亦相容。","張范唯通夢，求羊永絕蹤。","誰知長卿疾，歌賦不還邛。"]', '["哭葬寒郊外，行將何所從。","盛曹徒列柏，新墓已栽松。","海月同千古，江云覆幾重。","旧书曾諫獵，遺草議登封。","疇昔轻三事，嘗期老一峯。","门臨商嶺道，窗引洛城鐘。","應積泉中恨，無因世上逢。","招尋偏见厚，疎慢亦相容。","張范唯通梦，求羊永絕蹤。","誰知长卿疾，歌賦不還邛。"]', '诗', 'shi', '', NULL, '送魏六侍御葬 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e23c830-7db2-4780-96e5-a4940d1b8ed3', '送張道士歸茅山謁李尊師', '送張道士归茅山謁李尊師', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["向山獨有一人行，近洞應逢雙鶴迎。","嘗以素書傳弟子，還因白石號先生。","無窮杏樹行時種，幾許芝田向月耕。","師事少君年歲久，欲隨旄節徃層城。"]', '["向山独有一人行，近洞應逢雙鹤迎。","嘗以素书傳弟子，還因白石號先生。","無窮杏樹行时種，幾許芝田向月耕。","師事少君年歲久，欲隨旄節徃層城。"]', '诗', 'shi', '', NULL, '送張道士歸茅山謁李尊師 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6eb64a-78b1-4b36-93a8-5d96cd7651d9', '詶裴補闕吳寺見尋', '詶裴補闕吳寺见尋', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["東林初結構，已有晚鐘聲。","窻戶背流水，房廊半架城。","遠山重疊見，芳草淺深生。","每與君攜手，多煩長老迎。"]', '["东林初結構，已有晚鐘声。","窻戶背流水，房廊半架城。","远山重叠见，芳草淺深生。","每與君携手，多煩长老迎。"]', '诗', 'shi', '', NULL, '詶裴補闕吳寺見尋 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867523a0-6b22-4002-84e8-655273265d11', '送王相公之幽州', '送王相公之幽州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["自昔蕭曹任，難兼衛霍功。","勤勞無遠近，旌節屢西東。","不選三河卒，還令萬里通。","雁行緣古塞，馬鬣起長風。","遮虜關山靜，防秋鼓角雄。","徒思一攀送，羸老蓽門中。"]', '["自昔蕭曹任，难兼衛霍功。","勤勞無远近，旌節屢西东。","不選三河卒，還令万里通。","雁行緣古塞，马鬣起长风。","遮虜关山静，防秋鼓角雄。","徒思一攀送，羸老蓽门中。"]', '诗', 'shi', '', NULL, '送王相公之幽州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd80d8ef-c061-4d52-bb4e-3b364ef260b2', '題竹扇贈別', '題竹扇贈別', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["湘竹殊堪製，齊紈且未工。","幸親芳袖日，尤帶舊林風。","掩笑歌筵裏，傳書臥閣中。","竟將爲別贈，寧與合歡同。"]', '["湘竹殊堪製，齊紈且未工。","幸親芳袖日，尤带旧林风。","掩笑歌筵裏，傳书臥閣中。","竟將爲別贈，寧與合歡同。"]', '诗', 'shi', '', NULL, '題竹扇贈別 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b459aba9-305c-4d55-966c-d80e3409ec67', '歸陽羨兼送劉八長卿', '归陽羨兼送劉八长卿', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["湖上孤帆別，江南謫宦歸。","前程愁更遠，臨水淚沾衣。","雲夢春山徧，瀟湘過客稀。","武陵招我隱，歲晚閉柴扉。"]', '["湖上孤帆別，江南謫宦归。","前程愁更远，臨水泪沾衣。","云梦春山徧，瀟湘過客稀。","武陵招我隐，歲晚閉柴扉。"]', '诗', 'shi', '', NULL, '歸陽羨兼送劉八長卿 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3379b41f-7a57-4cee-80e9-d4028f214653', '東郊迎春', '东郊迎春', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["曉見蒼龍駕，東郊春已迎。","綵雲天仗合，玄象太階平。","佳氣山川秀，和風政令行。","句陳霜騎肅，御道雨師清。","律向韶陽變，人隨草木榮。","遙觀上林樹，今日遇遷鶯。"]', '["晓见蒼龙駕，东郊春已迎。","綵云天仗合，玄象太階平。","佳氣山川秀，和风政令行。","句陳霜騎肅，御道雨師清。","律向韶陽变，人隨草木榮。","遙观上林樹，今日遇遷鶯。"]', '诗', 'shi', '', NULL, '東郊迎春 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687eb62a-e2af-449a-b1d5-4a8a7c0c6f09', '招隱寺送閻判官還江州', '招隐寺送閻判官還江州', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["離別那逢秋氣悲，東林更作上方期。","共知客路浮雲外，暫愛僧房墜葉時。","長江九派人歸少，寒嶺千重雁度遲。","借問潯陽在何處，每看潮落一相思。"]', '["離別那逢秋氣悲，东林更作上方期。","共知客路浮云外，暫愛僧房墜葉时。","长江九派人归少，寒嶺千重雁度遲。","借问潯陽在何处，每看潮落一相思。"]', '诗', 'shi', '', NULL, '招隱寺送閻判官還江州 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4459d728-2f6a-4900-aabd-8084573056d6', '送李山人還', '送李山人還', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["從來無檢束，只欲老煙霞。","雞犬聲相應，深山有幾家。"]', '["從来無檢束，只欲老煙霞。","雞犬声相應，深山有幾家。"]', '诗', 'shi', '', NULL, '送李山人還 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d44a25-b271-4527-b767-e338e7b02217', '韋中丞西廳海榴', '韋中丞西廳海榴', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["海花爭讓候榴花，犯雪先開內史家。","末客朝朝鈴閣下，從公步履玩年華。"]', '["海花爭讓候榴花，犯雪先开內史家。","末客朝朝鈴閣下，從公步履玩年华。"]', '诗', 'shi', '', NULL, '韋中丞西廳海榴 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b6cd9a-5f4e-4289-9ee6-64807a456616', '洪澤館壁見故禮部尚書題詩', '洪澤館壁见故禮部尚书題诗', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["底事洪澤壁，空留黃絹詞。","年年淮水上，行客不勝悲。"]', '["底事洪澤壁，空留黄絹词。","年年淮水上，行客不勝悲。"]', '诗', 'shi', '', NULL, '洪澤館壁見故禮部尚書題詩 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf2b41c-7c93-4b79-84f9-230503bae9d8', '望南山雪懷山寺普上人', '望南山雪懷山寺普上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["夜夜夢蓮宮，無由見遠公。","朝來出門望，知在雪山中。"]', '["夜夜梦蓮宮，無由见远公。","朝来出门望，知在雪山中。"]', '诗', 'shi', '', NULL, '望南山雪懷山寺普上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed91026-4513-4b2e-b04a-5536981cd00c', '送夔州班使君', '送夔州班使君', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["晚日照樓邊，三軍拜峽前。","白雲隨浪散，青壁與山連。","萬嶺岷峨雪，千家橘柚川。","還如赴河內，天上去經年。"]', '["晚日照楼邊，三軍拜峽前。","白云隨浪散，青壁與山連。","万嶺岷峨雪，千家橘柚川。","還如赴河內，天上去經年。"]', '诗', 'shi', '', NULL, '送夔州班使君 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e0a4e0-4593-4778-992c-f98f0bbc1a24', '尋戴處士', '尋戴处士', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["車馬長安道，誰知大隱心。","蠻僧留古鏡，蜀客寄新琴。","曬藥竹齋暖，擣茶松院深。","思君一相訪，殘雪似山陰。"]', '["车马长安道，誰知大隐心。","蠻僧留古镜，蜀客寄新琴。","曬藥竹斋暖，擣茶松院深。","思君一相訪，殘雪似山陰。"]', '诗', 'shi', '', NULL, '尋戴處士 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2067bcb7-fb10-4b6d-865f-aea6e59e57a1', '早發中嚴寺別契上人', '早發中嚴寺別契上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["蒼蒼松桂陰，殘月半西岑。","素壁寒燈暗，紅爐夜火深。","廚開山鼠散，鐘盡嶺猿吟。","行役方如此，逢師懶話心。"]', '["蒼蒼松桂陰，殘月半西岑。","素壁寒灯暗，紅爐夜火深。","廚开山鼠散，鐘尽嶺猿吟。","行役方如此，逢師懶話心。"]', '诗', 'shi', '', NULL, '早發中嚴寺別契上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44189a1f-e697-4697-9cd9-c570a949e5c8', '華清宮', '华清宮', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["驪岫接新豐，岧嶢駕翠空。","鑿山開祕殿，隱霧閉仙宮。","絳闕猶棲鳳，雕梁尚帶虹。","溫泉曾浴日，華館舊迎風。","肅穆瞻雲輦，沈深閉綺櫳。","東郊倚望處，瑞氣靄濛濛。"]', '["驪岫接新豐，岧嶢駕翠空。","鑿山开祕殿，隐霧閉仙宮。","絳闕猶棲鳳，雕梁尚带虹。","溫泉曾浴日，华館旧迎风。","肅穆瞻云輦，沈深閉綺櫳。","东郊倚望处，瑞氣靄濛濛。"]', '诗', 'shi', '', NULL, '華清宮 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d974ae6-2223-4fa3-bb66-15a079adec68', '送孔巢父赴河南軍', '送孔巢父赴河南軍', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江城相送阻煙波，況復新秋一雁過。","聞道全師征北虜，更言諸將會南河。","邊心杳杳鄉人絕，塞草青青戰馬多。","共許陳琳工奏記，知君名宦未蹉跎。"]', '["江城相送阻煙波，況复新秋一雁過。","闻道全師征北虜，更言諸將會南河。","邊心杳杳乡人絕，塞草青青戰马多。","共許陳琳工奏記，知君名宦未蹉跎。"]', '诗', 'shi', '', NULL, '送孔巢父赴河南軍 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27d0c16-26f5-4c0c-9914-4fd9dbce5021', '李二侍御丹陽東去新亭', '李二侍御丹陽东去新亭', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["姑蘇東望海陵間，幾度裁書信未還。","長在府中持白簡，豈知天畔有青山。","人歸極浦寒流廣，雁下平蕪秋野閑。","舊日新亭更攜手，他鄉風景亦相關。"]', '["姑蘇东望海陵间，幾度裁书信未還。","长在府中持白簡，豈知天畔有青山。","人归極浦寒流廣，雁下平蕪秋野闲。","旧日新亭更携手，他乡风景亦相关。"]', '诗', 'shi', '', NULL, '李二侍御丹陽東去新亭 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c400192f-cbb4-41e4-8710-4713fa25784e', '夜發沅江寄李潁川劉侍郎', '夜發沅江寄李潁川劉侍郎', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["半夜回舟入楚鄉，月明山水共蒼蒼。","孤猨更發秋風裏，不是愁人亦斷腸。"]', '["半夜回舟入楚乡，月明山水共蒼蒼。","孤猨更發秋风裏，不是愁人亦斷腸。"]', '诗', 'shi', '', NULL, '夜發沅江寄李潁川劉侍郎 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2961da31-de2e-4d7a-8b6d-1f69cbd35b1a', '浪淘沙二首 一', '浪淘沙二首 一', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["蠻歌荳蔻北人愁，松雨蒲風野艇秋。","浪起鵁鶄眠不得，寒沙細細入江流。"]', '["蠻歌荳蔻北人愁，松雨蒲风野艇秋。","浪起鵁鶄眠不得，寒沙細細入江流。"]', '诗', 'shi', '', NULL, '浪淘沙二首 一 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcba4734-18a5-4d8d-8d12-9b5f4fb49be2', '浪淘沙二首 二', '浪淘沙二首 二', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["瀨頭細草接疎林，惡浪罾船半欲沈。","宿鷺眠洲非舊浦，去年沙觜是江心。"]', '["瀨头細草接疎林，惡浪罾船半欲沈。","宿鷺眠洲非旧浦，去年沙觜是江心。"]', '诗', 'shi', '', NULL, '浪淘沙二首 二 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35f583a-c20c-453c-a886-e13f98b2e4b4', '春思', '春思', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["鶯啼燕語報新年，馬邑龍堆路幾千。","家住秦城鄰漢苑，心隨明月到胡天。","機中錦字論長恨，樓上花枝笑獨眠。","爲問元戎竇車騎，何時反斾勒燕然。"]', '["鶯啼燕語報新年，马邑龙堆路幾千。","家住秦城鄰漢苑，心隨明月到胡天。","機中錦字論长恨，楼上花枝笑独眠。","爲问元戎竇车騎，何时反斾勒燕然。"]', '诗', 'shi', '', NULL, '春思 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7722e7f-beea-4b7a-8616-4e1696ae3df5', '逢莊納因贈', '逢莊納因贈', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["世故還相見，天涯共向東。","春歸江海上，人老別離中。","郡吏名何晚，沙鷗道自同。","甘泉須早獻，且莫歎飄蓬。"]', '["世故還相见，天涯共向东。","春归江海上，人老別離中。","郡吏名何晚，沙鷗道自同。","甘泉須早獻，且莫歎飄蓬。"]', '诗', 'shi', '', NULL, '逢莊納因贈 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5780e8f-b533-48f1-ad90-d91993d5b0df', '送韋山人歸鍾山所居', '送韋山人归鍾山所居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["逸人歸路遠，弟子出山迎。","服藥顏雖駐，耽書癖已成。","柴扉度歲月，藜杖見公聊。","更作儒林傳，還應有姓名。"]', '["逸人归路远，弟子出山迎。","服藥顏雖駐，耽书癖已成。","柴扉度歲月，藜杖见公聊。","更作儒林傳，還應有姓名。"]', '诗', 'shi', '', NULL, '送韋山人歸鍾山所居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6fe162-a656-4325-87bd-6ca772dbf177', '送普門上人', '送普门上人', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["花宮難久別，道者憶千燈。","殘雪入林路，深山歸寺僧。","日光依嫩草，泉響滴春冰。","何用求方便，看心是一乘。"]', '["花宮难久別，道者憶千灯。","殘雪入林路，深山归寺僧。","日光依嫩草，泉响滴春冰。","何用求方便，看心是一乘。"]', '诗', 'shi', '', NULL, '送普門上人 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef30530e-dc97-47b6-9ec2-1ca6a085ad81', '怨回紇歌二首 一', '怨回紇歌二首 一', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["白首南朝女，愁聽異域歌。","收兵頡利國，飲馬胡蘆河。","毳布腥羶久，穹廬歲月多。","雕巢城上宿，吹笛淚滂沱。"]', '["白首南朝女，愁听異域歌。","收兵頡利国，饮马胡蘆河。","毳布腥羶久，穹廬歲月多。","雕巢城上宿，吹笛泪滂沱。"]', '诗', 'shi', '', NULL, '怨回紇歌二首 一 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79339788-9ad4-4138-babf-0a439300eeb3', '怨回紇歌二首 二', '怨回紇歌二首 二', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["祖席駐征櫂，開帆信候潮。","隔煙桃葉泣，吹管杏花飄。","船去鷗飛閣，人歸塵上橋。","別離惆悵淚，江路濕紅蕉。"]', '["祖席駐征櫂，开帆信候潮。","隔煙桃葉泣，吹管杏花飄。","船去鷗飞閣，人归塵上橋。","別離惆悵泪，江路濕紅蕉。"]', '诗', 'shi', '', NULL, '怨回紇歌二首 二 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e6245a-8954-49e2-aebb-c25f7f3368ce', '句', '句', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["微官同侍蒼龍闕，直諫偏推白馬生。"]', '["微官同侍蒼龙闕，直諫偏推白马生。"]', '诗', 'shi', '', NULL, '句 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6e408e-d1fb-49a2-bcae-d31069d58ae9', '代宛轉歌二首 一', '代宛轉歌二首 一', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["星參差，明月二八燈五枝。","黃鶴瑤琴將別去，芙蓉羽帳惜空垂。","歌宛轉，宛轉恨無窮。","願爲潮與浪，俱起碧流中。"]', '["星參差，明月二八灯五枝。","黄鹤瑤琴將別去，芙蓉羽帳惜空垂。","歌宛轉，宛轉恨無窮。","願爲潮與浪，俱起碧流中。"]', '诗', 'shi', '', NULL, '代宛轉歌二首 一 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2370a95-4199-4955-a3a6-924cf42519d4', '代宛轉歌二首 二', '代宛轉歌二首 二', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["曉將近，黃姑織女銀河盡。","九華錦衾無復情，千金寶鏡誰能引。","歌宛轉，宛轉傷別離。","願作楊與柳，同向玉窗垂。"]', '["晓將近，黄姑织女銀河尽。","九华錦衾無复情，千金寶镜誰能引。","歌宛轉，宛轉傷別離。","願作楊與柳，同向玉窗垂。"]', '诗', 'shi', '', NULL, '代宛轉歌二首 二 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8372fb3-059f-4356-b372-01fe81ca5941', '烏栖曲二首 一', '烏栖曲二首 一', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["蛾眉曼臉傾城國，鳴環動佩新相識。","銀漢斜臨白玉堂，芙蓉行障掩燈光。"]', '["蛾眉曼臉傾城国，鳴环动佩新相識。","銀漢斜臨白玉堂，芙蓉行障掩灯光。"]', '诗', 'shi', '', NULL, '烏栖曲二首 一 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69904fe-40ee-44b5-b848-63c1c74307c4', '烏栖曲二首 二', '烏栖曲二首 二', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["畫舸雙艚錦爲纜，芙蓉花發蓮葉暗。","門前月色映橫塘，感郎中夜度瀟湘。"]', '["畫舸雙艚錦爲纜，芙蓉花發蓮葉暗。","门前月色映橫塘，感郎中夜度瀟湘。"]', '诗', 'shi', '', NULL, '烏栖曲二首 二 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6de100-0c6d-4f48-a2ed-f738e4098069', '巫山高', '巫山高', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["楚國巫山秀，清猨日夜啼。","萬重春樹合，十二碧峰齊。","峽出朝雲下，江來暮雨西。","陽臺歸路直，不畏向家迷。"]', '["楚国巫山秀，清猨日夜啼。","万重春樹合，十二碧峰齊。","峽出朝云下，江来暮雨西。","陽台归路直，不畏向家迷。"]', '诗', 'shi', '', NULL, '巫山高 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f32e8e-e866-48c8-a870-a759265945ac', '巫山神女', '巫山神女', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["神女藏難識，巫山秀莫羣。","今宵爲大雨，昨日作孤雲。","散漫愁巴峽，徘徊戀楚君。","先王爲立廟，春樹幾氛氳。"]', '["神女藏难識，巫山秀莫羣。","今宵爲大雨，昨日作孤云。","散漫愁巴峽，徘徊戀楚君。","先王爲立廟，春樹幾氛氳。"]', '诗', 'shi', '', NULL, '巫山神女 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b3819c-142f-41f0-ab66-dda052360a3b', '梅花落', '梅花落', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["新歲芳梅樹，繁花四面同。","春風吹漸落，一夜幾枝空。","少婦今如此，長城恨不窮。","莫將遼海雪，來比後庭中。"]', '["新歲芳梅樹，繁花四面同。","春风吹漸落，一夜幾枝空。","少婦今如此，长城恨不窮。","莫將遼海雪，来比後庭中。"]', '诗', 'shi', '', NULL, '梅花落 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144809d9-f96f-4005-8390-7181bf9e4542', '銅雀妓', '銅雀妓', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["遺令奉君王，嚬蛾強一妝。","歲移陵樹色，恩在舞衣香。","玉座生秋氣，銅臺下夕陽。","淚痕霑井榦，舞袖爲誰長。"]', '["遺令奉君王，嚬蛾強一妝。","歲移陵樹色，恩在舞衣香。","玉座生秋氣，銅台下夕陽。","泪痕霑井榦，舞袖爲誰长。"]', '诗', 'shi', '', NULL, '銅雀妓 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a0356b-afaf-434f-aa72-9d20a9c14eeb', '秋夜思', '秋夜思', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["旅夢何時盡，征途望每賒。","晚秋淮上水，新月楚人家。","猨嘯空山近，鴻飛極浦斜。","明朝南岸去，言折桂枝花。"]', '["旅梦何时尽，征途望每賒。","晚秋淮上水，新月楚人家。","猨嘯空山近，鴻飞極浦斜。","明朝南岸去，言折桂枝花。"]', '诗', 'shi', '', NULL, '秋夜思 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e3a77a-16bf-4493-ba3a-579310ca4115', '秋夜泛舟', '秋夜泛舟', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["林塘夜發舟，蟲響荻颼颼。","萬影皆因月，千聲各爲秋。","歲華空復晚，鄉思不堪愁。","西北浮雲外，伊川何處流。"]', '["林塘夜發舟，蟲响荻颼颼。","万影皆因月，千声各爲秋。","歲华空复晚，乡思不堪愁。","西北浮云外，伊川何处流。"]', '诗', 'shi', '', NULL, '秋夜泛舟 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a175a4-d16a-43d3-9230-9541b5817fdb', '折楊枝', '折楊枝', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["官渡初楊柳，風來亦動搖。","武昌行路好，應爲最長條。","葉映黃鸝夕，花繁白雪朝。","年年攀折意，流恨入纖腰。"]', '["官渡初楊柳，风来亦动搖。","武昌行路好，應爲最长條。","葉映黄鸝夕，花繁白雪朝。","年年攀折意，流恨入纖腰。"]', '诗', 'shi', '', NULL, '折楊枝 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e810fc2a-2af1-40f2-bf48-aee1bb90c305', '班婕妤', '班婕妤', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["夕殿別君王，宮深月似霜。","人幽在長信，螢出向昭陽。","露浥紅蘭濕，秋凋碧樹傷。","惟當合歡扇，從此篋中藏。"]', '["夕殿別君王，宮深月似霜。","人幽在长信，螢出向昭陽。","露浥紅蘭濕，秋凋碧樹傷。","惟當合歡扇，從此篋中藏。"]', '诗', 'shi', '', NULL, '班婕妤 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d980038f-486c-4784-970e-59ed6a95dafd', '新春', '新春', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["南陌春風早，東隣曙色斜。","一花開楚國，雙燕入盧家。","眠罷梳雪髻，妝成上錦車。","誰知如昔日，更浣越溪紗。"]', '["南陌春风早，东隣曙色斜。","一花开楚国，雙燕入盧家。","眠罷梳雪髻，妝成上錦车。","誰知如昔日，更浣越溪紗。"]', '诗', 'shi', '', NULL, '新春 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8956d2-37e9-487b-822f-fdaac68570d5', '寄嚴八判官', '寄嚴八判官', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["洛陽新月動秋砧，瀚海沙場天半陰。","出塞能全仲叔策，安親更切老萊心。","漢家宮裏風雲曉，羌笛聲中雨雪深。","懷袖未傳三歲字，相思空作隴頭吟。"]', '["洛陽新月动秋砧，瀚海沙場天半陰。","出塞能全仲叔策，安親更切老萊心。","漢家宮裏风云晓，羌笛声中雨雪深。","懷袖未傳三歲字，相思空作隴头吟。"]', '诗', 'shi', '', NULL, '寄嚴八判官 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b108a510-8ab7-455a-bf9c-f7883f9960b7', '秋夜寄皇甫冉鄭豐', '秋夜寄皇甫冉鄭豐', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["洛陽清夜白雲歸，城裏長河列宿稀。","秋後見飛千里鴈，月中聞搗萬家衣。","長憐西雍青門道，久別東吳黃鵠磯。","借問客書何所寄，用心不啻兩鄉違。"]', '["洛陽清夜白云归，城裏长河列宿稀。","秋後见飞千里鴈，月中闻捣万家衣。","长怜西雍青门道，久別东吳黄鵠磯。","借问客书何所寄，用心不啻兩乡違。"]', '诗', 'shi', '', NULL, '秋夜寄皇甫冉鄭豐 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6d87d07-0173-41b7-bd5a-52214bc1864e', '寄隴右嚴判官', '寄隴右嚴判官', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["副相西征重，蒼生屬望晨。","還同周薄伐，不取漢和親。","虜陣摧枯易，王師決勝頻。","高旗臨鼓角，太白靜風塵。","赤狄爭歸化，青羌已請臣。","遙傳閫外美，盛選幕中賓。","玉劒光初發，冰壺色自真。","忠貞期報主，章服豈榮身。","邊草含風綠，征鴻過月新。","胡笳長出塞，隴水半歸秦。","絕漠多來往，連年厭苦辛。","路經西漢雪，家擲後園春。","誰念煙雲裏，深居汝潁濱。","一叢黃菊地，九日白衣人。","松葉疎開嶺，桃花密映津。","縑書若有寄，爲訪許由鄰。"]', '["副相西征重，蒼生屬望晨。","還同周薄伐，不取漢和親。","虜陣摧枯易，王師決勝頻。","高旗臨鼓角，太白静风塵。","赤狄爭归化，青羌已請臣。","遙傳閫外美，盛選幕中賓。","玉劒光初發，冰壺色自真。","忠貞期報主，章服豈榮身。","邊草含风綠，征鴻過月新。","胡笳长出塞，隴水半归秦。","絕漠多来往，連年厭苦辛。","路經西漢雪，家擲後园春。","誰念煙云裏，深居汝潁濱。","一叢黄菊地，九日白衣人。","松葉疎开嶺，桃花密映津。","縑书若有寄，爲訪許由鄰。"]', '诗', 'shi', '', NULL, '寄隴右嚴判官 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb3241e-272e-4183-801d-b37e6beb048f', '擬娼樓節怨', '擬娼楼節怨', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["上苑離離鶯度，昆明冪冪蒲生。","時光春華可惜，何須對鏡含情。"]', '["上苑離離鶯度，昆明冪冪蒲生。","时光春华可惜，何須对镜含情。"]', '诗', 'shi', '', NULL, '擬娼樓節怨 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4edbf7-050f-4176-87cc-a3b461ea1acf', '採蓮曲', '採蓮曲', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["落日晴江裏，荆歌豔楚腰。","採蓮從小慣，十五即乘潮。"]', '["落日晴江裏，荆歌豔楚腰。","採蓮從小慣，十五即乘潮。"]', '诗', 'shi', '', NULL, '採蓮曲 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31dac9d0-ff07-4ce9-b98c-01be1efdf739', '長信宮', '长信宮', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["夢裏君王近，宮中河漢高。","秋風能再熱，團扇不辭勞。"]', '["梦裏君王近，宮中河漢高。","秋风能再熱，團扇不辞勞。"]', '诗', 'shi', '', NULL, '長信宮 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdfb8b8e-be3f-4928-b6ad-d418b60a3013', '京兆眉', '京兆眉', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["新作蛾眉樣，誰將月裏同。","有來凡幾日，相效滿城中。"]', '["新作蛾眉樣，誰將月裏同。","有来凡幾日，相效满城中。"]', '诗', 'shi', '', NULL, '京兆眉 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56863b6d-0025-48ab-a1a3-76dafc6bf99b', '春雪', '春雪', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["飛雪帶春風，裴回亂繞空。","君看似花處，偏在洛陽東。"]', '["飞雪带春风，裴回亂繞空。","君看似花处，偏在洛陽东。"]', '诗', 'shi', '', NULL, '春雪 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f6b39a-8235-4337-9e5e-294742bc3f0e', '望夫石', '望夫石', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["佳人成古石，蘚駁覆花黃。","猶有春山杏，枝枝似薄妝。"]', '["佳人成古石，蘚駁覆花黄。","猶有春山杏，枝枝似薄妝。"]', '诗', 'shi', '', NULL, '望夫石 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef544177-4d1c-4532-9ceb-aeeb4986c388', '送別', '送別', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["華亭霽色滿今朝，雲裏檣竿去轉遙。","莫怪山前深復淺，清淮一日兩迴潮。"]', '["华亭霽色满今朝，云裏檣竿去轉遙。","莫怪山前深复淺，清淮一日兩迴潮。"]', '诗', 'shi', '', NULL, '送別 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e7ec6e-0d6c-4f95-8181-4671c42e1faf', '夜月', '夜月', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["更深月色半人家，北斗闌干南斗斜。","今夜偏知春氣暖，蟲聲新透綠窗紗。"]', '["更深月色半人家，北斗闌干南斗斜。","今夜偏知春氣暖，蟲声新透綠窗紗。"]', '诗', 'shi', '', NULL, '夜月 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1bc01d-c281-40fd-9e0d-4c484539e4ae', '春怨', '春怨', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["紗窗日落漸黃昏，金屋無人見淚痕。","寂寞空庭春欲晚，梨花滿地不開門。"]', '["紗窗日落漸黄昏，金屋無人见泪痕。","寂寞空庭春欲晚，梨花满地不开门。"]', '诗', 'shi', '', NULL, '春怨 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09666f87-a152-4a41-a35b-8971b234cfa7', '代春怨', '代春怨', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["朝日殘鶯伴妾啼，開簾只見草萋萋。","庭前時有東風入，楊柳千條盡向西。"]', '["朝日殘鶯伴妾啼，开簾只见草萋萋。","庭前时有东风入，楊柳千條尽向西。"]', '诗', 'shi', '', NULL, '代春怨 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80832caa-35f3-4c50-86f5-66218ec57051', '宣州東峰亭各賦一物得古壁苔', '宣州东峰亭各賦一物得古壁苔', 'd130833d-82fc-47ab-bd7f-9e401f4faed7', '唐', '["苒苒溫寒泉，綿綿古危壁。","光含孤翠動，色與暮雲寂。","深淺松月間，幽人自登歷。"]', '["苒苒溫寒泉，綿綿古危壁。","光含孤翠动，色與暮云寂。","深淺松月间，幽人自登歷。"]', '诗', 'shi', '', NULL, '宣州東峰亭各賦一物得古壁苔 劉太真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e17f84c-a6f4-4052-bd4d-452be8b4dbc2', '顧十二況左遷過韋蘇州房杭州韋睦州三使君皆有郡中燕集詩辭章高麗鄙夫之所仰慕顧生既至留連笑語因亦成篇以繼三君子之風焉', '顧十二況左遷過韋蘇州房杭州韋睦州三使君皆有郡中燕集诗辞章高丽鄙夫之所仰慕顧生既至留連笑語因亦成篇以繼三君子之风焉', 'd130833d-82fc-47ab-bd7f-9e401f4faed7', '唐', '["寵至乃不驚，罪及非無由。","奔迸歷畏途，緬貌赴偏陬。","牧此彫弊甿，屬當賦斂秋。","鳳興諒無補，旬暇焉敢休。","前日懷友生，獨登城上樓。","迢迢西北望，遠思不可收。","今曰車騎來，曠然銷人憂。","晨迎東齋飯，晚度南溪遊。","以我碧流水，泊君青翰舟。","莫將遷客程，不爲勝境留。","飛札謝三守，斯篇希見酬。"]', '["寵至乃不驚，罪及非無由。","奔迸歷畏途，緬貌赴偏陬。","牧此彫弊甿，屬當賦斂秋。","鳳兴諒無補，旬暇焉敢休。","前日懷友生，独登城上楼。","迢迢西北望，远思不可收。","今曰车騎来，曠然銷人憂。","晨迎东斋飯，晚度南溪游。","以我碧流水，泊君青翰舟。","莫將遷客程，不爲勝境留。","飞札謝三守，斯篇希见酬。"]', '诗', 'shi', '', NULL, '顧十二況左遷過韋蘇州房杭州韋睦州三使君皆有郡中燕集詩辭章高麗鄙夫之所仰慕顧生既至留連笑語因亦成篇以繼三君子之風焉 劉太真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b66503e3-45bd-442b-9c56-85787aad2f1b', '貢院寄前主司蕭尚書聽', '貢院寄前主司蕭尚书听', 'd130833d-82fc-47ab-bd7f-9e401f4faed7', '唐', '["獨坐貢闈裏，愁心芳草生。","山公昨夜事，應見此時情。"]', '["独坐貢闈裏，愁心芳草生。","山公昨夜事，應见此时情。"]', '诗', 'shi', '', NULL, '貢院寄前主司蕭尚書聽 劉太真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c18f2c-6e0d-49c0-9095-cc1674caaac5', '東峰亭同劉太真各賦一物得垂澗藤', '东峰亭同劉太真各賦一物得垂澗藤', '6dc488be-f276-4bee-9af9-9db7defe787b', '唐', '["寒澗留不息，古藤終日垂。","迎風仍未定，拂水更相宜。","新花與舊葉，惟有幽人知。"]', '["寒澗留不息，古藤終日垂。","迎风仍未定，拂水更相宜。","新花與旧葉，惟有幽人知。"]', '诗', 'shi', '', NULL, '東峰亭同劉太真各賦一物得垂澗藤 袁傪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd72add0-bcb6-47de-a424-65bc31397b69', '喜陸侍御破石埭草寇東峰亭賦詩', '喜陸侍御破石埭草寇东峰亭賦诗', '6dc488be-f276-4bee-9af9-9db7defe787b', '唐', '["古詩東峰上，登臨興有餘。","同觀白簡使，新報赤囊書。","幾處閑烽堠，千方慶里閭。","欣欣夏木長，寂寂晚煙徐。","戰罷言歸馬，遠師賦出車。","因知越范蠡，湖海意[何如]。"]', '["古诗东峰上，登臨兴有餘。","同观白簡使，新報赤囊书。","幾处闲烽堠，千方慶里閭。","欣欣夏木长，寂寂晚煙徐。","戰罷言归马，远師賦出车。","因知越范蠡，湖海意[何如]。"]', '诗', 'shi', '', NULL, '喜陸侍御破石埭草寇東峰亭賦詩 袁傪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf79533-c907-461a-94b7-24bb9251e388', '東峰亭各賦一物得嶺上雲', '东峰亭各賦一物得嶺上云', '5731b3dc-4b24-4a6a-863d-387689eb6f39', '唐', '["佇立增遠意，中峰見孤雲。","溶溶傍危石，片片宜夕曛。","漸向羣木盡，殘飛更氤氳。"]', '["佇立增远意，中峰见孤云。","溶溶傍危石，片片宜夕曛。","漸向羣木尽，殘飞更氤氳。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得嶺上雲 崔何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf92e7b-c033-4304-88e6-29f1ee995a6d', '喜陸侍御破石埭草寇東峰亭賦詩', '喜陸侍御破石埭草寇东峰亭賦诗', '5731b3dc-4b24-4a6a-863d-387689eb6f39', '唐', '["絕景西溪寺，連延近郭山。","高深清扃外，行止翠微間。","江澈煙塵靜，川源草樹閑。","中丞健步到，柱史捷書還。","一戰清戎越，三吳變險艱。","功名麟閣上，得詠入秦關。"]', '["絕景西溪寺，連延近郭山。","高深清扃外，行止翠微间。","江澈煙塵静，川源草樹闲。","中丞健步到，柱史捷书還。","一戰清戎越，三吳变險艱。","功名麟閣上，得詠入秦关。"]', '诗', 'shi', '', NULL, '喜陸侍御破石埭草寇東峰亭賦詩 崔何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4047ab19-f7c0-494d-bb6c-6b75735c8380', '東峰亭各賦一物得幽徑石', '东峰亭各賦一物得幽徑石', 'bca790ac-9d8a-4739-862e-f40701e3ff0f', '唐', '["片石東溪上，陰崖剩阻修。","雨餘青石靄，歲晚綠苔幽。","從來不可轉，今日爲人留。"]', '["片石东溪上，陰崖剩阻修。","雨餘青石靄，歲晚綠苔幽。","從来不可轉，今日爲人留。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得幽徑石 王緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649179e5-991e-4826-a161-35332add157e', '喜陸侍御破石埭草寇東峰亭賦詩', '喜陸侍御破石埭草寇东峰亭賦诗', 'bca790ac-9d8a-4739-862e-f40701e3ff0f', '唐', '["蜂蠆聚吳州，推賢奉聖憂。","忠誠資上策，仁勇佐前籌。","草木成鵝鸛，戈鋋復斗牛。","戎車一戰後，殘壘五兵收。","野靜山戎險，江平水面流。","更憐羈旅客，從此罷葵丘。"]', '["蜂蠆聚吳州，推賢奉聖憂。","忠誠資上策，仁勇佐前籌。","草木成鵝鸛，戈鋋复斗牛。","戎车一戰後，殘壘五兵收。","野静山戎險，江平水面流。","更怜羈旅客，從此罷葵丘。"]', '诗', 'shi', '', NULL, '喜陸侍御破石埭草寇東峰亭賦詩 王緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1ed3d9-0a74-4d3b-98a1-1333b945d17d', '東峰亭各賦一物得臨軒桂', '东峰亭各賦一物得臨軒桂', 'ba823220-354c-4dbd-bb07-c2fd3e928a60', '唐', '["青青芳桂樹，幽陰在庭軒。","向日陰還合，從風葉乍翻。","共看霜雪後，終不變涼暄。"]', '["青青芳桂樹，幽陰在庭軒。","向日陰還合，從风葉乍翻。","共看霜雪後，終不变涼暄。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得臨軒桂 郭澹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b490c7d7-9127-4c57-8e32-84d3296eaf08', '喜陸侍御破石埭草寇東峰亭賦詩', '喜陸侍御破石埭草寇东峰亭賦诗', 'ba823220-354c-4dbd-bb07-c2fd3e928a60', '唐', '["介胄鷹揚出，山林蟻聚空。","忽聞飛簡報，曾是坐籌功。","逈夜昏氛滅，危亭眺望雄。","茂勳推世上，餘興寄杯中。","喜色煙霞改，歡忻里巷同。","幸茲尊俎末，飲至又從公。"]', '["介胄鷹揚出，山林蟻聚空。","忽闻飞簡報，曾是坐籌功。","逈夜昏氛滅，危亭眺望雄。","茂勳推世上，餘兴寄杯中。","喜色煙霞改，歡忻里巷同。","幸茲尊俎末，饮至又從公。"]', '诗', 'shi', '', NULL, '喜陸侍御破石埭草寇東峰亭賦詩 郭澹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8830f54f-bf1c-4db2-96a5-4521e4899c00', '東峰亭各賦一物得林中翠', '东峰亭各賦一物得林中翠', 'c70b3b09-66a7-468f-8b05-0fa15259cb7d', '唐', '["杳靄無定狀，霏微常滿林。","清風光不散，過雨色偏深。","幽意賞難盡，終朝再招尋。"]', '["杳靄無定狀，霏微常满林。","清风光不散，過雨色偏深。","幽意賞难尽，終朝再招尋。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得林中翠 高傪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2797a36b-cdb9-4ace-a0dc-672bf500419b', '東峰亭各賦一物得棲煙鳥', '东峰亭各賦一物得棲煙鸟', '498d4211-e7d4-4a84-a002-1bb37476c550', '唐', '["從來養毛羽，昔日曾飛遷。","變轉對朝陽，差池棲夕煙。","遇此枝葉覆，夙舉冀沖天。"]', '["從来養毛羽，昔日曾飞遷。","变轉对朝陽，差池棲夕煙。","遇此枝葉覆，夙舉冀沖天。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得棲煙鳥 李岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b1a34a-825b-4b0c-912a-d978c04cdc48', '東峰亭各賦一物得寒溪草', '东峰亭各賦一物得寒溪草', '445d6698-6469-4d1a-92d9-6b33c14f4b55', '唐', '["冪䍥溪邊草，遊人不厭看。","餘芳幽處老，深色望中寒。","幸得陪情興，青青賞未闌。"]', '["冪䍥溪邊草，游人不厭看。","餘芳幽处老，深色望中寒。","幸得陪情兴，青青賞未闌。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得寒溪草 蘇寓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('913c4360-669c-4e85-ba3d-49dec96abce4', '東峰亭各賦一物得陰崖竹', '东峰亭各賦一物得陰崖竹', '61baa968-c11c-4943-aed0-7c67d5118e7b', '唐', '["終歲寒苔色，寂寥幽思深。","朝歌猶夕嵐，日永流清陰。","龍鍾負煙雪，自有凌雲心。"]', '["終歲寒苔色，寂寥幽思深。","朝歌猶夕嵐，日永流清陰。","龙鍾負煙雪，自有凌云心。"]', '诗', 'shi', '', NULL, '東峰亭各賦一物得陰崖竹 袁邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6d275e-0794-441d-bb22-b29972e7e7cd', '唐德明興聖廟樂章 迎神', '唐德明兴聖廟乐章 迎神', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["元尊九德，佐堯光宅。","烈祖太宗，方周作伯。","響懷霜露，樂變金石。","白雲青風，髣髴來格。"]', '["元尊九德，佐堯光宅。","烈祖太宗，方周作伯。","响懷霜露，乐变金石。","白云青风，髣髴来格。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 迎神 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d74a95e-bab7-4162-8bd8-7de90b75ddcf', '唐德明興聖廟樂章 登歌奠幣', '唐德明兴聖廟乐章 登歌奠幣', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["四時有典，百事來祭。","尊祖奉宗，嚴禋大帝。","禮先蒼璧，奠備黝制。","於萬斯年，熙成帝系。"]', '["四时有典，百事来祭。","尊祖奉宗，嚴禋大帝。","禮先蒼璧，奠備黝制。","於万斯年，熙成帝系。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 登歌奠幣 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee77bdf-cd73-4f30-847b-b11394b3e630', '唐德明興聖廟樂章 迎俎', '唐德明兴聖廟乐章 迎俎', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["盛牲實俎，涓選休成。","鼎煁陽燧，玉盥陰精。","有飶嘉豆，既和大羹。","侑以清樂，細齊人情。"]', '["盛牲實俎，涓選休成。","鼎煁陽燧，玉盥陰精。","有飶嘉豆，既和大羹。","侑以清乐，細齊人情。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 迎俎 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7139c59e-7b56-40bb-98c4-c67f0da56bca', '唐德明興聖廟樂章 德明酌獻', '唐德明兴聖廟乐章 德明酌獻', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["清廟弈弈，和樂雍雍。","器尊犧象，禮屬宗公。","白水方[祼]，黃流在中。","謨明之德，萬古清風。"]', '["清廟弈弈，和乐雍雍。","器尊犧象，禮屬宗公。","白水方[祼]，黄流在中。","謨明之德，万古清风。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 德明酌獻 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2f5611-3d0e-4b0c-a986-b40a523a5c66', '唐德明興聖廟樂章 興聖酌獻', '唐德明兴聖廟乐章 兴聖酌獻', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["閟宮靜謐，合樂周張。","泰尊始獻，百末重觴。","震澹存誠，庶幾迪嘗。","遙源之祚，天漢靈長。"]', '["閟宮静謐，合乐周張。","泰尊始獻，百末重觴。","震澹存誠，庶幾迪嘗。","遙源之祚，天漢靈长。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 興聖酌獻 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d59460b-b1a2-4d2b-a7c1-7d801ac8d860', '唐德明興聖廟樂章 亞獻終獻', '唐德明兴聖廟乐章 亞獻終獻', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["惟清惟肅，靡聞靡見。","舉備九成，俛終三獻。","慶彰曼壽，胙撤嘉薦。","瘞玉埋牲，禮神斯徧。"]', '["惟清惟肅，靡闻靡见。","舉備九成，俛終三獻。","慶彰曼壽，胙撤嘉薦。","瘞玉埋牲，禮神斯徧。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 亞獻終獻 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62123595-e471-4263-929f-5bf84d8890c8', '唐德明興聖廟樂章 送神', '唐德明兴聖廟乐章 送神', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["元精回復，靈貺繁滋。","風灑蘭路，雲搖桂旗。","高丘緬邈，涼部逶遲。","瞻望靡及，纏綿永思。"]', '["元精回复，靈貺繁滋。","风灑蘭路，云搖桂旗。","高丘緬邈，涼部逶遲。","瞻望靡及，纏綿永思。"]', '诗', 'shi', '', NULL, '唐德明興聖廟樂章 送神 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768101d9-fc3c-4f85-aa98-e01ea8dea5e9', '讓皇帝廟樂章 迎神', '讓皇帝廟乐章 迎神', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["皇矣天宗，德先王季。","因心則友，克讓以位。","爰命有司，式尊前志。","神其降靈，昭饗祀事。"]', '["皇矣天宗，德先王季。","因心則友，克讓以位。","爰命有司，式尊前志。","神其降靈，昭饗祀事。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 迎神 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d192476f-adfa-4a7a-a1b0-78575fe4bfe1', '讓皇帝廟樂章 奠幣', '讓皇帝廟乐章 奠幣', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["惟帝時若，去而上仙。","祀用商武，樂備宮懸。","白壁加薦，玄纁告虔。","子孫拜後，承茲吉蠲。"]', '["惟帝时若，去而上仙。","祀用商武，乐備宮懸。","白壁加薦，玄纁告虔。","子孫拜後，承茲吉蠲。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 奠幣 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('933e80d0-3b30-4480-bde3-1d8760341efb', '讓皇帝廟樂章 迎俎', '讓皇帝廟乐章 迎俎', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["祀盛體薦，禮協粢盛。","方周假廟，用魯純牲。","捧撤祗敬，擊拊和鳴。","受釐歸胙，既戒而平。"]', '["祀盛體薦，禮協粢盛。","方周假廟，用魯純牲。","捧撤祗敬，擊拊和鳴。","受釐归胙，既戒而平。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 迎俎 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6134bd98-c13f-4dde-b5c5-2c61bbb2f262', '讓皇帝廟樂章 酌獻', '讓皇帝廟乐章 酌獻', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["八音具舉，三壽既盥。","潔茲宗彝，瑟彼圭瓚。","蘭肴重錯，椒醑飄散。","降祚維城，永爲藩翰。"]', '["八音具舉，三壽既盥。","潔茲宗彝，瑟彼圭瓚。","蘭肴重錯，椒醑飄散。","降祚維城，永爲藩翰。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 酌獻 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47ec48a-49e4-4c2f-ab12-390dad8135cc', '讓皇帝廟樂章 亞獻終獻', '讓皇帝廟乐章 亞獻終獻', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["秩禮有序，和音既同。","九儀不忒，三揖將終。","孝感藩后，相維辟公。","四時之典，永永無窮。"]', '["秩禮有序，和音既同。","九儀不忒，三揖將終。","孝感藩后，相維辟公。","四时之典，永永無窮。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 亞獻終獻 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7abd91-b70d-4c99-b6a1-0062f312021e', '讓皇帝廟樂章 送神', '讓皇帝廟乐章 送神', '1ff7839b-a4cf-4660-a2e0-cd3255006055', '唐', '["奠獻已事，昏昕載分。","風搖雨散，靈衛絪緼。","龍駕帝服，已騰五雲。","泮宮復閟，寂寞無聞。"]', '["奠獻已事，昏昕載分。","风搖雨散，靈衛絪緼。","龙駕帝服，已腾五云。","泮宮复閟，寂寞無闻。"]', '诗', 'shi', '', NULL, '讓皇帝廟樂章 送神 李紓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca20506a-d7d5-4253-975d-1377364ea11a', '釋奠武成王樂章 迎神', '釋奠武成王乐章 迎神', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["卜畋不從，兆發非熊。","乃傾荒政，爰佐一戎。","盛烈載垂，命祀維崇。","日練上戊，宿嚴閟宮。","迎奏嘉至，感而遂通。"]', '["卜畋不從，兆發非熊。","乃傾荒政，爰佐一戎。","盛烈載垂，命祀維崇。","日練上戊，宿嚴閟宮。","迎奏嘉至，感而遂通。"]', '诗', 'shi', '', NULL, '釋奠武成王樂章 迎神 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75dbae3-acc5-4b29-9a2a-02ef1c78c828', '釋奠武成王樂章 奠幣登歌', '釋奠武成王乐章 奠幣登歌', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["管罄升，壇薌集。","上公進，嘉幣執。","信以通，僾如及。","恢帝功，錫后邑。","四維張，百度立。","綿億載，邈難挹。"]', '["管罄升，壇薌集。","上公進，嘉幣執。","信以通，僾如及。","恢帝功，錫后邑。","四維張，百度立。","綿億載，邈难挹。"]', '诗', 'shi', '', NULL, '釋奠武成王樂章 奠幣登歌 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c7a7239-144e-4d4e-98d0-0ca472a4b4aa', '釋奠武成王樂章 迎俎酌獻', '釋奠武成王乐章 迎俎酌獻', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["五齊絜，九牢碩。","梡橛循，罍斝滌。","進具物，揚鴻勣。","和奏發，高靈寂。","虔告終，繁祉錫。","昭秩祀，永無易。"]', '["五齊絜，九牢碩。","梡橛循，罍斝滌。","進具物，揚鴻勣。","和奏發，高靈寂。","虔告終，繁祉錫。","昭秩祀，永無易。"]', '诗', 'shi', '', NULL, '釋奠武成王樂章 迎俎酌獻 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae7016e-6614-4060-92bd-17930bed017a', '釋奠武成王樂章 亞獻終獻', '釋奠武成王乐章 亞獻終獻', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["貳觴以獻，三變其終。","顧此非馨，尚達斯衷。","茅縮可致，神歆載融。","始神翊周，拯溺除凶。","時維降祐，永絕興戎。"]', '["貳觴以獻，三变其終。","顧此非馨，尚達斯衷。","茅縮可致，神歆載融。","始神翊周，拯溺除凶。","时維降祐，永絕兴戎。"]', '诗', 'shi', '', NULL, '釋奠武成王樂章 亞獻終獻 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4973cb28-d9ab-4709-88b0-d86860495d14', '釋奠武成王樂章 送神', '釋奠武成王乐章 送神', '7848102d-1bab-4ecf-91c5-6b13f7e9c511', '唐', '["明祀方終，備樂斯闋。","黝纁就瘞，豆籩告撤。","肸蠁尚餘，光景云滅。","返歸虛極，神心則悅。"]', '["明祀方終，備乐斯闋。","黝纁就瘞，豆籩告撤。","肸蠁尚餘，光景云滅。","返归虛極，神心則悅。"]', '诗', 'shi', '', NULL, '釋奠武成王樂章 送神 于邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63950163-6a10-4e74-af8a-09886e4ef2a8', '登鸛雀樓', '登鸛雀楼', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["白日依山盡，黃河入海流。","欲窮千里目，更上一層樓。"]', '["白日依山尽，黄河入海流。","欲窮千里目，更上一層楼。"]', '诗', 'shi', '', NULL, '登鸛雀樓 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5668e19f-051f-4c3c-bd36-db966c3d7e71', '送別', '送別', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["楊柳東風樹，青青夾御河。","近來攀折苦，應爲別離多。"]', '["楊柳东风樹，青青夾御河。","近来攀折苦，應爲別離多。"]', '诗', 'shi', '', NULL, '送別 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('526d4ecc-e123-4b9d-a213-958bb947593d', '涼州詞二首” 一', '涼州词二首” 一', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["黃河遠上白雲間，一片孤城萬仞山。","羌笛何須怨楊柳，春光不度玉門關。"]', '["黄河远上白云间，一片孤城万仞山。","羌笛何須怨楊柳，春光不度玉门关。"]', '诗', 'shi', '', NULL, '涼州詞二首” 一 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7c341d2-bc57-45b0-8c7a-ef7c1740b3e8', '涼州詞二首” 二', '涼州词二首” 二', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["單于北望拂雲堆，殺馬登壇祭幾迴。","漢家天子今神武，不肯和親歸去來。"]', '["單于北望拂云堆，殺马登壇祭幾迴。","漢家天子今神武，不肯和親归去来。"]', '诗', 'shi', '', NULL, '涼州詞二首” 二 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('750d30c4-bbe3-4d0b-8d72-e8d9b92fbdfd', '宴詞', '宴词', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["長堤春水綠悠悠，畎入漳河一道流。","莫聽聲聲催去櫂，桃溪淺處不勝舟。"]', '["长堤春水綠悠悠，畎入漳河一道流。","莫听声声催去櫂，桃溪淺处不勝舟。"]', '诗', 'shi', '', NULL, '宴詞 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f24b694-4965-4999-9945-e34ef371bff3', '九日送別', '九日送別', 'af2de6ea-bee2-4c52-a3b6-185b2321d1a7', '唐', '["薊庭蕭瑟故人稀，何處登高且送歸。","今日暫同芳菊酒，明朝應作斷蓬飛。"]', '["薊庭蕭瑟故人稀，何处登高且送归。","今日暫同芳菊酒，明朝應作斷蓬飞。"]', '诗', 'shi', '', NULL, '九日送別 王之渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70237d74-d8e5-4acd-a62e-ba6c4b8caec3', '晚秋石門禮拜', '晚秋石门禮拜', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["輕策臨絕壁，招提謁金仙。","舟車無由徑，巖嶠乃屬天。","躑躅淹昃景，夷猶望新弦。","石門變暝色，谷口生人煙。","陽鴈叫平楚，秋風急寒川。","馳暉苦代謝，浮脆慙貞堅。","永欲臥丘壑，息心依梵筵。","誓將歷劫願，無以外物牽。"]', '["轻策臨絕壁，招提謁金仙。","舟车無由徑，巖嶠乃屬天。","躑躅淹昃景，夷猶望新弦。","石门变暝色，谷口生人煙。","陽鴈叫平楚，秋风急寒川。","驰暉苦代謝，浮脆慙貞堅。","永欲臥丘壑，息心依梵筵。","誓將歷劫願，無以外物牽。"]', '诗', 'shi', '', NULL, '晚秋石門禮拜 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f6ef42b-eb0a-49f8-971b-d59a58ec6239', '百丈谿新理茅茨讀書', '百丈谿新理茅茨读书', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["浪迹棄人世，遠山自幽獨。","始傍巢由蹤，吾其獲心曲。","荒庭何所有，老樹半空腹。","秋蜩鳴北林，暮鳥穿我屋。","棲遲樂遵渚，恬曠寡所欲。","開卦推盈虛，散帙攻節目。","養閑度人事，達命知止足。","不學東周儒，俟時勞伐輻。"]', '["浪迹棄人世，远山自幽独。","始傍巢由蹤，吾其獲心曲。","荒庭何所有，老樹半空腹。","秋蜩鳴北林，暮鸟穿我屋。","棲遲乐遵渚，恬曠寡所欲。","开卦推盈虛，散帙攻節目。","養闲度人事，達命知止足。","不学东周儒，俟时勞伐輻。"]', '诗', 'shi', '', NULL, '百丈谿新理茅茨讀書 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49e54a12-b52b-4f98-b5c9-3beb8d5a823a', '宿岸道人精舍', '宿岸道人精舍', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["早歲參道風，放情入寥廓。","重因息心侶，遂果巖下諾。","斂跡辭人間，杜門守寂寞。","秋風翦蘭蕙，霜氣冷淙壑。","山牖見然燈，竹房聞搗藥。","願言捨塵事，所趣非龍蠖。"]', '["早歲參道风，放情入寥廓。","重因息心侶，遂果巖下諾。","斂跡辞人间，杜门守寂寞。","秋风翦蘭蕙，霜氣冷淙壑。","山牖见然灯，竹房闻捣藥。","願言捨塵事，所趣非龙蠖。"]', '诗', 'shi', '', NULL, '宿岸道人精舍 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b66eef-77d3-4406-9935-e3efe5e95928', '夕次鹿門山作', '夕次鹿门山作', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["龐公嘉遯所，浪跡難追攀。","浮舟暝始至，抱杖聊自閑。","雙巖開鹿門，百谷集珠灣。","噴薄湍上水，舂容漂裏山。","焦原不足險，梁壑未成艱。","我行自春仲，夏鳥忽緜蠻。","蕙草色已晚，客心殊倦還。","遠遊非避地，訪道愛童顏。","安能徇機巧爭奪錐刀間。"]', '["龐公嘉遯所，浪跡难追攀。","浮舟暝始至，抱杖聊自闲。","雙巖开鹿门，百谷集珠灣。","噴薄湍上水，舂容漂裏山。","焦原不足險，梁壑未成艱。","我行自春仲，夏鸟忽緜蠻。","蕙草色已晚，客心殊倦還。","远游非避地，訪道愛童顏。","安能徇機巧爭奪錐刀间。"]', '诗', 'shi', '', NULL, '夕次鹿門山作 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc46b2c-73ad-470b-9b7f-0b215c76afef', '與永樂諸公夜泛黃河作', '與永乐諸公夜泛黄河作', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["煙深載酒入，但覺暮川虛。","映水見山火，鳴榔聞夜漁。","愛茲山水趣，忽與人世疎。","無暇然官燭，中流有望舒。"]', '["煙深載酒入，但覺暮川虛。","映水见山火，鳴榔闻夜漁。","愛茲山水趣，忽與人世疎。","無暇然官燭，中流有望舒。"]', '诗', 'shi', '', NULL, '與永樂諸公夜泛黃河作 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2101c68-6a54-4d26-ad11-b4760a7a2770', '句', '句', '2983b7e6-32b4-49b6-96bc-e11b1193a084', '唐', '["熊踞庭中樹，龍蒸棟裏雲。"]', '["熊踞庭中樹，龙蒸棟裏云。"]', '诗', 'shi', '', NULL, '句 閻防 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d801a0-491e-45d0-9a0a-0decb86a252f', '懷哉行', '懷哉行', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["明時無廢人，廣廈無棄材。","良工不我顧，有用寧自媒。","懷策望君門，歲晏空遲迴。","秦城多車馬，日夕飛塵埃。","伐鼓千門啓，鳴珂雙闕來。","我聞雷雨施，天澤罔不該。","何意斯人徒，棄之如死灰。","主好臣必効，時禁權不開。","俗流實驕矜，得志輕草萊。","文王賴多士，漢帝資羣才。","一言竝拜相，片善咸居台。","夫君何不遇，爲泣黃金臺。"]', '["明时無廢人，廣廈無棄材。","良工不我顧，有用寧自媒。","懷策望君门，歲晏空遲迴。","秦城多车马，日夕飞塵埃。","伐鼓千门啓，鳴珂雙闕来。","我闻雷雨施，天澤罔不該。","何意斯人徒，棄之如死灰。","主好臣必効，时禁權不开。","俗流實驕矜，得志轻草萊。","文王賴多士，漢帝資羣才。","一言竝拜相，片善咸居台。","夫君何不遇，爲泣黄金台。"]', '诗', 'shi', '', NULL, '懷哉行 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c5da0f9-17f9-4a5f-acc2-9ae3636abc57', '古興', '古兴', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["日中望雙闕，軒蓋揚飛塵。","鳴珮初罷朝，自言皆近臣。","光華滿道路，意氣安可親。","歸來宴高堂，廣筵羅八珍。","僕妾盡綺紈，歌舞夜達晨。","四時固相代，誰能久要津。","已看覆前車，未見易後輪。","丈夫須兼濟，豈能樂一身。","君今皆得志，肯顧憔悴人。"]', '["日中望雙闕，軒蓋揚飞塵。","鳴珮初罷朝，自言皆近臣。","光华满道路，意氣安可親。","归来宴高堂，廣筵羅八珍。","僕妾尽綺紈，歌舞夜達晨。","四时固相代，誰能久要津。","已看覆前车，未见易後輪。","丈夫須兼濟，豈能乐一身。","君今皆得志，肯顧憔悴人。"]', '诗', 'shi', '', NULL, '古興 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24423d72-188c-4ac9-bd1d-39b7aa38eb71', '冬夜寓居寄儲太祝', '冬夜寓居寄儲太祝', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["自爲洛陽客，夫子吾知音。","愛義能下士，時人無此心。","奈何離居夜，巢鳥飛空林。","愁坐至月上，復聞南鄰砧。"]', '["自爲洛陽客，夫子吾知音。","愛義能下士，时人無此心。","奈何離居夜，巢鸟飞空林。","愁坐至月上，复闻南鄰砧。"]', '诗', 'shi', '', NULL, '冬夜寓居寄儲太祝 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be0b34a-9190-4a0d-bc3e-271aa7cc2bcf', '登秦望山', '登秦望山', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["南登秦望山，目極大海空。","朝陽半蕩漾，晃朗天水紅。","谿壑爭噴薄，江湖遰交通。","而多漁商客，不悟歲月窮。","振緡迎早潮，弭櫂候長風。","予本萍泛者，乘流任西東。","茫茫天際帆，棲泊何時同。","將尋會稽迹，從此訪任公。"]', '["南登秦望山，目極大海空。","朝陽半蕩漾，晃朗天水紅。","谿壑爭噴薄，江湖遰交通。","而多漁商客，不悟歲月窮。","振緡迎早潮，弭櫂候长风。","予本萍泛者，乘流任西东。","茫茫天際帆，棲泊何时同。","將尋會稽迹，從此訪任公。"]', '诗', 'shi', '', NULL, '登秦望山 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02880a43-5d89-4b2b-b2a9-f99228969262', '西陵口觀海', '西陵口观海', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["長江漫湯湯，近海勢彌廣。","在昔胚渾凝，融爲百川泱。","地形失端倪，天色灒滉漾。","東南際萬里，極目遠無象。","山影乍浮沈，潮波忽來往。","孤帆或不見，櫂歌猶想像。","日暮長風起，客心空振蕩。","浦口霞未收，潭心月初上。","林嶼幾邅迴，亭臯時偃仰。","歲晏訪蓬瀛，真游非外獎。"]', '["长江漫湯湯，近海勢彌廣。","在昔胚渾凝，融爲百川泱。","地形失端倪，天色灒滉漾。","东南際万里，極目远無象。","山影乍浮沈，潮波忽来往。","孤帆或不见，櫂歌猶想像。","日暮长风起，客心空振蕩。","浦口霞未收，潭心月初上。","林嶼幾邅迴，亭臯时偃仰。","歲晏訪蓬瀛，真游非外獎。"]', '诗', 'shi', '', NULL, '西陵口觀海 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea82076e-44f8-4d9c-8844-a2325b642224', '題鶴林寺', '題鹤林寺', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["道門隱形勝，向背臨法橋。","松覆山殿冷，花藏溪路遙。","珊珊寶幡挂，燄燄明燈燒。","遲日半空谷，春風連上潮。","少憑水木興，暫忝身心調。","願謝攜手客，茲山禪侶饒。"]', '["道门隐形勝，向背臨法橋。","松覆山殿冷，花藏溪路遙。","珊珊寶幡挂，燄燄明灯燒。","遲日半空谷，春风連上潮。","少憑水木兴，暫忝身心調。","願謝携手客，茲山禪侶饒。"]', '诗', 'shi', '', NULL, '題鶴林寺 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40bd73fb-a66f-4a4b-972c-f6cd96d4feeb', '初去郡齋書懷', '初去郡斋书懷', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["肅徒辭汝頴，懷古獨悽然。","尚想文王化，猶思巢父賢。","時移多讒巧，大道竟誰傳。","況是疾風起，悠悠旌斾懸。","征鳥無返翼，歸流不停川。","已經霜雪下，乃驗松柏堅。","回首望城邑，迢迢間雲煙。","志士不傷物，小人皆自妍。","感時惟責己，在道非怨天。","從此適樂土，東歸知幾年。"]', '["肅徒辞汝頴，懷古独悽然。","尚想文王化，猶思巢父賢。","时移多讒巧，大道竟誰傳。","況是疾风起，悠悠旌斾懸。","征鸟無返翼，归流不停川。","已經霜雪下，乃驗松柏堅。","回首望城邑，迢迢间云煙。","志士不傷物，小人皆自妍。","感时惟責己，在道非怨天。","從此適乐土，东归知幾年。"]', '诗', 'shi', '', NULL, '初去郡齋書懷 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a719764c-f6df-489f-ace4-b2ccb907bfb4', '出青門往南山下別業', '出青门往南山下別業', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["舊居在南山，夙駕自城闕。","榛莽相蔽虧，去爾漸超忽。","散漫餘雪晴，蒼茫季冬月。","寒風吹長林，白日原上沒。","懷抱曠莫伸，相知阻胡越。","弱年好棲隱，鍊藥在巖窟。","及此離垢氛，興來亦因物。","末路期赤松，斯言庶不伐。"]', '["旧居在南山，夙駕自城闕。","榛莽相蔽虧，去爾漸超忽。","散漫餘雪晴，蒼茫季冬月。","寒风吹长林，白日原上沒。","懷抱曠莫伸，相知阻胡越。","弱年好棲隐，鍊藥在巖窟。","及此離垢氛，兴来亦因物。","末路期赤松，斯言庶不伐。"]', '诗', 'shi', '', NULL, '出青門往南山下別業 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f3dd79-df81-4677-9b73-f5b31c53f1d9', '泊震澤口', '泊震澤口', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["日落草木陰，舟徒泊江汜。","蒼茫萬象開，合沓聞風水。","洄沿值漁翁，䆗窱逢樵子。","雲開天宇靜，月明照萬里。","早鴈湖上飛，晨鐘海邊起。","獨坐嗟遠游，登岸望孤洲。","零落星欲盡，朣朧氣漸收。","行藏空自秉，智識仍未周。","伍胥既仗劒，范蠡亦乘流。","歌竟鼓楫去，三江多客愁。"]', '["日落草木陰，舟徒泊江汜。","蒼茫万象开，合沓闻风水。","洄沿值漁翁，䆗窱逢樵子。","云开天宇静，月明照万里。","早鴈湖上飞，晨鐘海邊起。","独坐嗟远游，登岸望孤洲。","零落星欲尽，朣朧氣漸收。","行藏空自秉，智識仍未周。","伍胥既仗劒，范蠡亦乘流。","歌竟鼓楫去，三江多客愁。"]', '诗', 'shi', '', NULL, '泊震澤口 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b76ba067-1fbd-4d7f-9326-5891bdd71be2', '題丹陽陶司馬廳壁', '題丹陽陶司马廳壁', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["高鑒清洞徹，儒風入進難。","詔書增寵命，才子益能官。","門帶山光晚，城臨江水寒。","唯餘好文客，時得咏幽蘭。"]', '["高鑒清洞徹，儒风入進难。","詔书增寵命，才子益能官。","门带山光晚，城臨江水寒。","唯餘好文客，时得咏幽蘭。"]', '诗', 'shi', '', NULL, '題丹陽陶司馬廳壁 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cb9e31-1ff3-46dc-926a-4f6aafe01f5a', '古興', '古兴', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["投珠恐見疑，抱玉但垂泣。","道在君不舉，功成嘆何及。"]', '["投珠恐见疑，抱玉但垂泣。","道在君不舉，功成嘆何及。"]', '诗', 'shi', '', NULL, '古興 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d306936-bcaa-4720-b6f0-a0408d989362', '早發上東門', '早發上东门', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["十五能文西入秦，三十無家作路人。","時命不將明主合，布衣空惹洛陽塵。"]', '["十五能文西入秦，三十無家作路人。","时命不將明主合，布衣空惹洛陽塵。"]', '诗', 'shi', '', NULL, '早發上東門 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4752947e-cd1c-4654-809c-e701e413d200', '句', '句', '64e4607a-39a1-4412-a256-684d30ed3b85', '唐', '["省署開文苑，滄浪學釣翁。","窮冬時短晷，日盡西南天。"]', '["省署开文苑，滄浪学釣翁。","窮冬时短晷，日尽西南天。"]', '诗', 'shi', '', NULL, '句 薛據 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd2084e-e3ef-4c63-b240-c38981eb41f1', '秋夕會友', '秋夕會友', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["倦客易相失，懽遊無良辰。","忽然一夕間，稍慰闔家貧。","白露下庭梧，孤琴始悲辛。","迴風入幽草，蟲響滿四鄰。","會遇更何時，持桮重殷勤。"]', '["倦客易相失，懽游無良辰。","忽然一夕间，稍慰闔家貧。","白露下庭梧，孤琴始悲辛。","迴风入幽草，蟲响满四鄰。","會遇更何时，持桮重殷勤。"]', '诗', 'shi', '', NULL, '秋夕會友 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c918c2-50ca-4b10-b766-0663c6fa1227', '荆山獨往', '荆山独往', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["宿昔山水上，抱琴獨躑躅。","山遠去難窮，琴悲多斷續。","巖重丹陽樹，泉咽聞陰谷。","時下白雲中，淹留秋水曲。","秋水石欄深，潺湲如噴玉。","雜芳被陰岸，墜露方消綠。","恣此平生懷，獨游還自足。"]', '["宿昔山水上，抱琴独躑躅。","山远去难窮，琴悲多斷續。","巖重丹陽樹，泉咽闻陰谷。","时下白云中，淹留秋水曲。","秋水石欄深，潺湲如噴玉。","杂芳被陰岸，墜露方消綠。","恣此平生懷，独游還自足。"]', '诗', 'shi', '', NULL, '荆山獨往 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb8e3c11-4405-450d-ab33-af54d1dc2df0', '五老峰大明觀贈隱者', '五老峰大明观贈隐者', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["雲觀此山北，與君攜手稀。","林端涉橫水，洞口入斜暉。","頗覺鸞鶴邇，忽爲煙霧飛。","故人清和客，默會琴心微。","丹術幸可授，青龍當未歸。","悠悠平生意，此日復相違。"]', '["云观此山北，與君携手稀。","林端涉橫水，洞口入斜暉。","頗覺鸾鹤邇，忽爲煙霧飞。","故人清和客，默會琴心微。","丹術幸可授，青龙當未归。","悠悠平生意，此日复相違。"]', '诗', 'shi', '', NULL, '五老峰大明觀贈隱者 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f1f014-da88-4c84-9b73-79b9ff2e1162', '送周愿判官歸嶺南', '送周愿判官归嶺南', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["早蟬望秋鳴，夜琴怨離聲。","眇然多異感，值子江山行。","由來重義人，感激事縱橫。","往復念遐阻，淹留慕平生。","晨奔九衢餞，暮始萬里程。","山驛風月榭，海門煙霞城。","易綃泉源近，拾翠沙漵明。","蘭蕙一爲贈，貧交空復情。"]', '["早蟬望秋鳴，夜琴怨離声。","眇然多異感，值子江山行。","由来重義人，感激事縱橫。","往复念遐阻，淹留慕平生。","晨奔九衢餞，暮始万里程。","山驛风月榭，海门煙霞城。","易綃泉源近，拾翠沙漵明。","蘭蕙一爲贈，貧交空复情。"]', '诗', 'shi', '', NULL, '送周愿判官歸嶺南 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6963394-b39a-4899-8607-fcac7af9e2b3', '送陸渾主簿趙宗儒之任', '送陸渾主簿趙宗儒之任', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["山中眇然意，此意乃平生。","常日望鳴臯，遙對洛陽城。","故人吏爲隱，懷此若蓬瀛。","夕氣冒巖上，晨流瀉岸明。","存亡區中事，影響羽人情。","溪寂值猨下，雲歸聞鶴聲。","及茲春始暮，花葛正明榮。","會有攜手日，悠悠去無程。"]', '["山中眇然意，此意乃平生。","常日望鳴臯，遙对洛陽城。","故人吏爲隐，懷此若蓬瀛。","夕氣冒巖上，晨流瀉岸明。","存亡區中事，影响羽人情。","溪寂值猨下，云归闻鹤声。","及茲春始暮，花葛正明榮。","會有携手日，悠悠去無程。"]', '诗', 'shi', '', NULL, '送陸渾主簿趙宗儒之任 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15df8151-88f7-46a1-bfef-790acfcdb1e1', '楊參軍莊送宇文邈', '楊參軍莊送宇文邈', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["秋雲冒原隰，野鳥滿林聲。","愛此田舍事，稽君車馬程。","離堂慘不喧，脈脈復盈盈。","蘭葉一經霜，香銷爲贈輕。","燈光耿方寂，蟲思隱餘清。","相望忽無際，如含江海情。"]', '["秋云冒原隰，野鸟满林声。","愛此田舍事，稽君车马程。","離堂慘不喧，脈脈复盈盈。","蘭葉一經霜，香銷爲贈轻。","灯光耿方寂，蟲思隐餘清。","相望忽無際，如含江海情。"]', '诗', 'shi', '', NULL, '楊參軍莊送宇文邈 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3caf4a4-4512-4a42-b34f-1e8c3f2e8950', '京西遇舊識兼送往隴西', '京西遇旧識兼送往隴西', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["蟬鳴一何急，日暮秋風樹。","即此不勝愁，隴陰人更去。","相逢與相失，共是亡羊路。"]', '["蟬鳴一何急，日暮秋风樹。","即此不勝愁，隴陰人更去。","相逢與相失，共是亡羊路。"]', '诗', 'shi', '', NULL, '京西遇舊識兼送往隴西 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2d6b86-8381-47ab-b445-cc46c28b0be4', '古別離', '古別離', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["涼風已嫋嫋，露重木蘭枝。","獨上高樓望，行人遠不知。","輕寒入洞戶，明月滿秋池。","燕去鴻方至，年年是別離。"]', '["涼风已嫋嫋，露重木蘭枝。","独上高楼望，行人远不知。","轻寒入洞戶，明月满秋池。","燕去鴻方至，年年是別離。"]', '诗', 'shi', '', NULL, '古別離 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e86a927e-fe41-4bd4-9e00-2a5e5b1aab06', '野居池上看月', '野居池上看月', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["悠然雲間月，復此照池塘。","泫露蒼茫濕，沈波澹灩光。","應門當未曙，歌吹滿昭陽。","遠近徒傷目，清輝靄自長。"]', '["悠然云间月，复此照池塘。","泫露蒼茫濕，沈波澹灩光。","應门當未曙，歌吹满昭陽。","远近徒傷目，清輝靄自长。"]', '诗', 'shi', '', NULL, '野居池上看月 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138a236c-ce00-433b-8931-5460b685d243', '庭柳', '庭柳', '0ab6f8e7-3f21-45c3-9779-ad1dd0babe39', '唐', '["褭褭柳楊枝，當軒雜珮垂。","交陰總共密，分條各自宜。","因依似永久，攬結更傷離。","愛此陽春色，秋風莫遽吹。"]', '["褭褭柳楊枝，當軒杂珮垂。","交陰總共密，分條各自宜。","因依似永久，攬結更傷離。","愛此陽春色，秋风莫遽吹。"]', '诗', 'shi', '', NULL, '庭柳 姚係 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b4b1689-e229-4002-a9d4-c99999b9d628', '硤州旅舍奉懷蘇州韋郎中', '硤州旅舍奉懷蘇州韋郎中', '97b14f1c-e9e4-4095-a6c6-2c3026709cf0', '唐', '["儒服學從政，遂爲塵事嬰。","銜命東復西，孰堪異鄉情。","懷祿且懷恩，策名敢逃名。","羨彼農畝人，白首親友幷。","江山入秋氣，草木彫晚榮。","方塘寒露凝，旅管涼飆生。","懿交守東吳，夢想聞頌聲。","雲水方浩浩，離憂何平時。"]', '["儒服学從政，遂爲塵事嬰。","銜命东复西，孰堪異乡情。","懷祿且懷恩，策名敢逃名。","羨彼農畝人，白首親友幷。","江山入秋氣，草木彫晚榮。","方塘寒露凝，旅管涼飆生。","懿交守东吳，梦想闻頌声。","云水方浩浩，離憂何平时。"]', '诗', 'shi', '', NULL, '硤州旅舍奉懷蘇州韋郎中 令狐峘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35c04ebe-2894-441a-ab7a-65c4ad2cded6', '釋奠日國學觀禮聞雅頌', '釋奠日国学观禮闻雅頌', '97b14f1c-e9e4-4095-a6c6-2c3026709cf0', '唐', '["肅肅先師廟，依依胄子羣。","滿庭陳舊禮，開戶拜清芬。","萬舞當華燭，簫韶入翠雲。","頌歌清曉聽，雅吹度風聞。","澹泊調元氣，中和美聖君。","唯餘東魯客，蹈舞向南熏。"]', '["肅肅先師廟，依依胄子羣。","满庭陳旧禮，开戶拜清芬。","万舞當华燭，簫韶入翠云。","頌歌清晓听，雅吹度风闻。","澹泊調元氣，中和美聖君。","唯餘东魯客，蹈舞向南熏。"]', '诗', 'shi', '', NULL, '釋奠日國學觀禮聞雅頌 令狐峘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e491bb5b-4dc4-48a1-8e27-6ad20691adbc', '釋奠日國學觀禮聞雅頌', '釋奠日国学观禮闻雅頌', '31163e07-e9ed-465a-ac37-2f079f60ba50', '唐', '["太學時觀禮，東方曉色分。","威儀何棣棣，環珮又紛紛。","古樂從空盡，清歌幾處聞。","六和成遠吹，九奏動行雲。","聖上尊儒學，春秋奠茂勳。","幸因陪齒列，聊以頌斯文。"]', '["太学时观禮，东方晓色分。","威儀何棣棣，环珮又紛紛。","古乐從空尽，清歌幾处闻。","六和成远吹，九奏动行云。","聖上尊儒学，春秋奠茂勳。","幸因陪齒列，聊以頌斯文。"]', '诗', 'shi', '', NULL, '釋奠日國學觀禮聞雅頌 滕珦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8bc9ef-caab-4fc0-a99a-cf3e2ca892ea', '奉和聖製麟德殿燕百僚應制', '奉和聖製麟德殿燕百僚應制', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["雲闢御筵張，山呼聖壽長。","玉闌豐瑞草，金陛立神羊。","台鼎資庖膳，天星奉酒漿。","蠻夷陪作位，犀象舞成行。","網已袪三面，歌因守四方。","千秋不可極，花發滿宮香。"]', '["云闢御筵張，山呼聖壽长。","玉闌豐瑞草，金陛立神羊。","台鼎資庖膳，天星奉酒漿。","蠻夷陪作位，犀象舞成行。","網已袪三面，歌因守四方。","千秋不可極，花發满宮香。"]', '诗', 'shi', '', NULL, '奉和聖製麟德殿燕百僚應制 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c193ecd8-d9f3-47aa-9445-5a3942ce54d2', '晚秋集賢院即事寄徐薛二侍郎', '晚秋集賢院即事寄徐薛二侍郎', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["穆穆上清居，沈沈中祕書。","金鋪深內殿，石甃淨寒渠。","花樹臺斜倚，空煙閣半虛。","縹囊披錦繡，翠軸卷瓊琚。","墨潤冰文繭，香銷蠹字魚。","翻黃桐葉老，吐白桂花初。","舊德雙遊處，聊芳十載餘。","北朝榮庾薛，西漢盛嚴徐。","侍講親華扆，徴吟步綺疏。","綴簾金翡翠，賜硯玉蟾蜍。","序秩東南遠，離憂歲月除。","承明期重入，江海意何如。"]', '["穆穆上清居，沈沈中祕书。","金鋪深內殿，石甃淨寒渠。","花樹台斜倚，空煙閣半虛。","縹囊披錦繡，翠軸卷瓊琚。","墨潤冰文繭，香銷蠹字鱼。","翻黄桐葉老，吐白桂花初。","旧德雙游处，聊芳十載餘。","北朝榮庾薛，西漢盛嚴徐。","侍講親华扆，徴吟步綺疏。","綴簾金翡翠，賜硯玉蟾蜍。","序秩东南远，離憂歲月除。","承明期重入，江海意何如。"]', '诗', 'shi', '', NULL, '晚秋集賢院即事寄徐薛二侍郎 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295e5733-ef27-469e-afc1-2a487f3f9b4a', '早秋望華清宮樹因以成詠', '早秋望华清宮樹因以成詠', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["可憐雲木叢，滿禁碧濛濛。","色潤靈泉近，險清輦路通。","玉壇標八桂，金井識雙桐。","交映凝寒露，相和起夜風。","數枝盤石上，幾葉落雲中。","燕拂宜秋霽，蟬鳴覺晝空。","翠屏更隱見，珠綴共玲瓏。","雷雨生成早，樵蘇禁令雄。","野藤高助綠，仙果迥呈紅。","惆悵繚垣暮，茲山聞暗蟲。"]', '["可怜云木叢，满禁碧濛濛。","色潤靈泉近，險清輦路通。","玉壇標八桂，金井識雙桐。","交映凝寒露，相和起夜风。","數枝盤石上，幾葉落云中。","燕拂宜秋霽，蟬鳴覺晝空。","翠屏更隐见，珠綴共玲瓏。","雷雨生成早，樵蘇禁令雄。","野藤高助綠，仙果迥呈紅。","惆悵繚垣暮，茲山闻暗蟲。"]', '诗', 'shi', '', NULL, '早秋望華清宮樹因以成詠 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc029604-680e-4a44-9318-c28b4b3e689b', '和考功員外杪秋憶終南舊宅之作', '和考功員外杪秋憶終南旧宅之作', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["靜憶溪邊宅，知君許謝公。","曉霜凝耒耜，初日照梧桐。","澗鼠喧藤蔓，山禽竄石叢。","白雲當嶺雨，黃葉繞階風。","野菓垂橋上，高泉落水中。","歡榮來自間，羸賤賞曾通。","月滿珠藏海，天晴鶴在籠。","餘陰如可寄，願得隱牆東。"]', '["静憶溪邊宅，知君許謝公。","晓霜凝耒耜，初日照梧桐。","澗鼠喧藤蔓，山禽竄石叢。","白云當嶺雨，黄葉繞階风。","野菓垂橋上，高泉落水中。","歡榮来自间，羸賤賞曾通。","月满珠藏海，天晴鹤在籠。","餘陰如可寄，願得隐牆东。"]', '诗', 'shi', '', NULL, '和考功員外杪秋憶終南舊宅之作 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ced84be-43c1-42b1-8740-f884b354c351', '題金吾郭將軍石洑茅堂', '題金吾郭將軍石洑茅堂', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["雲戟曙沈沈，軒墀清且深。","家傳成棟美，堯寵結茅心。","玉佩多依石，油幢亦在林。","爐香諸洞暖，殿影衆山陰。","草奏風生筆，筵開雪滿琴。","客從龍闕至，僧自虎溪尋。","瀟灑延清賞，周流會素襟。","終朝惜塵步，一醉見華簪。"]', '["云戟曙沈沈，軒墀清且深。","家傳成棟美，堯寵結茅心。","玉佩多依石，油幢亦在林。","爐香諸洞暖，殿影衆山陰。","草奏风生笔，筵开雪满琴。","客從龙闕至，僧自虎溪尋。","瀟灑延清賞，周流會素襟。","終朝惜塵步，一醉见华簪。"]', '诗', 'shi', '', NULL, '題金吾郭將軍石洑茅堂 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('565a2c0f-1c88-4611-b7b8-d5218070b564', '登棲霞寺', '登棲霞寺', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["林香雨氣新，山寺綠無塵。","遂結雲外侶，共遊天上春。","鶴鳴金閣麗，僧語竹房鄰。","待月水流急，惜花風起頻。","何方非壞境，此地有歸人。","迴首空門外，皤然一幻身。"]', '["林香雨氣新，山寺綠無塵。","遂結云外侶，共游天上春。","鹤鳴金閣丽，僧語竹房鄰。","待月水流急，惜花风起頻。","何方非壞境，此地有归人。","迴首空门外，皤然一幻身。"]', '诗', 'shi', '', NULL, '登棲霞寺 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3efaa1-c7ef-4dae-b156-1e7cc5fda201', '逢南中使寄嶺外故人', '逢南中使寄嶺外故人', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["見說南來處，蒼梧指桂林。","過秋天更煖，邊海日長陰。","巴路緣雲出，蠻鄉入洞深。","信回人自老，夢到月應沈。","碧水通春色，青山寄遠心。","炎方難久客，爲爾一霑襟。"]', '["见说南来处，蒼梧指桂林。","過秋天更煖，邊海日长陰。","巴路緣云出，蠻乡入洞深。","信回人自老，梦到月應沈。","碧水通春色，青山寄远心。","炎方难久客，爲爾一霑襟。"]', '诗', 'shi', '', NULL, '逢南中使寄嶺外故人 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10888010-cf60-49f7-b7e8-eac8bc94c29e', '代員將軍罷戰後歸故里', '代員將軍罷戰後归故里', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["結髮事疆場，全生到海鄉。","連雲防鐵嶺，同日破漁陽。","牧馬胡天晚，移軍磧路長。","枕戈眠古戍，吹角立繁霜。","歸老勳仍在，酬恩虜未忘。","獨行過邑里，多病對農桑。","雄劒依塵橐，兵符寄藥囊。","空餘麾下將，猶逐羽林郎。"]', '["結髮事疆場，全生到海乡。","連云防鐵嶺，同日破漁陽。","牧马胡天晚，移軍磧路长。","枕戈眠古戍，吹角立繁霜。","归老勳仍在，酬恩虜未忘。","独行過邑里，多病对農桑。","雄劒依塵橐，兵符寄藥囊。","空餘麾下將，猶逐羽林郎。"]', '诗', 'shi', '', NULL, '代員將軍罷戰後歸故里 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16416b61-ecc2-4ae7-8cb2-7dd2bb5521d2', '詠冬瑰花', '詠冬瑰花', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["獨鶴寄煙霜，雙鸞思晚芳。","舊陰依謝宅，新豔出蕭牆。","蝶散搖輕露，鶯銜入夕陽。","雨朝勝濯錦，風夜劇焚香。","麗日千層豔，孤霞一片光。","密來驚葉少，動處覺枝長。","布影期高賞，留春爲遠方。","嘗聞贈瓊玖，叨和愧升堂。"]', '["独鹤寄煙霜，雙鸾思晚芳。","旧陰依謝宅，新豔出蕭牆。","蝶散搖轻露，鶯銜入夕陽。","雨朝勝濯錦，风夜劇焚香。","丽日千層豔，孤霞一片光。","密来驚葉少，动处覺枝长。","布影期高賞，留春爲远方。","嘗闻贈瓊玖，叨和愧升堂。"]', '诗', 'shi', '', NULL, '詠冬瑰花 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6196a33c-c420-4b81-9d97-e93c46f3c8dd', '句', '句', 'e037a716-f505-4277-ba24-882a2651121b', '唐', '["風候已應同嶺北，雲山仍喜似終南。"]', '["风候已應同嶺北，云山仍喜似終南。"]', '诗', 'shi', '', NULL, '句 常衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d05ab2-8a42-4338-a7a7-a1cd4b6d1d17', '登聖善寺閣', '登聖善寺閣', 'f9f5bfd9-5750-4203-aa5e-7bb136b7a38b', '唐', '["飛閣青霞裏，先秋獨早涼。","天花映窗近，月桂拂簷香。","華岳三峰小，黃河一帶長。","空間指歸路，煙際有垂楊。"]', '["飞閣青霞裏，先秋独早涼。","天花映窗近，月桂拂簷香。","华岳三峰小，黄河一带长。","空间指归路，煙際有垂楊。"]', '诗', 'shi', '', NULL, '登聖善寺閣 褚朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a695c3-28a6-4dde-89f9-c8c15b5c3887', '五絲', '五絲', 'f9f5bfd9-5750-4203-aa5e-7bb136b7a38b', '唐', '["越人傳楚俗，截竹競縈絲。","水底深休也，日中遠賀之。","章施文勝質，列匹美於姬。","錦繡侔新段，羔羊寢舊詩。","但誇端午節，誰薦屈原祠。","把酒時伸奠，汨羅空遠而。"]', '["越人傳楚俗，截竹競縈絲。","水底深休也，日中远賀之。","章施文勝質，列匹美於姬。","錦繡侔新段，羔羊寢旧诗。","但誇端午節，誰薦屈原祠。","把酒时伸奠，汨羅空远而。"]', '诗', 'shi', '', NULL, '五絲 褚朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22638786-aea2-48d0-82ea-08a4fd47a948', '奉上徐中書', '奉上徐中书', 'f9f5bfd9-5750-4203-aa5e-7bb136b7a38b', '唐', '["中禁仙池越鳳凰，池邊詞客紫薇郎。","既能作頌雄風起，何不時吹蘭蕙香。"]', '["中禁仙池越鳳凰，池邊词客紫薇郎。","既能作頌雄风起，何不时吹蘭蕙香。"]', '诗', 'shi', '', NULL, '奉上徐中書 褚朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa428c7-2354-4bfb-817e-8e8b3be85849', '小洞庭洄源亭讌四郡太守詩', '小洞庭洄源亭讌四郡太守诗', '1422348a-14e1-41b4-ba06-2e4a925244f0', '唐', '["小洞庭兮牽方舟，風嫋嫋兮離平流。","牽方舟兮小洞庭，雲微微兮連絕𡷨。","層瀾壯兮緬以沒，重巖轉兮超以忽。","馮夷逝兮護輕橈，蛟龍行兮落增潮。","泊中湖兮澹而閑，並曲漵兮悵而還。","適予手兮非予期，將解袂兮藂予思。","尚君子兮壽厥身，承明主兮憂斯人。"]', '["小洞庭兮牽方舟，风嫋嫋兮離平流。","牽方舟兮小洞庭，云微微兮連絕𡷨。","層瀾壯兮緬以沒，重巖轉兮超以忽。","馮夷逝兮護轻橈，蛟龙行兮落增潮。","泊中湖兮澹而闲，並曲漵兮悵而還。","適予手兮非予期，將解袂兮藂予思。","尚君子兮壽厥身，承明主兮憂斯人。"]', '诗', 'shi', '', NULL, '小洞庭洄源亭讌四郡太守詩 蘇源明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62cb7105-4cf3-4656-b441-fabe9a7f6c6f', '秋夜小洞庭離讌詩', '秋夜小洞庭離讌诗', '1422348a-14e1-41b4-ba06-2e4a925244f0', '唐', '["浮漲湖兮莽迢遙，川后禮兮扈予橈。","橫增沃兮蓬仙延，川后福兮易予舷。","月澄凝兮明空波，星磊落兮耿秋河。","夜既良兮酒且多，樂方作兮奈別何。"]', '["浮漲湖兮莽迢遙，川后禮兮扈予橈。","橫增沃兮蓬仙延，川后福兮易予舷。","月澄凝兮明空波，星磊落兮耿秋河。","夜既良兮酒且多，乐方作兮奈別何。"]', '诗', 'shi', '', NULL, '秋夜小洞庭離讌詩 蘇源明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6edde6e-23c4-4049-85a5-9e13be8cb2dd', '閨情', '閨情', '9bea10f1-a9d3-4033-ac3b-e48fd1163eba', '唐', '["銀鑰開香閣，金臺照夜燈。","長征君自慣，獨臥妾何曾。"]', '["銀鑰开香閣，金台照夜灯。","长征君自慣，独臥妾何曾。"]', '诗', 'shi', '', NULL, '閨情 鄭虔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc6c85c-d5a0-41f5-8ac8-ece3aaced577', '古意', '古意', 'e146c9d3-0a01-489f-afb0-c6c9726a191c', '唐', '["璇閨繡戶斜光入，千金女兒倚門立。","橫波美目雖往來，羅袂遙遙不相及。","聞道今年初避人，珊珊挂鏡長隨身。","願得侍兒爲道意，後堂羅帳一相親。"]', '["璇閨繡戶斜光入，千金女兒倚门立。","橫波美目雖往来，羅袂遙遙不相及。","闻道今年初避人，珊珊挂镜长隨身。","願得侍兒爲道意，後堂羅帳一相親。"]', '诗', 'shi', '', NULL, '古意 畢耀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5949236-b878-4ef5-aa53-445651fb04ac', '情人玉清歌', '情人玉清歌', 'e146c9d3-0a01-489f-afb0-c6c9726a191c', '唐', '["洛陽有人名玉清，可憐玉清如其名。","善踏斜柯能獨立，嬋娟花豔無人及。","珠爲帬，玉爲纓，臨春風，吹玉笙。","悠悠滿天星，黃金閣上晚妝成。","雲和曲中爲曼聲，玉梯不得蹈。","搖袂兩盈盈，城頭之日復何情。"]', '["洛陽有人名玉清，可怜玉清如其名。","善踏斜柯能独立，嬋娟花豔無人及。","珠爲帬，玉爲纓，臨春风，吹玉笙。","悠悠满天星，黄金閣上晚妝成。","云和曲中爲曼声，玉梯不得蹈。","搖袂兩盈盈，城头之日复何情。"]', '诗', 'shi', '', NULL, '情人玉清歌 畢耀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc7a06a-394c-4d6f-8f18-c4b0c760351e', '贈獨孤常州', '贈独孤常州', 'e146c9d3-0a01-489f-afb0-c6c9726a191c', '唐', '["洪爐無久停，日月速若飛。","忽然衝人身，飲酒不須疑。"]', '["洪爐無久停，日月速若飞。","忽然衝人身，饮酒不須疑。"]', '诗', 'shi', '', NULL, '贈獨孤常州 畢耀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b938a5-895c-4b05-bef8-c11f37a9b52f', '奉和聖製次瓊嶽應制', '奉和聖製次瓊嶽應制', '7d98edcf-de16-47aa-bccf-5d5594b66d56', '唐', '["陸海披晴雪，千旗獵早陽。","岳臨秦路險，河遶漢垣長。","行漏通鳷鵲，離宮接建章。","都門信宿近，歌舞從周王。"]', '["陸海披晴雪，千旗獵早陽。","岳臨秦路險，河遶漢垣长。","行漏通鳷鵲，離宮接建章。","都门信宿近，歌舞從周王。"]', '诗', 'shi', '', NULL, '奉和聖製次瓊嶽應制 韋濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a02ee4-3f26-49f3-84b4-3a0b8b8b0e9c', '成都爲客作', '成都爲客作', '2d82ef2e-ae05-4d20-a5da-c360541d81f6', '唐', '["蜀郡將之遠，城南萬里橋。","衣緣鄉淚濕，貌以客愁銷。","地富魚爲米，山芳桂是樵。","旅遊唯得酒，今日過明朝。"]', '["蜀郡將之远，城南万里橋。","衣緣乡泪濕，貌以客愁銷。","地富鱼爲米，山芳桂是樵。","旅游唯得酒，今日過明朝。"]', '诗', 'shi', '', NULL, '成都爲客作 田澄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3885e598-42c4-4a9c-904f-9b28617d0aae', '奉和苑舍人宿直曉翫新池寄南省友', '奉和苑舍人宿直晓翫新池寄南省友', '22301e15-9d3a-4fbc-bdaa-55e189f88d13', '唐', '["傳聞閶闔裏，寓直有神仙。","史爲三墳博，郎因五字遷。","晨臨翔鳳沼，春注躍龍泉。","去似登天上，來如看鏡前。","影搖宸翰發，波淨列星懸。","既濟仍懷友，流謙欲進賢。","彈冠聲實貴，覆被渥恩偏。","溫室言雖阻，文場契獨全。","玉珂光赫奕，朱紱氣蟬聯。","興逸潘仁賦，名高謝朓篇。","青雲仰不逮，白雲和難牽。","苒苒胡爲此，甘心老歲年。"]', '["傳闻閶闔裏，寓直有神仙。","史爲三墳博，郎因五字遷。","晨臨翔鳳沼，春注躍龙泉。","去似登天上，来如看镜前。","影搖宸翰發，波淨列星懸。","既濟仍懷友，流謙欲進賢。","彈冠声實貴，覆被渥恩偏。","溫室言雖阻，文場契独全。","玉珂光赫奕，朱紱氣蟬聯。","兴逸潘仁賦，名高謝朓篇。","青云仰不逮，白云和难牽。","苒苒胡爲此，甘心老歲年。"]', '诗', 'shi', '', NULL, '奉和苑舍人宿直曉翫新池寄南省友 沈東美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0b63a5-3a74-48aa-873d-bd2206c7ae06', '變律 一', '变律 一', '0d1e57d3-f45f-4fbd-932e-17f82029e736', '唐', '["日月東西行，寒暑冬夏易。","陰陽無停機，造化渺莫測。","開目爲晨光，閉目爲夜色。","一開復一閉，明晦無休息。","居然六合外，曠哉天地德。","天地且不言，世人浪喧喧。"]', '["日月东西行，寒暑冬夏易。","陰陽無停機，造化渺莫測。","开目爲晨光，閉目爲夜色。","一开复一閉，明晦無休息。","居然六合外，曠哉天地德。","天地且不言，世人浪喧喧。"]', '诗', 'shi', '', NULL, '變律 一 蘇渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4714c39-186d-4e5f-bd1c-fdb3fbff199d', '變律 二', '变律 二', '0d1e57d3-f45f-4fbd-932e-17f82029e736', '唐', '["毒蜂成一窠，高挂惡木枝。","行人百步外，目斷魂亦飛。","長安大道邊，挾彈誰家兒。","右手持金丸，引滿無所疑。","一中紛下來，勢若風雨隨。","身如萬箭攢，宛轉迷所之。","徒有疾惡心，奈何不知幾。"]', '["毒蜂成一窠，高挂惡木枝。","行人百步外，目斷魂亦飞。","长安大道邊，挾彈誰家兒。","右手持金丸，引满無所疑。","一中紛下来，勢若风雨隨。","身如万箭攢，宛轉迷所之。","徒有疾惡心，奈何不知幾。"]', '诗', 'shi', '', NULL, '變律 二 蘇渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e4d5ec-1d8e-4a97-b69e-633f7ae6c0c2', '變律 三', '变律 三', '0d1e57d3-f45f-4fbd-932e-17f82029e736', '唐', '["養蠶爲素絲，葉盡蠶不老。","傾筐對空林，此意向誰道。","一女不得織，萬夫受其寒。","一夫不得意，四海行路難。","禍亦不在大，福亦不在先。","世路險孟門，吾徒當勉旃。"]', '["養蠶爲素絲，葉尽蠶不老。","傾筐对空林，此意向誰道。","一女不得织，万夫受其寒。","一夫不得意，四海行路难。","禍亦不在大，福亦不在先。","世路險孟门，吾徒當勉旃。"]', '诗', 'shi', '', NULL, '變律 三 蘇渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac1c147-2d6d-4d12-923e-2121413de02a', '贈零陵僧', '贈零陵僧', '0d1e57d3-f45f-4fbd-932e-17f82029e736', '唐', '["張顛沒在二十年，謂言草聖無人傳。","零陵沙門繼其後，新書大字大如斗。","興來走筆如旋風，醉後耳熱心更兇。","忽如裴旻舞雙劒，七星錯落纏蛟龍。","又如吳生畫[鬼神]，魑魅魍魎驚本身。","鉤鎖相連勢不絕，倔強毒蛇爭屈鐵。","西河舞劒氣凌雲，孤蓬自振唯有君。","今日華堂看灑落，四座喧呼歎佳作。","迴首邀余賦一章，欲令羨價齊鍾張。","琅誦囗句三百字，何似醉僧顛復狂。","忽然告我遊南溟，言祈亞相求大名。","亞相書翰凌獻之，見君絕意必深知。","南中紙價當日貴，只恐貪泉成墨池。"]', '["張顛沒在二十年，謂言草聖無人傳。","零陵沙门繼其後，新书大字大如斗。","兴来走笔如旋风，醉後耳熱心更兇。","忽如裴旻舞雙劒，七星錯落纏蛟龙。","又如吳生畫[鬼神]，魑魅魍魎驚本身。","鉤鎖相連勢不絕，倔強毒蛇爭屈鐵。","西河舞劒氣凌云，孤蓬自振唯有君。","今日华堂看灑落，四座喧呼歎佳作。","迴首邀余賦一章，欲令羨價齊鍾張。","琅誦囗句三百字，何似醉僧顛复狂。","忽然告我游南溟，言祈亞相求大名。","亞相书翰凌獻之，见君絕意必深知。","南中紙價當日貴，只恐貪泉成墨池。"]', '诗', 'shi', '', NULL, '贈零陵僧 蘇渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1634ee2-0c10-47cb-a985-0e36bf3e99a9', '江南曲', '江南曲', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["美人何蕩漾，湖上風日長。","玉手欲有贈，裴回雙明璫。","歌聲隨綠水，怨色起青陽。","日暮還家望，雲波橫洞房。"]', '["美人何蕩漾，湖上风日长。","玉手欲有贈，裴回雙明璫。","歌声隨綠水，怨色起青陽。","日暮還家望，云波橫洞房。"]', '诗', 'shi', '', NULL, '江南曲 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f097448-4dc7-43ed-aafc-3e256dba23fa', '九日送人', '九日送人', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["海上正搖落，客中還別離。","同舟去未已，遠送新相知。","流水意何極，滿尊徒爾爲。","從來菊花節，早已醉東籬。"]', '["海上正搖落，客中還別離。","同舟去未已，远送新相知。","流水意何極，满尊徒爾爲。","從来菊花節，早已醉东籬。"]', '诗', 'shi', '', NULL, '九日送人 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9532d5be-e0a2-4623-aaf5-322a8b90d1ea', '暮秋揚子江寄孟浩然', '暮秋揚子江寄孟浩然', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["木葉紛紛下，東南日煙霜。","林山相晚暮，天海空青蒼。","暝色況復久，秋聲亦何長。","孤舟兼微月，獨夜仍越鄉。","寒笛對京口，故人在襄陽。","詠思勞今夕，江漢遙相望。"]', '["木葉紛紛下，东南日煙霜。","林山相晚暮，天海空青蒼。","暝色況复久，秋声亦何长。","孤舟兼微月，独夜仍越乡。","寒笛对京口，故人在襄陽。","詠思勞今夕，江漢遙相望。"]', '诗', 'shi', '', NULL, '暮秋揚子江寄孟浩然 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dbfdde1-a5ba-440f-8acc-3d0872c72351', '潯陽陶氏別業', '潯陽陶氏別業', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["陶家習先隱，種柳長江邊。","朝夕潯陽郭，白衣來幾年。","霽雲明孤嶺，秋水澄寒天。","物象自清曠，野情何綿聯。","蕭蕭丘中賞，明宰非徒然。","願守黍稷稅，歸耕東山田。"]', '["陶家習先隐，種柳长江邊。","朝夕潯陽郭，白衣来幾年。","霽云明孤嶺，秋水澄寒天。","物象自清曠，野情何綿聯。","蕭蕭丘中賞，明宰非徒然。","願守黍稷稅，归耕东山田。"]', '诗', 'shi', '', NULL, '潯陽陶氏別業 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0732a1c2-259d-451e-b11e-11344d0ed7ce', '登廬山峰頂寺', '登廬山峰頂寺', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["孤峰臨萬象，秋氣何高清。","天際南郡出，林端西江明。","山門二緇叟，振錫聞幽聲。","心照有無界，業懸前後生。","雖知真機靜，尚與愛網幷。","方首金門路，未遑參道情。"]', '["孤峰臨万象，秋氣何高清。","天際南郡出，林端西江明。","山门二緇叟，振錫闻幽声。","心照有無界，業懸前後生。","雖知真機静，尚與愛網幷。","方首金门路，未遑參道情。"]', '诗', 'shi', '', NULL, '登廬山峰頂寺 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef01a21-89c8-4940-a633-6302a2ebeb0d', '尋東溪還湖中作', '尋东溪還湖中作', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["出山更回首，日暮清溪深。","東嶺新別處，數猨叫空林。","昔遊有初迹，此路還獨尋。","幽興方在往，歸懷復爲今。","雲峰勞前意，湖水成遠心。","望望已超越，坐鳴舟中琴。"]', '["出山更回首，日暮清溪深。","东嶺新別处，數猨叫空林。","昔游有初迹，此路還独尋。","幽兴方在往，归懷复爲今。","云峰勞前意，湖水成远心。","望望已超越，坐鳴舟中琴。"]', '诗', 'shi', '', NULL, '尋東溪還湖中作 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa03d77-459d-4b12-855b-6f34c10bfebd', '送韓平兼寄郭微', '送韓平兼寄郭微', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["上客夜相過，小童能酤酒。","即爲臨水處，正值歸鴈後。","前路望鄉山，近家見門柳。","到時春未暮，風景自應有。","余憶東州人，經年別來久。","殷勤爲傳語，日夕念攜手。","兼問前寄書，書中復達否。"]', '["上客夜相過，小童能酤酒。","即爲臨水处，正值归鴈後。","前路望乡山，近家见门柳。","到时春未暮，风景自應有。","余憶东州人，經年別来久。","殷勤爲傳語，日夕念携手。","兼问前寄书，书中复達否。"]', '诗', 'shi', '', NULL, '送韓平兼寄郭微 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53ff05c-b03f-4424-8d41-199d24f25750', '寄閻防', '寄閻防', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["青冥南山口，君與緇錫鄰。","深路入古寺，亂花隨暮春。","紛紛對寂莫，往往落衣巾。","松色空照水，經聲時有人。","晚心復南望，山遠情獨親。","應以修往業，亦惟立此身。","深林度空夜，煙月資清真。","莫歎文明日，彌年徒隱淪。"]', '["青冥南山口，君與緇錫鄰。","深路入古寺，亂花隨暮春。","紛紛对寂莫，往往落衣巾。","松色空照水，經声时有人。","晚心复南望，山远情独親。","應以修往業，亦惟立此身。","深林度空夜，煙月資清真。","莫歎文明日，彌年徒隐淪。"]', '诗', 'shi', '', NULL, '寄閻防 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e6ba3fd-d983-4950-9fec-8e55331d0c09', '海上詩送薛文學歸海東', '海上诗送薛文学归海东', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["何處歸且遠，送君東悠悠。","滄溟千萬里，日夜一孤舟。","曠望絕國所，微茫天際愁。","有時近仙境，不定若夢遊。","或見青色古，孤山百里秋。","前心方杳眇，後路勞夷猶。","離別惜吾道，風波敬皇休。","春浮花氣遠，思逐海水流。","日暮驪歌後，永懷空滄洲。"]', '["何处归且远，送君东悠悠。","滄溟千万里，日夜一孤舟。","曠望絕国所，微茫天際愁。","有时近仙境，不定若梦游。","或见青色古，孤山百里秋。","前心方杳眇，後路勞夷猶。","離別惜吾道，风波敬皇休。","春浮花氣远，思逐海水流。","日暮驪歌後，永懷空滄洲。"]', '诗', 'shi', '', NULL, '海上詩送薛文學歸海東 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa1c110-2d0d-4d83-90fc-e0d012fdfd55', '越中問海客', '越中问海客', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["風雨滄洲暮，一帆今始歸。","自云發南海，萬里速如飛。","初謂落何處，永將無所依。","冥茫漸西見，山色越中微。","誰念去時遠，人經此路稀。","泊舟悲且泣，使我亦霑衣。","浮海焉用說，憶鄉難久違。","縱爲魯連子，山路有柴扉。"]', '["风雨滄洲暮，一帆今始归。","自云發南海，万里速如飞。","初謂落何处，永將無所依。","冥茫漸西见，山色越中微。","誰念去时远，人經此路稀。","泊舟悲且泣，使我亦霑衣。","浮海焉用说，憶乡难久違。","縱爲魯連子，山路有柴扉。"]', '诗', 'shi', '', NULL, '越中問海客 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b4fe60-9809-422d-afa7-143a2088f045', '闕題', '闕題', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["道由白雲盡，春與青溪長。","時有落花至，遠隨流水香。","閑門向山路，深柳讀書堂。","幽映每白日，清輝照衣裳。"]', '["道由白云尽，春與青溪长。","时有落花至，远隨流水香。","闲门向山路，深柳读书堂。","幽映每白日，清輝照衣裳。"]', '诗', 'shi', '', NULL, '闕題 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13148989-dfbe-43bf-80dd-55329343c8a2', '寄江滔求孟六遺文', '寄江滔求孟六遺文', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["南望襄陽路，思君情轉親。","偏知漢水廣，應與孟家鄰。","在日貪爲善，昨來聞更貧。","相如有遺草，一爲問家人。"]', '["南望襄陽路，思君情轉親。","偏知漢水廣，應與孟家鄰。","在日貪爲善，昨来闻更貧。","相如有遺草，一爲问家人。"]', '诗', 'shi', '', NULL, '寄江滔求孟六遺文 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c38ec65-f658-4fad-b296-bb4afd7fa182', '積雪爲小山', '積雪爲小山', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["飛雪伴春還，春庭曉自閑。","虛心應任道，遇賞遂成山。","峰小形全秀，巖虛勢莫攀。","以幽能皎潔，謂近可循環。","孤影臨冰境，寒光對玉顏。","不隨遲日盡，留顧歲華間。"]', '["飞雪伴春還，春庭晓自闲。","虛心應任道，遇賞遂成山。","峰小形全秀，巖虛勢莫攀。","以幽能皎潔，謂近可循环。","孤影臨冰境，寒光对玉顏。","不隨遲日尽，留顧歲华间。"]', '诗', 'shi', '', NULL, '積雪爲小山 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2139e79b-f5fc-4ba9-a768-88dbf03c4578', '贈喬琳', '贈喬琳', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["去年上策不見收，今年寄食仍淹留。","羨君有酒能共醉，羨君無錢能不憂。","如今五侯不待客，羨君不問五侯宅。","如今七貴方自尊，羨君不過七貴門。","丈夫會應有知己，世上悠悠何足論。"]', '["去年上策不见收，今年寄食仍淹留。","羨君有酒能共醉，羨君無錢能不憂。","如今五侯不待客，羨君不问五侯宅。","如今七貴方自尊，羨君不過七貴门。","丈夫會應有知己，世上悠悠何足論。"]', '诗', 'shi', '', NULL, '贈喬琳 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67edf4da-dbe3-4d69-a659-71fbc9c6ea28', '茙葵花歌', '茙葵花歌', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["昨日一花開，今日一花開。","今日花正好，昨日花已老。","人生不得長少年，莫惜牀頭酤酒錢。","請君有錢向酒家，君不見茙葵花。"]', '["昨日一花开，今日一花开。","今日花正好，昨日花已老。","人生不得长少年，莫惜牀头酤酒錢。","請君有錢向酒家，君不见茙葵花。"]', '诗', 'shi', '', NULL, '茙葵花歌 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09dd83df-159b-4439-aa5a-fbdd9b27a1a2', '句', '句', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["歸夢如春水，悠悠遶故鄉。","駐馬渡江處，望鄉待歸舟。"]', '["归梦如春水，悠悠遶故乡。","駐马渡江处，望乡待归舟。"]', '诗', 'shi', '', NULL, '句 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccee9a6-bff2-4e78-8968-7ab6ead7c79b', '冬夜宴蕭十丈因餞殷郭二子西上', '冬夜宴蕭十丈因餞殷郭二子西上', '5318b681-c586-49ad-820c-696ff49eac49', '唐', '["有琴斯鳴，于宰之庭。","君子莅止，其心孔平。","政既告成，德以永貞。","鳴琴有衎，于潁之畔。","彼之才髦，其年未冠。","聞詩聞禮，斐兮璨璨。","鳴琴其怡，于潁之湄。","二子翰飛，言戾京師。","有鬱者桂，爰攀其枝。","琴既鳴矣，宵既清矣。","烘煁有煒，酒醴惟旨。","喟我寤歎，吁其別矣。"]', '["有琴斯鳴，于宰之庭。","君子莅止，其心孔平。","政既告成，德以永貞。","鳴琴有衎，于潁之畔。","彼之才髦，其年未冠。","闻诗闻禮，斐兮璨璨。","鳴琴其怡，于潁之湄。","二子翰飞，言戾京師。","有鬱者桂，爰攀其枝。","琴既鳴矣，宵既清矣。","烘煁有煒，酒醴惟旨。","喟我寤歎，吁其別矣。"]', '诗', 'shi', '', NULL, '冬夜宴蕭十丈因餞殷郭二子西上 息夫牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb870b9-66be-4669-bdfe-84c0c75aec34', '蟬鳴一篇五章 一', '蟬鳴一篇五章 一', '9a1ba5f3-0071-47f2-b962-abe09713ba73', '唐', '["蟬其鳴矣，於彼疎桐。","庇影容跡，何所不容。","嘒嘒其長，永託于風。","未見君子，我心仲仲。","既見君子，樂且有融。"]', '["蟬其鳴矣，於彼疎桐。","庇影容跡，何所不容。","嘒嘒其长，永託于风。","未见君子，我心仲仲。","既见君子，乐且有融。"]', '诗', 'shi', '', NULL, '蟬鳴一篇五章 一 宋華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997dbf46-01a7-4a5a-81ac-9549592c95c5', '蟬鳴一篇五章 二', '蟬鳴一篇五章 二', '9a1ba5f3-0071-47f2-b962-abe09713ba73', '唐', '["彼蟬鳴矣，於林之表。","含風飲露，以樂吾道。","有懷載遷，伊誰云保。","未見君子，我心悄悄。","既見君子，披豁予抱。"]', '["彼蟬鳴矣，於林之表。","含风饮露，以乐吾道。","有懷載遷，伊誰云保。","未见君子，我心悄悄。","既见君子，披豁予抱。"]', '诗', 'shi', '', NULL, '蟬鳴一篇五章 二 宋華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246b34c8-2ae8-4ee3-a646-e39b0b31d3bc', '蟬鳴一篇五章 三', '蟬鳴一篇五章 三', '9a1ba5f3-0071-47f2-b962-abe09713ba73', '唐', '["蟬鳴蟬鳴，幽暢乎而。","肅肅爾庭，遠近涼颸。","言赴高柳，叢篁間之。","思而不見，如渴如饑。","亦既覯止，我心則夷。"]', '["蟬鳴蟬鳴，幽暢乎而。","肅肅爾庭，远近涼颸。","言赴高柳，叢篁间之。","思而不见，如渴如饑。","亦既覯止，我心則夷。"]', '诗', 'shi', '', NULL, '蟬鳴一篇五章 三 宋華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a595de9b-2b7e-4ced-91d3-22438a17b776', '蟬鳴一篇五章 四', '蟬鳴一篇五章 四', '9a1ba5f3-0071-47f2-b962-abe09713ba73', '唐', '["蟬鳴伊何，時運未與。","匪歎秋徂，怨斯路阻。","願言莫從，鬱悒誰語。","君子至止，慰我延佇。","何斯違斯，倏爾遐舉。"]', '["蟬鳴伊何，时運未與。","匪歎秋徂，怨斯路阻。","願言莫從，鬱悒誰語。","君子至止，慰我延佇。","何斯違斯，倏爾遐舉。"]', '诗', 'shi', '', NULL, '蟬鳴一篇五章 四 宋華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524d7587-b9db-401a-8f54-ff39bb60eb26', '蟬鳴一篇五章 五', '蟬鳴一篇五章 五', '9a1ba5f3-0071-47f2-b962-abe09713ba73', '唐', '["歲之秋深，蟬其夕吟。","披衣軒除，蕭蕭風林。","我友來斯，言告離衿。","何以敘懷，臨水鳴琴。","何以贈言，委順浮沈。"]', '["歲之秋深，蟬其夕吟。","披衣軒除，蕭蕭风林。","我友来斯，言告離衿。","何以敘懷，臨水鳴琴。","何以贈言，委順浮沈。"]', '诗', 'shi', '', NULL, '蟬鳴一篇五章 五 宋華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40445dd4-db09-43f4-aa1d-9dc31bf14f12', '寄蕭頴士補正字', '寄蕭頴士補正字', 'ab08ea8c-cbbf-4123-9b21-104c05910921', '唐', '["六月度開雲，三峯翫山翠。","爾時黃綬屈，別後青雲致。"]', '["六月度开云，三峯翫山翠。","爾时黄綬屈，別後青云致。"]', '诗', 'shi', '', NULL, '寄蕭頴士補正字 鄒象先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ed119c-c269-4657-b508-ba5a76adff7f', '河中晚霽', '河中晚霽', '626e5e15-317f-44b0-943d-1dd9701da685', '唐', '["湖廣舟自輕，江天欲澄霽。","是時清楚望，氣色猶霾曀。","躑躕金霞白，波上日初麗。","煙紅落鏡中，樹木生天際。","杳杳涯欲斑，濛濛雲復閉。","言垂星漢明，又覩寰瀛勢。","微興從此愜，悠然不知歲。","試歌滄浪清，遂覺乾坤細。","肯念客衣薄，將期永投袂。","遲迴漁父間，一雁聲嘹唳。"]', '["湖廣舟自轻，江天欲澄霽。","是时清楚望，氣色猶霾曀。","躑躕金霞白，波上日初丽。","煙紅落镜中，樹木生天際。","杳杳涯欲斑，濛濛云复閉。","言垂星漢明，又覩寰瀛勢。","微兴從此愜，悠然不知歲。","試歌滄浪清，遂覺乾坤細。","肯念客衣薄，將期永投袂。","遲迴漁父间，一雁声嘹唳。"]', '诗', 'shi', '', NULL, '河中晚霽 韋建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feec88d1-b8bd-4f59-887a-3fb47159da7f', '泊舟盱眙', '泊舟盱眙', '626e5e15-317f-44b0-943d-1dd9701da685', '唐', '["泊舟淮水次，霜降夕流清。","夜久潮浸岸，天寒月近城。","平沙依鴈宿，候館聽雞鳴。","鄉國雲霄外，誰堪羈旅情。"]', '["泊舟淮水次，霜降夕流清。","夜久潮浸岸，天寒月近城。","平沙依鴈宿，候館听雞鳴。","乡国云霄外，誰堪羈旅情。"]', '诗', 'shi', '', NULL, '泊舟盱眙 韋建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87355e28-dc3f-4c8b-8d4c-0f50afe018bb', '銓試後徴山別業寄源侍御', '銓試後徴山別業寄源侍御', '0639f228-1048-48c4-9e4e-d4d0f3c03cdc', '唐', '["別業在徴山，登高望畿甸。","嚴令天地肅，城闕如何見。","藹藹王侯門，華軒日遊衒。","幸逢休明代，山虜尚交戰。","投策去園林，率名皆拜選。","聖君性則哲，濟濟多英彥。","裴楷能清通，山濤急推薦。","謏才甘自屏，薄伎忝餘眷。","雖承國士恩，尚乏中人援。","疇昔相知者，今茲秉天憲。","朱紱何赫赫，繡衣復蔥蒨。"]', '["別業在徴山，登高望畿甸。","嚴令天地肅，城闕如何见。","藹藹王侯门，华軒日游衒。","幸逢休明代，山虜尚交戰。","投策去园林，率名皆拜選。","聖君性則哲，濟濟多英彥。","裴楷能清通，山濤急推薦。","謏才甘自屏，薄伎忝餘眷。","雖承国士恩，尚乏中人援。","疇昔相知者，今茲秉天憲。","朱紱何赫赫，繡衣复蔥蒨。"]', '诗', 'shi', '', NULL, '銓試後徴山別業寄源侍御 殷寅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a534189-aff8-47e9-bb0f-7753350c1087', '玄元皇帝應角賀聖祚無疆', '玄元皇帝應角賀聖祚無疆', '0639f228-1048-48c4-9e4e-d4d0f3c03cdc', '唐', '["應曆生周日，脩祠表漢年。","復茲秦嶺上，更似霍山前。","昔贊神功啓，今符聖祚延。","已題金簡字，仍訪玉堂仙。","睿祖光元始，曾孫體又玄。","言因六夢接，慶叶九齡傳。","北闕心超矣，南山壽固然。","無由同拜慶，竊抃賀陶甄。"]', '["應曆生周日，脩祠表漢年。","复茲秦嶺上，更似霍山前。","昔贊神功啓，今符聖祚延。","已題金簡字，仍訪玉堂仙。","睿祖光元始，曾孫體又玄。","言因六梦接，慶叶九齡傳。","北闕心超矣，南山壽固然。","無由同拜慶，竊抃賀陶甄。"]', '诗', 'shi', '', NULL, '玄元皇帝應角賀聖祚無疆 殷寅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f58fef5-6f8b-41bf-a2b7-9fa46aa0f2e4', '秋怨', '秋怨', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["玉樹起涼煙，凝情一葉前。","別離傷曉鏡，搖落思秋弦。","漢壘關山月，胡笳塞北天。","不知腸斷夢，空遶幾山川。"]', '["玉樹起涼煙，凝情一葉前。","別離傷晓镜，搖落思秋弦。","漢壘关山月，胡笳塞北天。","不知腸斷梦，空遶幾山川。"]', '诗', 'shi', '', NULL, '秋怨 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3778fb-6fe4-470e-9a43-9bf8c78553a7', '春思贈人', '春思贈人', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["紅粉當三五，青娥豔一雙。","綺羅迴錦陌，弦管入花江。","落雁驚金彈，拋杯瀉玉缸。","誰知褐衣客，顦顇在書窗。"]', '["紅粉當三五，青娥豔一雙。","綺羅迴錦陌，弦管入花江。","落雁驚金彈，拋杯瀉玉缸。","誰知褐衣客，顦顇在书窗。"]', '诗', 'shi', '', NULL, '春思贈人 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741e4915-ced6-4295-b445-f84b68644501', '幽院早春', '幽院早春', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["草短花初拆，苔青柳半黃。","隔簾春雨細，高枕曉鶯長。","無事含閑夢，多情識異香。"]', '["草短花初拆，苔青柳半黄。","隔簾春雨細，高枕晓鶯长。","無事含闲梦，多情識異香。"]', '诗', 'shi', '', NULL, '幽院早春 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c4b862-f6f9-43de-9eb7-6465af52b1f5', '寒食戲贈', '寒食戲贈', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["春暮越江邊，春陰寒食天。","杏花香麥粥，柳絮伴鞦韆。","酒是芳菲節，人當桃李年。","不知何處恨，已解入箏弦。"]', '["春暮越江邊，春陰寒食天。","杏花香麦粥，柳絮伴鞦韆。","酒是芳菲節，人當桃李年。","不知何处恨，已解入箏弦。"]', '诗', 'shi', '', NULL, '寒食戲贈 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1629d90-2443-46e1-b8a5-7b394970a827', '聽箏', '听箏', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["抽弦促柱聽秦箏，無限秦人悲怨聲。","似逐春風知柳態，如隨啼鳥識花情。","誰家獨夜愁燈影，何處空樓思月明。","更入幾重離別恨，江南歧路洛陽城。"]', '["抽弦促柱听秦箏，無限秦人悲怨声。","似逐春风知柳態，如隨啼鸟識花情。","誰家独夜愁灯影，何处空楼思月明。","更入幾重離別恨，江南歧路洛陽城。"]', '诗', 'shi', '', NULL, '聽箏 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bec6a44-d780-49de-a561-a8f668da71e0', '河陽橋送別', '河陽橋送別', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["黃河流出有浮橋，晉國歸人此路遙。","若傍闌干千里望，北風驅馬雨蕭蕭。"]', '["黄河流出有浮橋，晉国归人此路遙。","若傍闌干千里望，北风驱马雨蕭蕭。"]', '诗', 'shi', '', NULL, '河陽橋送別 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92dd65da-8301-4c83-b8f3-986b6095c481', '征怨', '征怨', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["歲歲金河復玉關，朝朝馬策與刀環。","三春白雪歸青冢，萬里黃河遶黑山。"]', '["歲歲金河复玉关，朝朝马策與刀环。","三春白雪归青冢，万里黄河遶黑山。"]', '诗', 'shi', '', NULL, '征怨 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218871bc-b14e-44a8-9fde-b9bd347d25c1', '涼州曲二首 一', '涼州曲二首 一', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["關山萬里遠征人，一望關山淚滿巾。","青海戍頭空有月，黃沙磧裏本無春。"]', '["关山万里远征人，一望关山泪满巾。","青海戍头空有月，黄沙磧裏本無春。"]', '诗', 'shi', '', NULL, '涼州曲二首 一 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b70ce0-ac01-482a-b759-a5ffe845852a', '涼州曲二首 二', '涼州曲二首 二', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["高檻連天望武威，窮陰拂地戍金微。","九城弦管聲遙發，一夜關山雪滿飛。"]', '["高檻連天望武威，窮陰拂地戍金微。","九城弦管声遙發，一夜关山雪满飞。"]', '诗', 'shi', '', NULL, '涼州曲二首 二 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead025a2-3925-4777-9236-c089b8ef909c', '江行', '江行', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["繁陰乍隱洲，落葉初飛浦。","蕭蕭楚客帆，暮入寒江雨。"]', '["繁陰乍隐洲，落葉初飞浦。","蕭蕭楚客帆，暮入寒江雨。"]', '诗', 'shi', '', NULL, '江行 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c16400-b46c-4069-9dae-158a4b4e5da2', '丁評事宅秋夜宴集', '丁評事宅秋夜宴集', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["翠幕卷回廊，銀燈開後堂。","風驚擁砌葉，月冷滿庭霜。","綺席人將醉，繁弦夜未央。","共憐今促席，誰道客愁長。"]', '["翠幕卷回廊，銀灯开後堂。","风驚擁砌葉，月冷满庭霜。","綺席人將醉，繁弦夜未央。","共怜今促席，誰道客愁长。"]', '诗', 'shi', '', NULL, '丁評事宅秋夜宴集 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8eb0b23-fb4a-450e-b12f-0f6855549aef', '夜渡江', '夜渡江', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["夜渚帶浮煙，蒼茫晦遠天。","舟輕不覺動，纜急始知牽。","聽笛遙尋岸，聞香暗識蓮。","唯看去帆影，常恐客心懸。"]', '["夜渚带浮煙，蒼茫晦远天。","舟轻不覺动，纜急始知牽。","听笛遙尋岸，闻香暗識蓮。","唯看去帆影，常恐客心懸。"]', '诗', 'shi', '', NULL, '夜渡江 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1d738e-df68-4420-89da-20c14c5fc8a7', '揚子途中', '揚子途中', '6512e777-e20b-47de-b465-8393e793a108', '唐', '["楚塞望蒼然，寒林古戍邊。","秋風人渡水，落日雁飛天。"]', '["楚塞望蒼然，寒林古戍邊。","秋风人渡水，落日雁飞天。"]', '诗', 'shi', '', NULL, '揚子途中 柳中庸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df05a7c-a25e-4bcc-81dd-485f6bffefa3', '宴城東莊', '宴城东莊', 'b1dbaf9e-c4a2-4528-b83a-c0c457c6448d', '唐', '["一月主人笑幾回，相逢相識且銜杯。","眼看春色如流水，今日殘花昨日開。"]', '["一月主人笑幾回，相逢相識且銜杯。","眼看春色如流水，今日殘花昨日开。"]', '诗', 'shi', '', NULL, '宴城東莊 崔惠童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac916bbf-b5f6-4879-941a-0b4ce20603ac', '宴城東莊', '宴城东莊', '53fb649a-7571-4674-b74d-54c3a2127bff', '唐', '["一年始有一年春，百歲曾無百歲人。","能向花前幾回醉，十千沽酒莫辭貧。"]', '["一年始有一年春，百歲曾無百歲人。","能向花前幾回醉，十千沽酒莫辞貧。"]', '诗', 'shi', '', NULL, '宴城東莊 崔敏童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3c68c1-2a48-4f7a-9e13-e0fa27179875', '奉和聖制早登太行山中言志', '奉和聖制早登太行山中言志', '9554339e-918d-4b20-8d13-d3dfe7440fb6', '唐', '["金吾戒道清，羽騎動天聲。","砥路方南絕，重巖始北征。","關樓前望遠，河邑下觀平。","喜氣迴輿合，祥風入斾輕。","祝堯三老至，會禹百神迎。","月令農先急，春蒐禮復行。","仍親后土祭，更理晉陽兵。","不似勞車轍，空留八駿名。"]', '["金吾戒道清，羽騎动天声。","砥路方南絕，重巖始北征。","关楼前望远，河邑下观平。","喜氣迴輿合，祥风入斾轻。","祝堯三老至，會禹百神迎。","月令農先急，春蒐禮复行。","仍親后土祭，更理晉陽兵。","不似勞车轍，空留八駿名。"]', '诗', 'shi', '', NULL, '奉和聖制早登太行山中言志 苗晉卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a833a7e3-13da-49f1-83eb-4b3db1dab38d', '賦虞書歌', '賦虞书歌', 'fbf46a89-3b67-45d2-99de-4037d1a1904c', '唐', '["衆書之中虞書巧，體法自然歸大道。","不同懷素只攻顛，豈類張芝惟創草。","形勢素，筋骨老，父子君臣相揖抱。","孤青似竹更颼颸，闊白如波長浩渺。","能方正，不隳倒，功夫未至難尋奧。","須知孔子廟堂碑，便是青箱中至寶。"]', '["衆书之中虞书巧，體法自然归大道。","不同懷素只攻顛，豈類張芝惟創草。","形勢素，筋骨老，父子君臣相揖抱。","孤青似竹更颼颸，闊白如波长浩渺。","能方正，不隳倒，功夫未至难尋奧。","須知孔子廟堂碑，便是青箱中至寶。"]', '诗', 'shi', '', NULL, '賦虞書歌 賈躭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d94bd5-d2ab-4fc2-8899-4cd3a5fca059', '雲門山投龍詩', '云门山投龙诗', 'be6ef3fa-1bf2-44c9-a66f-dd1c7cce820f', '唐', '["曉登雲門山，直上一千尺。","絕頂彌孤聳，盤途幾傾窄。","前對豎裂峯，下臨削成壁。","陽巘靈芝秀，陰崖半天赤。","大壑靜不波，渺溟無際極。","是時雪初霽，冱寒水更積。","披展送龍儀，寧安服狐白。","沛恩惟聖主，祈福在方伯。","三元章醮昇，五域囗囗覿。","帟幕翠微亙，機茵丹洞闢。","祝起鳴天鼓，拜傳端素冊。","霞間朱紱縈，嵐際黃裳襞。","玉策奉誠信，仙佩俟奔驛。","香氣入岫門，瑞雲出巖石。","至誠必招感，大福旋來格。","空中忽神言，帝壽萬千百。"]', '["晓登云门山，直上一千尺。","絕頂彌孤聳，盤途幾傾窄。","前对豎裂峯，下臨削成壁。","陽巘靈芝秀，陰崖半天赤。","大壑静不波，渺溟無際極。","是时雪初霽，冱寒水更積。","披展送龙儀，寧安服狐白。","沛恩惟聖主，祈福在方伯。","三元章醮昇，五域囗囗覿。","帟幕翠微亙，機茵丹洞闢。","祝起鳴天鼓，拜傳端素冊。","霞间朱紱縈，嵐際黄裳襞。","玉策奉誠信，仙佩俟奔驛。","香氣入岫门，瑞云出巖石。","至誠必招感，大福旋来格。","空中忽神言，帝壽万千百。"]', '诗', 'shi', '', NULL, '雲門山投龍詩 趙居貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('500dd912-d70f-4a29-a1e6-fbdd7741e138', '扈從迴鑾應制', '扈從迴鑾應制', 'cfc9fd92-aa3a-4d02-aae7-e869886107c4', '唐', '["粵在秦京日，議乎封禪難。","豈知陶唐主，道濟蒼生安。","惟彼烈祖事，增修實榮觀。","聲名朝萬國，玉帛禮三壇。","纂聖德重光，建元功載刊。","仍開舊馳道，不記昔迴鑾。","羽衛搖晴日，弓戈生早寒。","猶思檢玉處，却望白雲端。"]', '["粵在秦京日，議乎封禪难。","豈知陶唐主，道濟蒼生安。","惟彼烈祖事，增修實榮观。","声名朝万国，玉帛禮三壇。","纂聖德重光，建元功載刊。","仍开旧驰道，不記昔迴鑾。","羽衛搖晴日，弓戈生早寒。","猶思檢玉处，却望白云端。"]', '诗', 'shi', '', NULL, '扈從迴鑾應制 蕭華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd788508-d06e-4c46-9222-c899b5487f81', '西河郡太原守張夫人輓歌', '西河郡太原守張夫人輓歌', '498d4211-e7d4-4a84-a002-1bb37476c550', '唐', '["鵲印慶仍傳，魚軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龍是雙歸日，鸞非獨舞年。","哀榮今共盡，悽愴杜陵田。"]', '["鵲印慶仍傳，鱼軒寵莫先。","從夫元凱貴，訓子孟軻賢。","龙是雙归日，鸾非独舞年。","哀榮今共尽，悽愴杜陵田。"]', '诗', 'shi', '', NULL, '西河郡太原守張夫人輓歌 李岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a26c7f6d-fcc0-4142-a208-042a43622480', '玄元皇帝應見賀聖祚無疆', '玄元皇帝應见賀聖祚無疆', '498d4211-e7d4-4a84-a002-1bb37476c550', '唐', '["皇綱歸有道，帝系祖玄元。","運表南山祚，神通北極尊。","大同齊日月，興廢應乾坤。","聖后趨庭禮，宗臣稽首言。","千官欣肆觀，萬國賀深恩。","錫宴雲天接，飛聲雷地喧。","祥光浮紫閣，喜氣繞皇軒。","未預承天命，空勤望帝門。"]', '["皇綱归有道，帝系祖玄元。","運表南山祚，神通北極尊。","大同齊日月，兴廢應乾坤。","聖后趨庭禮，宗臣稽首言。","千官欣肆观，万国賀深恩。","錫宴云天接，飞声雷地喧。","祥光浮紫閣，喜氣繞皇軒。","未預承天命，空勤望帝门。"]', '诗', 'shi', '', NULL, '玄元皇帝應見賀聖祚無疆 李岑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e57ab2-c932-4965-8aeb-61b29cd04ea7', '復游浯溪', '复游浯溪', '97a28a2f-8b3c-4873-9771-003a06315a54', '唐', '["昔到纔三歲，今來鬢已蒼。","剝苔看篆字，薙草覓書堂。","引客登臺上，呼童掃樹旁。","石渠疏擁水，門徑斸藂篁。","田地潛更主，林園盡廢荒。","悲涼問耆耋，疆界指垂楊。"]', '["昔到纔三歲，今来鬢已蒼。","剝苔看篆字，薙草覓书堂。","引客登台上，呼童掃樹旁。","石渠疏擁水，门徑斸藂篁。","田地潛更主，林园尽廢荒。","悲涼问耆耋，疆界指垂楊。"]', '诗', 'shi', '', NULL, '復游浯溪 元友讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4a5f1d-9f6a-4c43-b3b6-b50266cc484c', '南溪別業', '南溪別業', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["結宇依青嶂，開軒對綠疇。","樹交花兩色，溪合水同流。","竹徑春來掃，蘭尊夜不收。","逍遙自得意，鼓腹醉中遊。"]', '["結宇依青嶂，开軒对綠疇。","樹交花兩色，溪合水同流。","竹徑春来掃，蘭尊夜不收。","逍遙自得意，鼓腹醉中游。"]', '诗', 'shi', '', NULL, '南溪別業 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df01972d-f851-4b0f-bbd5-9e57be874eb6', '古意', '古意', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["冉冉紅羅帳，開君玉樓上。","畫作同心鳥，銜花兩相向。","春風正可憐，吹暎綠窗前。","妾意空相感，君心何處邊。"]', '["冉冉紅羅帳，开君玉楼上。","畫作同心鸟，銜花兩相向。","春风正可怜，吹暎綠窗前。","妾意空相感，君心何处邊。"]', '诗', 'shi', '', NULL, '古意 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbae9e83-1d83-491a-8b71-fe64540692c6', '臺中書懷', '台中书懷', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["持憲當休明，飭躬免顛沛。","直繩備豪右，正色清冠蓋。","寄切才恨薄，職雄班匪大。","坐居三獨中，立在百僚外。","簡牘時休暇，依然秋興多。","披書唯骨鯁，循跡少閑和。","庭樹凌霜柏，池傾萎露荷。","歲寒應可見，感此遂成歌。"]', '["持憲當休明，飭躬免顛沛。","直繩備豪右，正色清冠蓋。","寄切才恨薄，職雄班匪大。","坐居三独中，立在百僚外。","簡牘时休暇，依然秋兴多。","披书唯骨鯁，循跡少闲和。","庭樹凌霜柏，池傾萎露荷。","歲寒應可见，感此遂成歌。"]', '诗', 'shi', '', NULL, '臺中書懷 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0dc1af7-c04b-47b3-a488-a60082869b1b', '經埋輪地', '經埋輪地', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["漢家張御史，晉國綠珠樓。","時代邈已遠，共謝洛陽秋。","洛陽大道邊，舊地尚依然。","下馬獨太息，擾擾城市喧。","時人欣綠珠，詩滿金谷圓。","千載埋輪地，無人興一言。","正直死猶忌，況乃未死前。","汨羅有飜浪，恐是嫌屈原。","我聞太古水，上與天相連。","如何一落地，又作九曲泉。","萬古惟高步，可以旌我賢。"]', '["漢家張御史，晉国綠珠楼。","时代邈已远，共謝洛陽秋。","洛陽大道邊，旧地尚依然。","下马独太息，擾擾城市喧。","时人欣綠珠，诗满金谷圓。","千載埋輪地，無人兴一言。","正直死猶忌，況乃未死前。","汨羅有飜浪，恐是嫌屈原。","我闻太古水，上與天相連。","如何一落地，又作九曲泉。","万古惟高步，可以旌我賢。"]', '诗', 'shi', '', NULL, '經埋輪地 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c6ca3cc-dcd9-4b6c-af3c-11b7bc8ad15e', '山行見鵲巢', '山行见鵲巢', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["鵲巢性本高，更在西山木。","朝下清泉戲，夜近明月宿。","非直避網羅，兼能免傾覆。","豈憂五陵子，挾彈來相逐。"]', '["鵲巢性本高，更在西山木。","朝下清泉戲，夜近明月宿。","非直避網羅，兼能免傾覆。","豈憂五陵子，挾彈来相逐。"]', '诗', 'shi', '', NULL, '山行見鵲巢 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22bb299-e951-445a-8926-46d406d65136', '巫山之陽香谿之陰明妃神女舊跡存焉', '巫山之陽香谿之陰明妃神女旧跡存焉', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["神女歸巫峽，明妃入漢宮。","搗衣餘石在，薦枕舊室空。","行雨有時度，谿流何日窮。","至今詞賦裏，淒愴寫遺風。"]', '["神女归巫峽，明妃入漢宮。","捣衣餘石在，薦枕旧室空。","行雨有时度，谿流何日窮。","至今词賦裏，淒愴寫遺风。"]', '诗', 'shi', '', NULL, '巫山之陽香谿之陰明妃神女舊跡存焉 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272c9e8c-5d6f-4e20-b8d6-e7c8a30b8915', '夜飛鵲', '夜飞鵲', 'f9414968-ec74-4d04-9d1f-33ba638b94b0', '唐', '["北林夜方久，南月影頻移。","何啻飛三匝，猶言未得枝。"]', '["北林夜方久，南月影頻移。","何啻飞三匝，猶言未得枝。"]', '诗', 'shi', '', NULL, '夜飛鵲 蔣冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13db9634-9391-4c27-b732-15022d699ece', '途次維揚望京口寄白下諸公', '途次維揚望京口寄白下諸公', 'c11e9e2e-0f9b-4c48-ae97-ab1ada720fe6', '唐', '["北望情何限，南行路轉深。","晚帆低荻葉，寒日下楓林。","雲白蘭陵渚，煙青建業岑。","江天秋向盡，無處不傷心。"]', '["北望情何限，南行路轉深。","晚帆低荻葉，寒日下楓林。","云白蘭陵渚，煙青建業岑。","江天秋向尽，無处不傷心。"]', '诗', 'shi', '', NULL, '途次維揚望京口寄白下諸公 蔣渙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ed1ce5e-d66c-448d-a501-05d2930952d4', '登栖霞寺塔', '登栖霞寺塔', 'c11e9e2e-0f9b-4c48-ae97-ab1ada720fe6', '唐', '["三休尋磴道，九折步雲霓。","瀍澗臨江北，郊原極海西。","沙平瓜步出，樹遠綠楊低。","南指晴天外，青峯是會稽。"]', '["三休尋磴道，九折步云霓。","瀍澗臨江北，郊原極海西。","沙平瓜步出，樹远綠楊低。","南指晴天外，青峯是會稽。"]', '诗', 'shi', '', NULL, '登栖霞寺塔 蔣渙 shi');
